function formatDev(v){return Number.isInteger(v)?String(v):Number(v).toFixed(Math.abs(v)<.1?3:2).replace(/0+$/,'').replace(/\.$/,'');}
function renderDevPanel(){
  const root=document.getElementById("devTuningControls");
  if(!root)return;
  gdRenderPermissionsAdmin();
  gdRenderLaunchMonitorAdmin();
  gdRenderAdminVisualSettings();
  gdRenderAdminCourseDatabase();
  gdRenderCoursePlayPipelineDebug();
  try{window.GDCourseMappingDebug?.renderAdminPanel?.();}catch(e){}
  root.innerHTML="";
  const groups=Object.keys(DEV_DEFS).sort((a,b)=>DEV_DEFS[a].label.localeCompare(DEV_DEFS[b].label));
  if(!groups.includes(activeDevGroup))activeDevGroup=groups[0];
  const picker=document.createElement("div");
  picker.className="devGroupSelect";
  picker.innerHTML=`<label for="gdDevGroupSelect">Developer setting group</label><select id="gdDevGroupSelect">${groups.map(group=>`<option value="${group}" ${group===activeDevGroup?"selected":""}>${gdEscapeHTML(DEV_DEFS[group].label)}</option>`).join("")}</select>`;
  root.appendChild(picker);
  const group=activeDevGroup;
  const box=document.createElement("div");box.className="devGroup";
  box.innerHTML=`<h3>${DEV_DEFS[group].label}</h3><p>${DEV_DEFS[group].desc}</p>`;
  Object.keys(DEV_FIELDS).filter(k=>k.startsWith(group+".")).sort((a,b)=>DEV_FIELDS[a].label.localeCompare(DEV_FIELDS[b].label)).forEach(path=>{
    const f=DEV_FIELDS[path], cur=dev(path), def=devDefault(path), delta=Number(cur)-Number(def), changed=Math.abs(delta)>1e-9;
    const row=document.createElement("div");row.className="devTune";
    row.innerHTML=`<div><label>${f.label}</label><small>${f.help||""}</small></div><input type="number" min="${f.min}" max="${f.max}" step="${f.step}" value="${cur}" data-dev-path="${path}"><div class="devMeta"><span>Default ${formatDev(def)}${f.unit||""}</span><span>Current ${formatDev(cur)}${f.unit||""}</span><span class="${changed?'changed':''}">Δ ${delta>=0?'+':''}${formatDev(delta)}${f.unit||""}</span></div>`;
    box.appendChild(row);
  });
  const reset=document.createElement("button");reset.className="devResetSmall";reset.textContent=`Reset ${DEV_DEFS[group].label}`;reset.onclick=()=>resetDevSettings(group);box.appendChild(reset);
  root.appendChild(box);
  const select=root.querySelector("#gdDevGroupSelect");
  if(select)select.onchange=()=>{activeDevGroup=select.value;gdSafeLocalSet("golf_daddy_active_dev_group",activeDevGroup);renderDevPanel();};
  root.querySelectorAll("input[data-dev-path]").forEach(input=>{
    input.onchange=()=>{let v=Number(input.value);const f=DEV_FIELDS[input.dataset.devPath];if(!Number.isFinite(v))v=devDefault(input.dataset.devPath);v=Math.max(f.min,Math.min(f.max,v));setDev(input.dataset.devPath,v);};
  });
}
