function gdLmMetric(rawLabel,candidateMetric,value,unit="m",confidence=.84){
  return {rawLabel,candidateMetric,rawValue:String(value),value,unit,confidence};
}
function gdLmMetricListHasMetric(metrics,key){
  const wanted=String(key||"").trim().toLowerCase();
  return (Array.isArray(metrics)?metrics:[]).some(metric=>String(metric?.candidateMetric||metric?.rawLabel||"").trim().toLowerCase()===wanted);
}
