function gdLmParseNumber(value,key=""){
  const raw=String(value??"").trim();
  if(!raw||/^[-=—–]+$/.test(raw))return NaN;
  if(/[A-KM-QS-Z]/i.test(raw.replace(/[Oo]/g,"").replace(/[°º]/g,"")))return NaN;
  let text=raw.replace(/[−–—]/g,"-").replace(/[Oo]/g,"0").replace(/[^0-9,.\-+]/g,"");
  if(!text||/^[-+.]$/.test(text))return NaN;
  const hasDecimal=/[,.]/.test(text);
  if(text.includes(",")&&!text.includes("."))text=text.replace(/,/g,".");
  else if(text.includes(",")&&text.includes("."))text=text.replace(/,/g,"");
  let n=Number(text);
  if(!Number.isFinite(n))return NaN;
  const abs=Math.abs(n);
  const k=String(key||"");
  if(!hasDecimal){
    if(["clubSpeed","ballSpeed"].includes(k)&&abs>=400&&abs<=1900)n=n/10;
    else if(k==="offline"&&abs>=30&&abs<300)n=n/10;
    else if(["carry","total"].includes(k)&&abs>=380&&abs<3300)n=n/10;
    else if(["attackAngle","sideAngle","launchDirection","spinAxis","faceToPath","swingDirection","clubPath","faceAngle","dynamicLoft","launch","descent"].includes(k)&&abs>=10&&abs<900)n=n/10;
    else if(k==="smashFactor"&&abs>=80&&abs<220)n=n/100;
  }
  return n;
}
function gdLmMetricPlausible(key,value){
  const n=Number(value);
  if(!Number.isFinite(n))return false;
  const abs=Math.abs(n);
  if(key==="ballSpeed")return n>=40&&n<=190;
  if(key==="carry")return n>=20&&n<=260;
  if(key==="total")return n>=20&&n<=300;
  if(key==="offline")return abs<=80;
  if(key==="launch")return n>=-5&&n<=45;
  if(key==="sideAngle")return abs<=25;
  if(key==="descent")return n>=5&&n<=65;
  if(key==="peakHeight")return n>=1&&n<=80;
  if(key==="backspin")return n>=1000&&n<=12000;
  if(key==="sideSpin")return abs<=2500;
  return true;
}
