function gdLmClubFromLine(line,opts={}){
  const noisy=gdLmNoisyClubFromText(line);
  if(noisy)return noisy;
  const compact=String(line||"").trim().toLowerCase().replace(/[^0-9a-z|!\[\](){}]/g,"");
  const ocrIron=compact.match(/^([2-9])(?:i|l|1|!|\||\[|\]|\(|\)|\{|\})$/);
  if(ocrIron)return `${ocrIron[1]}i`;
  const ironGlyph=line.match(/(?:^|\s)([2-9])\s*[il1](?:\s|$)/i);
  if(ironGlyph)return `${ironGlyph[1]}i`;
  const degree=line.match(/(?:^|\s)((?:4[6-9]|5[0-9]|6[0-4])\s*(?:°|deg))(?:\s|$)/i);
  if(degree&&!opts.ignoreDegree)return degree[1].replace(/\s+/g,"");
  const match=line.match(/\b(driver|dr|1w|2w|3w|4w|5w|7w|[2-9]\s*h|[2-9]\s*(?:i|iron)|pw|gw|aw|sw|lw|wedge|putter)\b/i);
  if(!match)return "";
  const raw=match[1].replace(/\s+/g,"").toLowerCase();
  if(/^(?:pw|gw|aw|sw|lw|wedge|putter)$/.test(raw)){
    const before=String(line||"").slice(0,Number(match.index)||0);
    const after=String(line||"").slice((Number(match.index)||0)+String(match[0]||"").length);
    if(/\b\d*[2-9]\d*\b/.test(`${before} ${after}`))return "";
  }
  if(raw==="driver"||raw==="dr"||raw==="1w")return "Driver";
  if(raw==="wedge")return "Wedge";
  const hybrid=raw.match(/^([2-9])h$/);
  if(hybrid)return `${hybrid[1]}h`;
  const iron=raw.match(/^([2-9])(?:i|iron)$/);
  if(iron)return `${iron[1]}i`;
  return raw.replace("iron","i").toUpperCase();
}
