let gdPracticeExtractionPreviewState=null;
function gdPracticeMetricValue(group,names){
  const metrics=Array.isArray(group?.metrics)?group.metrics:[];
  const expanded=(Array.isArray(names)?names:[names]).flatMap(name=>gdLmMetricNamesForKey(name));
  const keys=expanded.map(name=>String(name||"").trim().toLowerCase());
  for(const metric of metrics){
    const raw=String(metric?.rawLabel||"").trim().toLowerCase();
    const candidate=String(metric?.candidateMetric||"").trim().toLowerCase();
    if(keys.includes(raw)||keys.includes(candidate)){
      const value=Number(metric?.value);
      if(Number.isFinite(value))return value;
    }
  }
  return null;
}
function gdPracticeMetricDisplay(value,suffix="",decimals=1){
  // Number(null) is 0 — a MISSING metric must show "-", not a fake "0.0".
  if(value==null||value==="")return "-";
  const n=Number(value);
  if(!Number.isFinite(n))return "-";
  const abs=Math.abs(n);
  const places=abs>=100?0:decimals;
  return `${n.toFixed(places)}${suffix}`;
}
function gdPracticeExtractionRows(payload){
  const groups=Array.isArray(payload?.clubGroups)?payload.clubGroups:[];
  return groups.map((group,index)=>{
    const carry=gdPracticeMetricValue(group,"carry");
    const offline=gdPracticeMetricValue(group,"offline");
    const sideAngle=gdPracticeMetricValue(group,"sideAngle");
    const launchDirection=gdPracticeMetricValue(group,"launchDirection");
    const faceToPath=gdPracticeMetricValue(group,"faceToPath");
    const clubPath=gdPracticeMetricValue(group,"clubPath");
    const faceAngle=gdPracticeMetricValue(group,"faceAngle");
    const spinAxis=gdPracticeMetricValue(group,"spinAxis");
    const smash=gdPracticeMetricValue(group,"smashFactor");
    const launch=gdPracticeMetricValue(group,"launch");
    const dynamicLoft=gdPracticeMetricValue(group,"dynamicLoft");
    const ballSpeed=gdPracticeMetricValue(group,"ballSpeed");
    const total=gdPracticeMetricValue(group,"total");
    const backspin=gdPracticeMetricValue(group,"backspin");
    const sideSpin=gdPracticeMetricValue(group,"sideSpin");
    const descent=gdPracticeMetricValue(group,["descentAngle","descent","land angle"]);
    const peak=gdPracticeMetricValue(group,["peakHeight","peak","height"]);
    const totalSpin=gdPracticeMetricValue(group,["totalSpin","spin","spin rate"]);
    const club=String(group?.candidateClub||group?.originClubLabel||"Unknown").trim()||"Unknown";
    // Same Number(null)=0 trap as the display: a null metric must count as
    // MISSING, or absent carry/direction rows are marked "ready" with 0 flags.
    const present=v=>v!=null&&Number.isFinite(Number(v));
    const missing=[];
    if(!present(carry))missing.push("carry");
    const hasBallDirection=present(offline)||present(sideAngle)||present(launchDirection)||present(spinAxis);
    if(!hasBallDirection)missing.push("ball direction");
    return {index:index+1,club,ballSpeed,launch,sideAngle,backspin,sideSpin,descent,offline,peak,carry,total,launchDirection,faceToPath,clubPath,faceAngle,spinAxis,smash,dynamicLoft,totalSpin,missing};
  });
}
function gdPracticeSetExtractionPreview(payload,sourceLabel){
  const rows=gdPracticeExtractionRows(payload);
  gdPracticeExtractionPreviewState={payload,sourceLabel:sourceLabel||payload?.label||"Practice extraction",rows,createdAt:Date.now()};
  gdRenderPracticeExtractionCheckpoint();
  if(gdPracticeAdminIsOpenSafe()){
    gdLmSetStatus("Status","Extraction ready",`${rows.length} shots waiting in Practice Admin checkpoint`,"needs_more_data");
    gdLmToast(`Extraction checkpoint ready (${rows.length} shots)`);
  }
}
