function gdRenderPracticeExtractionCheckpoint(){
  const root=document.getElementById("gdPracticeExtractCheckpoint");
  if(!root)return;
  const state=gdPracticeExtractionPreviewState;
  const show=!!(state&&gdPracticeAdminIsOpenSafe()&&gdPracticeToleranceCanEditSafe());
  root.hidden=!show;
  if(!show){
    root.innerHTML="";
    return;
  }
  const rows=Array.isArray(state.rows)?state.rows:[];
  const good=rows.filter(row=>!row.missing.length).length;
  const missing=rows.length-good;
  const columns=[
    ["#","index",""],
    ["Club","club",""],
    ["Ball","ballSpeed","mph"],
    ["Launch","launch","°"],
    ["Side Ang","sideAngle","°"],
    ["Backspin","backspin",""],
    ["SideSpin","sideSpin",""],
    ["SpinAxis","spinAxis","°"],
    ["Descent","descent","°"],
    ["Offline","offline","m"],
    ["Peak","peak","m"],
    ["Carry","carry","m"],
    ["Total","total","m"]
  ];
  const head=columns.map(column=>`<b>${gdEscapeHTML(column[0])}</b>`).join("");
  const body=rows.map(row=>{
    const tone=row.missing.length?"warn":"good";
    const missingText=row.missing.length?`Missing ${row.missing.join(", ")}`:"Ready";
    const cells=columns.map(([label,key,suffix])=>{
      if(key==="index")return `<span>${row.index}</span>`;
      if(key==="club")return `<strong>${gdEscapeHTML(row.club)}</strong>`;
      const decimals=["backspin","sideSpin"].includes(key)?0:1;
      return `<b>${gdEscapeHTML(gdPracticeMetricDisplay(row[key],suffix,decimals))}</b>`;
    }).join("");
    return `<div class="gdPracticeExtractRow ${tone}">
      ${cells}
      <em>${gdEscapeHTML(missingText)}</em>
    </div>`;
  }).join("");
  root.innerHTML=`<div class="gdPracticeExtractHead">
    <div><strong>Extraction checkpoint</strong><span>${gdEscapeHTML(state.sourceLabel||"Practice extraction")} · compare this list against the original before importing.</span></div>
    <div class="gdPracticeExtractStats"><b>${rows.length} shots</b><b>${good} ready</b><b>${missing} flags</b></div>
  </div>
  <div class="gdPracticeExtractActions"><button type="button" onclick="gdPracticeClearExtractionPreview()">Clear</button><button class="primary" type="button" onclick="gdImportPracticeExtractionPreview()">Import these shots</button></div>
  <div class="gdPracticeExtractList"><div class="gdPracticeExtractRow gdPracticeExtractHeader">${head}<em>Status</em></div>${body||'<div class="gdShotAdminEmpty">No extracted shots waiting.</div>'}</div>`;
}
