  if(items.length<2)return null;
  const band=Math.max(2,Math.ceil(items.length*.28));
  const top=gdValueClusterMedianPoint(items.slice(0,band),item=>({x:item.word.cx,y:item.word.cy}));
  const bottom=gdValueClusterMedianPoint(items.slice(-band),item=>({x:item.word.cx,y:item.word.cy}));
