  const buffer=gdValueClusterShapeBuffer(width,height,colGap,rowGap);
  const bufferX=buffer.x;
  const bufferY=buffer.y;
  const xs=points.flatMap(point=>[point.x]).concat(values.flatMap(word=>[word.x0,word.x1])).map(Number).filter(Number.isFinite);
  const ys=points.flatMap(point=>[point.y]).concat(values.flatMap(word=>[word.y0,word.y1])).map(Number).filter(Number.isFinite);
  if(!xs.length||!ys.length)return null;
  const x0=Math.max(0,Math.min(...xs)-bufferX);
  const y0=Math.max(0,Math.min(...ys)-bufferY);
  const x1=Math.min(width,Math.max(...xs)+bufferX);
  const y1=Math.min(height,Math.max(...ys)+bufferY);
