  boxes.forEach(box=>{
    let best=null,bestDistance=Infinity;
    tracks.forEach(track=>{
      const distance=Math.abs(track.cx-Number(box.cx));
      if(distance<tolerance&&distance<bestDistance){
        best=track;
        bestDistance=distance;
      }
    });
    if(!best){
      best={cx:Number(box.cx),boxes:[]};
      tracks.push(best);
    }
    best.boxes.push(box);
    best.cx=gdValueClusterMedian(best.boxes.map(item=>Number(item.cx)))||best.cx;
  });
