    lines:[],
    results:[],
    sourceCanvas:source,
    preparedCanvas:source,
    directColumnSource:source,
    fullTableCanvas:checkpoint?.source||checkpoint?.fullTableSource||null,
    valueCluster:null,
    flatTableFailure:failure,
