      rowIndex:index,
      cy:row.cy,
      top:Math.max(0,top),
      bottom:Math.min(height,bottom),
      x0:Number.isFinite(Number(row.valueX0))?Number(row.valueX0):row.x0,
      x1:Number.isFinite(Number(row.valueX1))?Number(row.valueX1):row.x1,
      count:row.count,
      valueBoxCount:Number(row.valueBoxCount)||0,
      detected:true
