function gdCanvasToDataUrl(canvas){
  if(!canvas)return "";
  try{return canvas.toDataURL("image/png");}catch(e){return "";}
}
function gdMaskNumberPreviewCanvas(source,mask){
  const width=Number(source?.width)||0;
  const height=Number(source?.height)||0;
  if(!source||width<2||height<2)return source||null;
  const canvas=document.createElement("canvas");
  canvas.width=width;
  canvas.height=height;
  const ctx=canvas.getContext("2d",{willReadFrequently:true});
  ctx.drawImage(source,0,0,width,height);
  if(mask&&Number.isFinite(Number(mask.x0))&&Number.isFinite(Number(mask.y0))&&Number.isFinite(Number(mask.x1))&&Number.isFinite(Number(mask.y1))){
    const x0=Math.max(0,Math.min(width,Math.round(Number(mask.x0))));
    const y0=Math.max(0,Math.min(height,Math.round(Number(mask.y0))));
    const x1=Math.max(0,Math.min(width,Math.round(Number(mask.x1))));
    const y1=Math.max(0,Math.min(height,Math.round(Number(mask.y1))));
    ctx.fillStyle="rgba(255,184,74,.33)";
    ctx.fillRect(x0,y0,Math.max(1,x1-x0),Math.max(1,y1-y0));
    ctx.strokeStyle="rgba(255,184,74,.95)";
    ctx.lineWidth=Math.max(1,Math.round(Math.min(width,height)*.025));
    ctx.strokeRect(x0+.5,y0+.5,Math.max(1,x1-x0-1),Math.max(1,y1-y0-1));
  }
  return canvas;
}
function gdAppendMaskDirectionStage(parent,label,canvas,caption){
  const stage=document.createElement("div");
  stage.className="gdMaskDirectionStage";
  const title=document.createElement("strong");
  title.textContent=label;
  stage.append(title);
  if(canvas){
    const img=document.createElement("img");
    img.alt=label;
    const url=gdCanvasToDataUrl(canvas);
    if(url)img.src=url;
    stage.append(img);
  }
  const text=document.createElement("span");
  text.textContent=caption||"";
  stage.append(text);
  parent.append(stage);
}
function gdMaskDirectionFinalValue(raw,direction){
  const number=String(raw||"").trim();
  const dir=String(direction||"").trim().toUpperCase();
  if(!number)return dir?`?${dir}`:"?";
  return dir?`${number}${dir}`:`${number}?`;
}
function gdRenderMaskDirectionCards(title,entries,limit=90){
  const list=document.getElementById("gdPracticeScanDebugList");
  if(!list||!entries.length)return;
  const details=document.createElement("details");
  details.className="gdColumnImagePreview gdMaskDirectionPreview";
  details.open=false;
  const summary=document.createElement("summary");
  const resolved=entries.filter(entry=>entry.direction&&entry.trusted).length;
  const review=entries.length-resolved;
  summary.textContent=`${title} (${entries.length} cells · ${resolved} resolved · ${review} need review · masked rest)`;
  const helper=document.createElement("div");
  helper.className="gdLRExperimentMeta";
  helper.textContent="Mask-number method: read the number first, erase its box from the full value box, then scan the remaining full masked value box for L/R.";
  const grid=document.createElement("div");
  grid.className="gdMaskDirectionGrid";
  entries.slice(0,limit).forEach(entry=>{
    const card=document.createElement("div");
    card.className="gdMaskDirectionCard";
    card.dataset.direction=entry.direction||"-";
    card.dataset.trusted=entry.trusted?"true":"false";
    const head=document.createElement("div");
    head.className="gdMaskDirectionCardHead";
    const left=document.createElement("span");
    left.textContent=`${entry.key} r${entry.row}`;
    const right=document.createElement("small");
    right.textContent=entry.direction?`${entry.direction}${entry.trusted?" ok":" ?"}`:"direction missing";
    head.append(left,right);
    const steps=document.createElement("div");
    steps.className="gdMaskDirectionSteps";
    const restView=entry.restCanvas||entry.fullMaskedCanvas;
    gdAppendMaskDirectionStage(steps,"Original",entry.originalCanvas,entry.raw?`number read: ${entry.raw}`:"number missing");
    gdAppendMaskDirectionStage(steps,"Number Mask",entry.maskCanvas,entry.mask?"number area marked for removal":"number box unavailable");
    gdAppendMaskDirectionStage(steps,"Rest after mask",restView,entry.direction?`remainder found ${entry.direction}`:"remainder found no L/R");
    gdAppendMaskDirectionStage(steps,"Result",entry.restCanvas,entry.direction?`L/R found: ${entry.direction}`:"needs review");
    const result=document.createElement("div");
    result.className="gdMaskDirectionResult";
    const final=gdMaskDirectionFinalValue(entry.raw,entry.direction);
    result.innerHTML=`Final: <b>${final}</b> · ${entry.direction?"mask remainder checked":"<span class='warn'>direction missing — review needed</span>"}`;
    card.append(head,steps,result);
    grid.append(card);
  });
  details.append(summary,helper,grid);
  list.append(details);
}
