function gdValueCorridorStripResults(scanImage,columns,valueCluster){
  const width=Number(scanImage?.width)||0;
  const height=Number(scanImage?.height)||0;
  if(!scanImage||width<10||height<10)return [];
  const rows=Array.isArray(valueCluster?.rowBands)?valueCluster.rowBands:[];
  const topCandidates=rows.map(row=>Number(row.top)).filter(Number.isFinite);
  const bottomCandidates=rows.map(row=>Number(row.bottom)).filter(Number.isFinite);
  const top=topCandidates.length?Math.max(0,Math.min(...topCandidates)):Math.max(0,height*.06);
  const bottom=bottomCandidates.length?Math.min(height,Math.max(...bottomCandidates)):Math.min(height,height*.96);
  return (Array.isArray(columns)?columns:[]).map((column,index)=>{
    const label=String(column.label||`C${String(index+1).padStart(2,"0")}`);
    const key=String(column.key||`gridCol${String(index+1).padStart(2,"0")}`);
    const left=Number.isFinite(Number(column.dividerLeft))?Number(column.dividerLeft):Number(column.left);
    const right=Number.isFinite(Number(column.dividerRight))?Number(column.dividerRight):Number(column.right);
    if(!Number.isFinite(left)||!Number.isFinite(right)||right<=left+3)return null;
    const x1=left;
    const x2=right;
    const colWidth=Number.isFinite(Number(x2-x1))?Math.max(0,Number(x2-x1)):0;
    const colW=colWidth;
    // Crop from the column's own value-box extents rather than raw divider
    // bounds. Divider bounds run to the image edge for the first/last corridor
    // (pulling club labels into the ballSpeed strip) and hug narrow gaps after
    // an outlier re-split (leaving e.g. the Side Angle strip with ~0px margin).
    // acceptXGlobal/acceptXLocal stay on divider bounds so value acceptance is
    // unchanged and neighbour digits inside the padding are still rejected.
    const extentLeft=Number(column.x0);
    const extentRight=Number(column.x1);
    let boundLeft=x1;
    let boundRight=x2;
    if(Number.isFinite(extentLeft)&&Number.isFinite(extentRight)&&extentRight>extentLeft){
      const slack=Math.max(10,Math.min(30,(extentRight-extentLeft)*.14));
      if(extentLeft-boundLeft>slack*2.5)boundLeft=extentLeft-slack*2;
      if(boundRight-extentRight>slack*2.5)boundRight=extentRight+slack*2;
      boundLeft=Math.min(boundLeft,Math.max(0,extentLeft-slack));
      boundRight=Math.max(boundRight,Math.min(width,extentRight+slack));
    }
    const padX=Math.max(3,Math.min(14,colW*.06));
    const padY=Math.max(6,Math.min(28,(bottom-top)*.025));
    const x=Math.max(0,boundLeft-padX);
    const y=Math.max(0,top-padY);
    const r=Math.min(width,boundRight+padX);
    const b=Math.min(height,bottom+padY);
    const source=gdNormalizeValueCorridorHeader(column?.source||column?.borderSource||column?.valueSkewerStatus||"ocr-value-clearance-corridor");
    const reason="column strip crop from detected corridor bounds";
    const crop=gdCropCanvasRegion(scanImage,{x,y,width:Math.max(1,r-x),height:Math.max(1,b-y)},1);
    return {
      key,
      source,
      reason,
      column:Object.assign({},column,{key,label,left,right,dividerLeft:left,dividerRight:right}),
      acceptXGlobal:{left:x1,right:x2},
      acceptXLocal:{left:x1-crop.x,right:x2-crop.x},
      x1:x1,
      x2:x2,
      centerX:(x1+x2)/2,
      width:colWidth,
      y1:y,
      y2:b,
      crop,
      data:{text:"",words:[],lines:[]},
      localData:{text:"",words:[],lines:[]},
      values:[]
    };
  }).filter(Boolean);
}
