  const dataTop=dataRows.length?Math.min.apply(null,dataRows.map(r=>Number(r.y0))):0;
  const rowHeights=dataRows.map(r=>Number(r.y1)-Number(r.y0)).filter(v=>v>0).sort((a,b)=>a-b);
  const medRowH=rowHeights.length?rowHeights[Math.floor(rowHeights.length/2)]:16;
