  try{canvas=gdClarityNativeStripCanvas(flat,{left:0,right:width});}catch(e){canvas=null;}
  if(!canvas){canvas=gdClarityUpscaleCanvas(PIX.cropCanvas(flat,0,0,width,flat.height,0),2.5);cropSource="flat";}
  out.canvas=canvas;out.cropSource=cropSource;
