  const res=await gdClarityOcrWithTimeout(gdRecognizeWithTesseract(Tesseract,canvas,{tessedit_char_whitelist:"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789.° ",tessedit_pageseg_mode:"6"},"clarity-offcut"),15000);
