// Feedback image: the offcut strip exactly as read, each OCR line labelled at
// its own height with what it resolved to (club / SUMMARY / nothing).
function gdClarityOffcutMontage(offcut){
  const canvas=offcut&&offcut.canvas;
  if(!canvas){const e=document.createElement("canvas");e.width=10;e.height=10;return e;}
  const gap=8,labelW=220,dispH=700;
  const sc=dispH/Math.max(1,canvas.height);
  const imgW=Math.max(10,Math.round(canvas.width*sc));
  const flatH=Number(offcut.flatHeight)||0;
  const c=document.createElement("canvas");
  c.width=imgW+labelW+gap*3;c.height=dispH+gap*2;
  const ctx=c.getContext("2d");ctx.fillStyle="#0b0f0d";ctx.fillRect(0,0,c.width,c.height);
  ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality="high";
  try{ctx.drawImage(canvas,gap,gap,imgW,dispH);}catch(e){}
  ctx.strokeStyle="#37f28d";ctx.lineWidth=1.5;ctx.strokeRect(gap,gap,imgW,dispH);
  ctx.font="10px ui-monospace,Menlo,monospace";
  (offcut.lines||[]).forEach((l,i)=>{
    const yy=gap+(flatH>0?Math.max(8,Math.min(dispH-2,(Number(l.flatY)/flatH)*dispH)):8+i*12);
    ctx.fillStyle=l.summary?"#ffb84a":(l.club?"#37f28d":"#8fa39a");
    ctx.fillText(`${l.summary?"SUMMARY":(l.club||"·")} "${l.text}"`.slice(0,36),gap*2+imgW,yy);
  });
  return c;
}
// ===========================================================================
// DEEP SCAN (Stage 3.5) — targeted re-read of direction markers (R/L/+/-).
// Each direction cell is a KNOWN box holding a number plus (maybe) one small
// marker that can only be 1 of 4 glyphs. The stage re-crops that one box —
// at native photo resolution when the warp metadata allows it — then applies
// the BLANKING METHOD: remove the value cluster from the image and read what
// remains, by two independent routes (pure shape classification + OCR of the
// blanked image on clean white). It only ever updates the `direction` field
// of existing cells: rows are never added, removed, or shifted here.
// ===========================================================================
// Re-crop one flat-image rect at the best available quality. Prefers mapping
// the rect back through the warp to the ORIGINAL photo (native pixels); falls
// back to upscaling the flat crop when no warp metadata exists. Returns
// {canvas, source:"native"|"flat", scale} — source is reported truthfully in
// the debug output.
function gdClarityDeepCropCell(flat,rect){
  const PIX=window.ClarityTableOcrPixels;
  const x0=Math.max(0,Math.floor(Number(rect.x0))),y0=Math.max(0,Math.floor(Number(rect.y0)));
  const x1=Math.min(Number(flat.width)-1,Math.ceil(Number(rect.x1))),y1=Math.min(Number(flat.height)-1,Math.ceil(Number(rect.y1)));
  const cellW=Math.max(1,x1-x0),cellH=Math.max(1,y1-y0);
  const warpSource=flat.__gdWarpSource||null;
  if(warpSource&&Array.isArray(flat.__gdFlattenedQuad)){
    const corners=[[x0,y0],[x1,y0],[x1,y1],[x0,y1]].map(p=>gdFlatPointToWarpSourcePoint(flat,p[0],p[1]));
    if(corners.every(p=>p&&Number.isFinite(p.x)&&Number.isFinite(p.y))){
      const srcW=(Math.hypot(corners[1].x-corners[0].x,corners[1].y-corners[0].y)+Math.hypot(corners[2].x-corners[3].x,corners[2].y-corners[3].y))/2;
      // Render at ~2.5x the native source width (clamped) so thin marker
      // strokes survive binarisation; never below 2x the flat size.
      const targetW=Math.round(Math.min(1200,Math.max(cellW*2,srcW*2.5,120)));
      const canvas=gdWarpQuadToCanvas(warpSource,corners.map(p=>({x:p.x,y:p.y})),targetW,{minW:32,minH:16,maxH:480});
      if(canvas)return {canvas:canvas,source:"native",scale:targetW/cellW};
    }
  }
  const upscale=3.4;
  const cropped=PIX.cropCanvas(flat,x0,y0,x1,y1,0);
  return {canvas:gdClarityUpscaleCanvas(cropped,upscale),source:"flat",scale:upscale};
}
// Surround a crop with a white margin before OCR. Tesseract silently DROPS
// glyphs that touch the image border (the "111.6 read as 11.6" leading-digit
// failure) — a clean margin around the text is the standard fix.
function gdClarityPadCanvas(src,margin){
  margin=Math.max(0,Math.round(Number(margin)||0));
  if(!src||!src.width||!margin)return src;
  const out=document.createElement("canvas");
  out.width=src.width+margin*2;
  out.height=src.height+margin*2;
  const ctx=out.getContext("2d");
  ctx.fillStyle="#fff";
  ctx.fillRect(0,0,out.width,out.height);
  ctx.drawImage(src,margin,margin);
  return out;
}
// Full-height native-resolution render of one strip, for the DEBUG MONTAGES —
// so the feedback window shows the same quality the per-cell reads actually
// used, not the 1800px flat cut. Returns null without warp metadata (montage
// then falls back to the flat strip canvas).
function gdClarityNativeStripCanvas(flat,strip){
  if(!flat||!flat.__gdWarpSource||!Array.isArray(flat.__gdFlattenedQuad))return null;
  const x0=Math.max(0,Math.floor(Number(strip.left))),x1=Math.min(Number(flat.width)-1,Math.ceil(Number(strip.right)));
  const corners=[[x0,0],[x1,0],[x1,flat.height-1],[x0,flat.height-1]].map(p=>gdFlatPointToWarpSourcePoint(flat,p[0],p[1]));
  if(!corners.every(p=>p&&Number.isFinite(p.x)&&Number.isFinite(p.y)))return null;
  const targetW=Math.round(Math.min(520,Math.max(120,(x1-x0)*2.2)));
  return gdWarpQuadToCanvas(flat.__gdWarpSource,corners.map(p=>({x:p.x,y:p.y})),targetW,{minW:64,minH:120,maxH:3400});
}
// The stage runner, STRIP-LEVEL (v2). Per direction strip:
//   1. one hi-res render of the whole strip (native via inverse warp),
//   2. find the MARKER COLUMN once, by cross-row alignment — markers occupy the
//      same narrow x-range on every row, while value fragments land anywhere,
//   3. COLLECTIVE BLANKING: white out everything outside that column all the
//      way down the strip in one stroke (no per-cell value guessing),
//   4. read the remaining sliver band by band (shape classifier + OCR).
// Windows are deliberately GENEROUS: we never claim to know exactly where a
// marker is, only that it is definitely inside the padded window we read.
// Every data band of every direction strip is reported — none skipped silently.
// Only cell.direction is ever written; rows are never added/removed/shifted.
async function gdClarityDeepScanDirections(flat,scanRows,strips,dataRows,Tesseract,opts){
  opts=opts||{};
  const OCR=window.ClarityTableOcr,PIX=window.ClarityTableOcrPixels;
  const dirStrips=(Array.isArray(strips)?strips:[]).filter(s=>s&&s.metricKey&&typeof gdColumnNeedsDirection==="function"&&gdColumnNeedsDirection(s.metricKey));
  const rows=(Array.isArray(dataRows)?dataRows:[]).filter(r=>r&&Number.isFinite(Number(r.y0))&&Number.isFinite(Number(r.y1)));
  const out={stripEntries:[],examined:0,updated:0,agreed:0,shapeOnly:0,ocrOnly:0,conflicts:0,noMarker:0,noColumn:0,strips:dirStrips.length};
  let done=0;
  for(const strip of dirStrips){
    if(typeof gdPracticeAssertImportNotCanceled==="function")gdPracticeAssertImportNotCanceled();
    // 1. Hi-res strip render (native photo pixels when warp metadata exists).
    let canvas=null,cropSource="native";
    try{canvas=gdClarityNativeStripCanvas(flat,strip);}catch(e){canvas=null;}
    if(!canvas){canvas=gdClarityUpscaleCanvas(strip.canvas,2.5);cropSource="flat";}
    const bin=PIX.binarizeCanvas(canvas);
    const sy=bin.height/Math.max(1,Number(flat.height));
    const maskObj=PIX.inkMask(PIX.imageData(bin));
    const comps=PIX.connectedComponents(maskObj);
    const heights=comps.map(c=>c.h).filter(h=>h>2).sort((a,b)=>a-b);
    const charHeight=heights.length?heights[Math.floor(heights.length/2)]:16;
    // 2. Per data band (scaled into this strip's pixel space), group components.
    const bandPad=Math.max(2,charHeight*0.25);
    const bands=rows.map(r=>{
      const y0=Number(r.y0)*sy,y1=Number(r.y1)*sy;
      const inBand=comps.filter(c=>{const cy=(c.y0+c.y1)/2;return cy>=y0-bandPad&&cy<=y1+bandPad;});
      return {y0:y0,y1:y1,groups:OCR.groupComponentsIntoValues(inBand,{charHeight:charHeight}),comps:inBand};
    });
    // DECIDER: letter markers (R/L) live in a column RIGHT of the value —
    // try that first. Monitors that print signed values instead (+/-) put the
    // sign LEFT of the number, so when no right column aligns, fall back to
    // the basic sign mode on the left. Signs mode only ever accepts + or -.
    let markerCol=OCR.findMarkerColumn(bands,{charHeight:charHeight,side:"right"});
    let markerMode=markerCol?"letters":"";
    if(!markerCol){
      markerCol=OCR.findMarkerColumn(bands,{charHeight:charHeight,side:"left"});
      if(markerCol)markerMode="signs";
    }
    const entry={metricKey:strip.metricKey,cropSource:cropSource,canvas:bin,markerCol:null,support:0,mode:markerMode,bands:[]};
    if(!markerCol){
      // Honest: no aligned marker column found — every band reported unread,
      // strip-read directions stay untouched.
      out.noColumn+=1;
      entry.bands=bands.map((b,r)=>({row:r+1,final:"",method:"no-column",prev:"",hasCell:false,y0:b.y0,y1:b.y1}));
      out.examined+=bands.length;out.noMarker+=bands.length;
      out.stripEntries.push(entry);
      done+=1;if(typeof opts.onStrip==="function")opts.onStrip(done,dirStrips.length);
      continue;
    }
    // Generous sliver: the marker is DEFINITELY inside [mx0,mx1] padded.
    const pad=Math.max(3,Math.round(charHeight*0.45));
    const mx0=Math.max(0,Math.floor(markerCol.x0-pad)),mx1=Math.min(bin.width,Math.ceil(markerCol.x1+pad));
    entry.markerCol={x0:mx0,x1:mx1};entry.support=markerCol.support;
    // 3. COLLECTIVE BLANKING: everything outside the marker column, full height.
    const bctx=bin.getContext("2d");
    bctx.fillStyle="#fff";
    if(mx0>0)bctx.fillRect(0,0,mx0,bin.height);
    if(mx1<bin.width)bctx.fillRect(mx1,0,bin.width-mx1,bin.height);
    // 4. Read the sliver band by band.
    // Cells are matched by GEOMETRY (the reader stored each cell's band), not by
    // index — scanRows can legitimately have fewer rows than dataRows.
    const stripCells=[];
    scanRows.forEach((row,ri)=>{(row.cells||[]).forEach(cell=>{if(cell&&cell.key===strip.metricKey&&cell.geom)stripCells.push({cell:cell,scanRow:ri});});});
    for(let r=0;r<bands.length;r+=1){
      if(typeof gdPracticeAssertImportNotCanceled==="function")gdPracticeAssertImportNotCanceled();
      const b=bands[r];
      const markerComps=b.comps.filter(c=>{const cx=(c.x0+c.x1)/2;return cx>=mx0&&cx<=mx1;});
      // shape route: classify each remaining component, best score wins. Signs
      // mode is restricted to + and - (a fragment shaped like a letter must
      // not become a direction there).
      let shapeGlyph="",shapeScore=0;
      markerComps.forEach(c=>{
        const cls=OCR.classifyGlyphMask(OCR.cropMask(maskObj,c.x0,c.y0,c.x1,c.y1));
        if(!cls.glyph)return;
        if(markerMode==="signs"&&cls.glyph!=="+"&&cls.glyph!=="-")return;
        if(cls.score>shapeScore){shapeGlyph=cls.glyph;shapeScore=cls.score;}
      });
      const shapeDir=shapeGlyph?(OCR._internals.markerGlyphToDirection(shapeGlyph)||""):"";
      // ocr route: read the blanked sliver band (only run when ink remains)
      let ocrText="",ocrDir="";
      if(markerComps.length){
        try{
          const bandCrop=PIX.cropCanvas(bin,mx0,Math.max(0,Math.floor(b.y0-bandPad)),mx1,Math.min(bin.height,Math.ceil(b.y1+bandPad)),0);
          const res=await gdClarityOcrWithTimeout(gdRecognizeWithTesseract(Tesseract,gdClarityPadCanvas(bandCrop,12),{tessedit_char_whitelist:markerMode==="signs"?"+-":"LRlr+-",tessedit_pageseg_mode:"10"},"clarity-deep-scan"),9000);
          ocrText=String(res&&res.data&&res.data.text||"").trim();
          ocrDir=OCR._internals.directionFromText(ocrText)||"";
        }catch(e){ocrText="(ocr error: "+(e&&e.message||e)+")";}
      }
      // decision: agreement wins; lone shape accepted; lone OCR accepted when
      // marker ink exists; disagreement applies NOTHING and is reported.
      let final="",method="none";
      if(shapeDir&&ocrDir&&shapeDir===ocrDir){final=shapeDir;method="agree";}
      else if(shapeDir&&!ocrDir){final=shapeDir;method="shape";}
      else if(!shapeDir&&ocrDir){final=ocrDir;method="ocr";}
      else if(shapeDir&&ocrDir){method="conflict";}
      // attach to the scan row whose stored band overlaps this dataRow band
      const flatY0=Number(rows[r].y0),flatY1=Number(rows[r].y1);
      const match=stripCells.find(sc=>{const g=sc.cell.geom;const cy=(Number(g.y0)+Number(g.y1))/2;return cy>=flatY0-3&&cy<=flatY1+3;});
      const prev=match?String(match.cell.direction||""):"";
      if(final&&match){
        if(final!==prev)out.updated+=1;
        match.cell.direction=final;
        match.cell.directionSource="deep-scan-"+method;
      }
      if(method==="agree")out.agreed+=1;
      else if(method==="shape")out.shapeOnly+=1;
      else if(method==="ocr")out.ocrOnly+=1;
      else if(method==="conflict")out.conflicts+=1;
      else out.noMarker+=1;
      out.examined+=1;
      entry.bands.push({row:r+1,final:final,method:method,prev:prev,hasCell:!!match,shapeGlyph:shapeGlyph,shapeScore:Math.round(shapeScore*100),ocrText:ocrText,markerInk:markerComps.length,y0:b.y0,y1:b.y1});
    }
    out.stripEntries.push(entry);
    done+=1;if(typeof opts.onStrip==="function")opts.onStrip(done,dirStrips.length);
  }
  return out;
}
// Montage for the feedback window: each direction strip AFTER collective
// blanking — the actual sliver that was read — marker column boxed, one result
// letter per band. One tall image per strip: readable at a glance.
function gdClarityDeepScanMontage(stripEntries){
  const list=(Array.isArray(stripEntries)?stripEntries:[]).filter(e=>e&&e.canvas);
  if(!list.length){const e=document.createElement("canvas");e.width=10;e.height=10;return e;}
  const gap=10,labelH=14,dispH=700,resultW=34;
  const items=list.map(e=>{const sc=dispH/Math.max(1,e.canvas.height);return {e:e,sc:sc,dw:Math.max(10,Math.round(e.canvas.width*sc))+resultW,dh:dispH};});
  const totalW=items.reduce((a,it)=>a+it.dw+gap,gap);
  const c=document.createElement("canvas");c.width=Math.max(1,totalW);c.height=dispH+labelH+gap*2;
  const ctx=c.getContext("2d");ctx.fillStyle="#0b0f0d";ctx.fillRect(0,0,c.width,c.height);
  ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality="high";
  let x=gap;
  items.forEach(it=>{
    const e=it.e,sc=it.sc,imgW=it.dw-resultW;
    try{ctx.drawImage(e.canvas,x,labelH+gap,imgW,it.dh);}catch(err){}
    ctx.strokeStyle=e.markerCol?"#37f28d":"#ff6a6a";ctx.lineWidth=1.5;
    ctx.strokeRect(x,labelH+gap,imgW,it.dh);
    if(e.markerCol){
      ctx.strokeStyle="#62d2ff";
      ctx.strokeRect(x+e.markerCol.x0*sc,labelH+gap,Math.max(2,(e.markerCol.x1-e.markerCol.x0)*sc),it.dh);
    }
    ctx.font="10px ui-monospace,Menlo,monospace";
    ctx.fillStyle=e.markerCol?"#37f28d":"#ff8a8a";
    ctx.fillText(`${e.metricKey} (${e.cropSource}${e.markerCol?`, ${e.mode||"letters"}, ${e.support} aligned`:", no column"})`.slice(0,42),x,11);
    (e.bands||[]).forEach(b=>{
      const by=labelH+gap+((b.y0!=null?b.y0:0))*sc;
      const cy=labelH+gap+(((b.y0||0)+(b.y1||0))/2)*sc;
      ctx.fillStyle=b.final?"#37f28d":(b.method==="conflict"?"#ffb84a":"#5f6f68");
      ctx.fillText(`${b.row}:${b.final||"·"}`,x+imgW+3,Number.isFinite(cy)&&cy>labelH?cy:labelH+gap+12*b.row);
    });
    x+=it.dw+gap;
  });
  return c;
}
async function gdClarityTableOcrScanFromCheckpoint(checkpoint,opts={}){
  // Rebuilt scan path. Hands the flattened value-grid image (output of the kept
  // 4-corner stretch) to the isolated Clarity Table OCR module:
  //   Stage 1 split (anti-fusion + de-fuse) -> Stage 2 header allocation ->
  //   Stage 3 per-cell read + validation -> library import.
  // The old in-file corridor/header/column pipeline is no longer on this path.
  const OCR=window.ClarityTableOcr, PIX=window.ClarityTableOcrPixels, REG=window.LaunchMonitorAliasRegistry;
  const sourceLabel=opts.sourceLabel||gdPracticePhotoName||"Practice photo scan";
  const flat=checkpoint?.scanImage||checkpoint?.directColumnSource||checkpoint?.cluster?.displayCutoutCanvas||checkpoint?.cluster?.cutoutCanvas||gdPracticeNormalizedCanvas||null;
  if(!OCR||!PIX||!REG){
    gdPracticeFeedback("Clarity Table OCR module is not loaded.","error");
    return null;
  }
  if(!flat||typeof flat.width!=="number"){
    gdPracticeFeedback("No flattened value grid available. Re-frame and scan again.","error");
    gdOpenPracticeManualQuadTool();
    return null;
  }
  // Start a durable, cancelable job up front so the WHOLE run has an active/fail
  // boundary (not just the processing flag). Any early return, stall, or throw
  // is caught by the finally, which fails this job and releases the UI.
  const job=gdPracticeStartImportJob("clarity-table-ocr",sourceLabel,{status:"scanning",checkpointText:"Splitting columns",stageIndex:0,progress:8});
  if(!job)return null;
  const jobId=job.id;
  gdPracticeClusterCheckpoint=checkpoint;
  window.__gdPracticeClusterCheckpoint=checkpoint;
  gdClosePracticeManualQuadTool();
  gdSetPracticePhotoProcessing(true,{stageIndex:0,progress:8,preserveClubs:true});
  gdPracticeFeedback("Scanning: splitting columns...");
  await gdPracticeYieldScanPaint();
  try{
    // Detect boxes from pixels (reliable geometry, no misses), then OCR EACH box
    // with a small crop. Whole-image OCR missed ~a third of values and garbled
    // the headers; isolated crops read cleanly. Number-like boxes feed the cut;
    // the leftover text boxes are the headers (the only words left per strip).
    const Tesseract=await gdLoadTesseract();
    gdPracticeDebugCheckpointSafe("value_corridor_mapping","running",{inputSummary:`${flat.width}x${flat.height} flat image`});
    const detected=PIX.detectNumberBoxes(flat);
    const boxCfg={tessedit_char_whitelist:"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789.,°ºLR-+ ",tessedit_pageseg_mode:"7"};
    const looksNum=OCR._internals&&OCR._internals.looksLikeValue;
    const readBoxes=[];
    const totalBoxes=detected.boxes.length;
    for(let bi=0;bi<totalBoxes;bi+=1){
      gdPracticeAssertImportNotCanceled();
      const box=detected.boxes[bi];
      // Native-resolution crop (falls back to the flat crop without warp
      // metadata). Box GEOMETRY stays in flat coordinates — only the pixels
      // handed to OCR get the quality upgrade. White margin so no glyph
      // touches the border (Tesseract drops edge glyphs).
      const crop=gdClarityPadCanvas(gdClarityDeepCropCell(flat,{x0:box.x0-3,y0:box.y0-3,x1:box.x1+3,y1:box.y1+3}).canvas,12);
      const res=await gdClarityOcrWithTimeout(gdRecognizeWithTesseract(Tesseract,crop,boxCfg,"clarity-box"),9000);
      readBoxes.push(Object.assign({},box,{text:String(res?.data?.text||"").trim()}));
      if(bi%12===0){
        gdPracticeUpdateImportJob({checkpointText:`Reading boxes ${bi+1}/${totalBoxes}`,stageIndex:0,progress:Math.min(48,10+Math.round((bi/Math.max(1,totalBoxes))*38))});
        await gdPracticeYieldScanPaint();
      }
    }
    const numberBoxes=readBoxes.filter(box=>box.text&&looksNum(box.text));
    const textBoxes=readBoxes.filter(box=>box.text&&!looksNum(box.text));
    const columns=OCR.splitColumns(numberBoxes,{sourceWidth:flat.width});
    const valueRows=OCR.clusterValueRows(numberBoxes);
    // Diagnostic: what does each column actually contain? Lists the box count and a
    // few sample reads per column so a phantom column (e.g. an L/R marker band or a
    // split club column) is obvious at a glance instead of guessed at.
    const columnBreakdown=columns.map((c,ci)=>{
      const inCol=numberBoxes.filter(b=>Number(b.cx)>=Number(c.left)&&Number(b.cx)<=Number(c.right));
      return `c${ci}[${inCol.length}]:${inCol.slice(0,5).map(b=>String(b.text||"").trim()).join(",")}`;
    }).join("  |  ");
    gdPracticeDebugCheckpointSafe("value_corridor_mapping",columns.length>=4?"success":"failed",{outputSummary:`${columns.length} columns from ${numberBoxes.length} number boxes (${readBoxes.length} read) across ${valueRows.length} value rows\nPer-column: ${columnBreakdown}`,counts:{columns:columns.length,numberBoxes:numberBoxes.length,textBoxes:textBoxes.length,rows:valueRows.length},snapshot:{canvas:gdClarityScanOverlay(flat,{numberBoxes:numberBoxes,textBoxes:textBoxes,columns:columns}),label:"Column split: value boxes green, text boxes blue, cuts yellow"}});
    if(columns.length<4||valueRows.length<1){
      gdPracticeFeedback("Column split did not find a usable grid. Re-frame and scan again.","error");
      gdOpenPracticeManualQuadTool();
      return null;
    }
    // Stage 2 — CUT each column into its own strip image, then NAME each strip by
    // reading the header off the top of THAT strip. Each strip is self-contained.
    gdPracticeUpdateImportJob({checkpointText:"Cutting + naming strips",stageIndex:1,progress:56});
    gdSetPracticePhotoProcessing(true,{stageIndex:1,progress:56,preserveClubs:true});
    // Header = just the text near the top of each strip. Generous band: anything
    // above the first data row. Each strip is its OWN image, so reading its top
    // only sees THAT column's header (+ its units, which the resolver strips) —
    // no cross-strip mixing, no need to be precise about the band.
    // Anchor the header band to the first FULL value row, not just the topmost
    // detected row. A stray 2-box row near the top would otherwise collapse the
    // band to a sliver and every header would read as garbage (the 0/12 failure).
    const rowCounts=valueRows.map(r=>Array.isArray(r.items)?r.items.length:0);
    const maxRowBoxes=Math.max.apply(null,[0].concat(rowCounts));
    const firstDataRow=valueRows.find(r=>(Array.isArray(r.items)?r.items.length:0)>=Math.max(4,maxRowBoxes*0.5))||valueRows[0];
    const headerBottom=Math.max(8,Number(firstDataRow.y0));
    let strips=gdClarityCutStrips(flat,columns);
    gdPracticeDebugCheckpointSafe("header_strip_scan","running",{inputSummary:`${strips.length} strips cut, header band 0-${Math.round(headerBottom)}`});
    // Name each strip by reading the text near its top and matching a metric.
    strips=await gdClarityNameStrips(strips,headerBottom,Tesseract,flat);
    // Hand over ALL strips (no edge trimming). Unnamed strips carry no metricKey,
    // so they contribute nothing to a metric, but stay visible in the montage so
    // misreads are inspectable. The club/margin column is handled separately.
    const namedStrips=strips.filter(s=>s.metricKey);
    const allocatedCount=namedStrips.length;
    gdPracticeDebugCheckpointSafe("header_strip_scan",allocatedCount>=4?"success":"failed",{outputSummary:`Named ${allocatedCount}/${strips.length}: ${strips.map(s=>s.metricKey||("?"+(s.headerText?"["+s.headerText+"]":""))).join(" | ")}`,counts:{allocated:allocatedCount,strips:strips.length},snapshot:{canvas:gdClarityStripsMontage(strips),label:"Physical strips: green=named, red=unnamed"}});
    if(allocatedCount<4){
      gdPracticeFeedback("Header allocation could not identify the columns. Re-frame and scan again.","error");
      gdOpenPracticeManualQuadTool();
      return null;
    }
    // Margin = everything left of the first NAMED metric strip (the club column
    // + true page margin).
    const firstColLeft=Number((namedStrips[0]||strips[0]).left);
    // ===== Stage 2.5 — CLUB ID + SUMMARY ROWS, from ONE whole-offcut read.
    // No per-row cutting: it does not matter where anything sits on the offcut,
    // only that it is on it. The lines that come back give the club (majority
    // over lines resolving to a club — one club per scan) and the y-positions
    // of AVERAGE / STD DEV labels, which the row filter below uses.
    gdPracticeUpdateImportJob({checkpointText:"Reading the offcut (club + summary rows)",stageIndex:1,progress:64});
    gdPracticeDebugCheckpointSafe("club_id","running",{inputSummary:`Whole offcut 0-${Math.round(firstColLeft)} x ${flat.height}`});
    let clubScan={club:"",votes:{},lines:[],summaryYs:[]};
    try{
      clubScan=await gdClarityOffcutScan(flat,firstColLeft,Tesseract);
    }catch(e){
      if(typeof gdPracticeIsQuietScanStop==="function"&&gdPracticeIsQuietScanStop(e))throw e;
      console.warn("[GolfDaddy] Club ID stage failed",e);
      gdPracticeDebugCheckpointSafe("club_id","failed",{outputSummary:`Offcut read failed — falling back to the manual club; summary rows unfiltered. ${e&&e.message?e.message:e}`,technicalDetails:e&&e.stack});
    }
    const manualClub=(typeof gdPracticeScanClubLabel==="function"?gdPracticeScanClubLabel():"7i")||"7i";
    const clubLabel=clubScan.club||manualClub;
    if(clubScan.lines&&clubScan.lines.length){
      const voteText=Object.keys(clubScan.votes).map(k=>`${k}: ${clubScan.votes[k]}`).join(", ")||"none";
      const lineText=clubScan.lines.map(l=>`y${Math.round(l.flatY)}: "${l.text}" -> ${l.summary?"SUMMARY":(l.club||"·")}`).join("\n");
      const totalVotes=Object.values(clubScan.votes).reduce((a,b)=>a+b,0);
      const winnerVotes=clubScan.club?clubScan.votes[clubScan.club]:0;
      gdPracticeDebugCheckpointSafe("club_id",clubScan.club?"success":"warning",{
        outputSummary:`${clubScan.club?`Club: ${clubScan.club} (${winnerVotes}/${totalVotes} club votes)`:`No club resolved from ${clubScan.lines.length} offcut lines — using ${manualClub} (manual/default)`}. Votes: ${voteText}. ${clubScan.summaryYs.length} summary label${clubScan.summaryYs.length===1?"":"s"} found (y: ${clubScan.summaryYs.map(y=>Math.round(y)).join(", ")||"none"}) [${clubScan.cropSource||"?"}].\n${lineText}`,
        counts:{lines:clubScan.lines.length,votes:totalVotes,winnerVotes:winnerVotes,summaryLabels:clubScan.summaryYs.length},
        snapshot:{canvas:gdClarityOffcutMontage(clubScan),label:`Offcut as read: green = club vote, amber = summary label; result ${clubLabel}`}
      });
    }else if(!clubScan.club){
      gdPracticeDebugCheckpointSafe("club_id","warning",{outputSummary:`Offcut produced no readable lines (width ${Math.round(firstColLeft)}px) — using ${manualClub} (manual/default); summary rows unfiltered.`,counts:{lines:0}});
    }
    // A real data row spans most of the columns. Drop SPARSE stray rows (e.g. a
    // couple of edge-noise boxes near the top) — otherwise that stray becomes a
    // phantom shot as row 1 and shifts every real row down a slot. Summary rows
    // (AVERAGE / STD DEV) are dropped by the offcut label y-positions above.
    const rowBoxMax=Math.max.apply(null,[0].concat(valueRows.map(r=>Array.isArray(r.items)?r.items.length:0)));
    // rowFilterLog: honest per-row record of WHY each detected row was kept or
    // dropped — printed in the extraction checkpoint.
    const rowFilterLog=[];
    const summaryYs=Array.isArray(clubScan.summaryYs)?clubScan.summaryYs:[];
    const dataRows=valueRows.filter((row,ri)=>{
      const boxes=Array.isArray(row.items)?row.items.length:0;
      if(boxes<Math.max(4,rowBoxMax*0.5)){rowFilterLog.push(`band${ri+1}(y${Math.round(row.y0)}): DROPPED sparse (${boxes} boxes)`);return false;}
      const rowPad=(Number(row.y1)-Number(row.y0))*0.6;
      const summaryHit=summaryYs.find(y=>Number(y)>=Number(row.y0)-rowPad&&Number(y)<=Number(row.y1)+rowPad);
      rowFilterLog.push(`band${ri+1}(y${Math.round(row.y0)}): ${summaryHit!=null?`DROPPED summary (label at y${Math.round(summaryHit)})`:"kept"} (${boxes} boxes)`);
      return summaryHit==null;
    });
    // ===== GEOMETRY FROZEN. Strips are cut + named. Extraction below just reads
    // each strip top-to-bottom and slots values into rows by position. =====
    gdPracticeUpdateImportJob({checkpointText:"Reading strips",stageIndex:2,progress:74});
    gdSetPracticePhotoProcessing(true,{stageIndex:2,progress:74,preserveClubs:true});
    // extraction_completed marked RUNNING so its duration spans the strip reads.
    gdPracticeDebugCheckpointSafe("extraction_completed","running",{inputSummary:`Read ${namedStrips.length} named strips into ${dataRows.length} rows`});
    // Read each strip top-to-bottom, slot values into rows by position (blanks
    // self-insert where a value is missed).
    const readResult=await gdClarityReadStripsIntoRows(strips,dataRows,Tesseract,{club:clubLabel,flat:flat,onStrip:(i,n)=>{try{gdPracticeUpdateImportJob({checkpointText:`Reading strip ${i+1}/${n}`,stageIndex:2,progress:Math.min(96,74+Math.round((i/Math.max(1,n))*22))});}catch(e){}}});
    const scanRows=readResult.scanRows;
    // Diagnostic: dump what each strip actually READ, per metric, down the rows —
    // so the read values can be compared directly against the visible strips (a
    // blank cell prints as "·"). This makes a bad read or a misalignment obvious.
    const readDump=namedStrips.map(s=>{
      const vals=scanRows.map(r=>{const c=(r.cells||[]).find(x=>x&&x.key===s.metricKey);return c&&c.value!=null?String(c.value)+(c.direction||""):"·";});
      return `${s.metricKey}: ${vals.join(",")}`;
    }).join("\n");
    // ===== Stage 3.5 — DEEP SCAN (strip-level). Per direction strip: find the
    // marker column once by cross-row alignment, COLLECTIVELY BLANK everything
    // outside it all the way down, then read the remaining sliver band by band.
    // Every data band is examined and reported — no silent skips. Only
    // direction fields are touched; a failure falls back to strip-read
    // directions without killing the scan.
    gdPracticeUpdateImportJob({checkpointText:"Deep scanning direction markers",stageIndex:2,progress:90});
    try{
      const directionKeys=namedStrips.map(s=>s.metricKey).filter(k=>typeof gdColumnNeedsDirection==="function"&&gdColumnNeedsDirection(k));
      gdPracticeDebugCheckpointSafe("deep_scan","running",{inputSummary:`${directionKeys.length} direction strips (${directionKeys.join(", ")||"none"}) x ${dataRows.length} data bands`});
      const deep=await gdClarityDeepScanDirections(flat,scanRows,namedStrips,dataRows,Tesseract,{onStrip:(n,total)=>{try{gdPracticeUpdateImportJob({checkpointText:`Deep scan strip ${n}/${total}`,stageIndex:2,progress:Math.min(95,90+Math.round((n/Math.max(1,total))*5))});}catch(e){}}});
      const deepDump=deep.stripEntries.map(e=>{
        const head=`${e.metricKey} [${e.cropSource}] ${e.markerCol?`marker column found (mode: ${e.mode==="signs"?"+/- signs, left of value":"R/L letters, right of value"}, ${e.support} rows aligned)`:"NO marker column aligned (letters nor signs) — nothing applied"}`;
        const bandText=(e.bands||[]).map(b=>`r${b.row}:${b.final||"·"}${b.method&&b.method!=="none"&&b.method!=="no-column"?`[${b.method}]`:""}${b.hasCell===false&&b.final?"(no cell)":""}${b.prev&&b.prev!==b.final?`(was ${b.prev})`:""}`).join(" ");
        return `${head}\n  ${bandText}`;
      }).join("\n");
      gdPracticeDebugCheckpointSafe("deep_scan",deep.examined?"success":"warning",{
        outputSummary:`${deep.strips} direction strips, ${deep.examined} bands examined: ${deep.agreed} agree (shape+ocr), ${deep.shapeOnly} shape-only, ${deep.ocrOnly} ocr-only, ${deep.conflicts} conflict (not applied), ${deep.noMarker} no marker. ${deep.noColumn} strip(s) without an aligned marker column. ${deep.updated} direction${deep.updated===1?"":"s"} changed.\n${deepDump||"No direction strips to scan."}`,
        counts:{strips:deep.strips,examined:deep.examined,updated:deep.updated,agreed:deep.agreed,shapeOnly:deep.shapeOnly,ocrOnly:deep.ocrOnly,conflicts:deep.conflicts,noMarker:deep.noMarker,noColumn:deep.noColumn},
        snapshot:{canvas:gdClarityDeepScanMontage(deep.stripEntries),label:"Deep scan: strips after collective blanking (blue = marker column read; right rail = per-row result)"}
      });
    }catch(e){
      if(typeof gdPracticeIsQuietScanStop==="function"&&gdPracticeIsQuietScanStop(e))throw e;
      console.warn("[GolfDaddy] Deep scan stage failed",e);
      gdPracticeDebugCheckpointSafe("deep_scan","failed",{outputSummary:`Deep scan failed — directions fall back to the strip read. ${e&&e.message?e.message:e}`,technicalDetails:e&&e.stack});
    }
    // Single checkpoint (adapter): scanner output -> Shot Library, cleaning misreads.
    const payload=gdClarityScanResultToPayload(scanRows,{label:sourceLabel,club:clubLabel});
    const rowCount=Number(payload?.clubGroups?.length)||0;
    gdPracticeDebugCheckpointSafe("extraction_completed",rowCount?"success":"failed",{outputSummary:`Read ${rowCount} shots (${scanRows.length} rows x ${allocatedCount} strips)\nPer-strip band counts (after head-trim to consensus): ${(readResult.stripCounts||[]).join(" ")}\n${readDump}\nRow filter (summary/sparse):\n${rowFilterLog.join("\n")}`,counts:{rows:rowCount,scanRows:scanRows.length},snapshot:{canvas:gdClarityStripsMontage(namedStrips),label:`Extraction: ${rowCount} shots read from ${namedStrips.length} physical strips`}});
    if(!rowCount){
      gdPracticeFeedback("No usable rows were read. Re-frame the value grid and scan again.","error");
      gdOpenPracticeManualQuadTool();
      return null;
    }
    gdPracticeSetExtractionPreview(payload,sourceLabel);
    await gdImportLaunchMonitorPayload(payload,sourceLabel);
    gdSetPracticeScanStatus(`Scan complete: saved ${rowCount} shot${rowCount===1?"":"s"} to the Clarity Shot Library.`);
    gdPracticeFeedback(`Saved ${rowCount} shot${rowCount===1?"":"s"} to the Shot Library.`,"ready");
    return payload;
  }catch(e){
    if(typeof gdPracticeIsQuietScanStop==="function"&&gdPracticeIsQuietScanStop(e)){
      gdPracticeReleaseStoppedScan(e.message||"Practice photo scan stopped");
      return null;
    }
    console.warn("[GolfDaddy] Clarity table OCR scan failed",e);
    gdPracticeDebugFailedSafe("extraction_started",e,{outputSummary:"Clarity table OCR failed",technicalDetails:e&&e.stack});
    gdPracticeFeedback(e&&e.message?e.message:"Table OCR scan failed. Adjust the frame and scan again.","error");
    return null;
  }finally{
    // Single fail boundary: if this job is still active here (any early return,
    // stall, or throw that didn't complete the import), fail it so the UI is
    // released and a new scan isn't blocked as "still running".
    try{if(gdPracticeImportJobIsCurrent(jobId))gdPracticeFailImportJob(new Error("Clarity table OCR ended without saving"),"Scan ended without saving. Adjust the frame and scan again.");}catch(e){}
    gdSetPracticePhotoProcessing(false,{skipJob:true});
    gdPracticeReleaseProcessingControlsSafe("clarity-table-ocr-finally");
  }
}
async function gdRunDefaultPracticePhotoScanFromCheckpoint(checkpoint,opts={}){
  // Rebuilt path: delegate to the isolated Clarity Table OCR module. The old
  // corridor/header/column pipeline is bypassed (kept as dead code for now).
  if(!checkpoint){
    gdPracticeFeedback("Frame the value grid first, then scan.","error");
    return null;
  }
  return gdClarityTableOcrScanFromCheckpoint(checkpoint,opts);
}
async function gdRunPracticePhotoOcrFromCheckpoint(checkpoint){
  if(!checkpoint?.cluster?.quad)return null;
  if(checkpoint?.visualOnly||checkpoint?.directColumnSource){
    return await gdRunValueCorridorMappingFromCheckpoint(checkpoint,{sourceLabel:gdPracticePhotoName||"Practice photo scan"});
  }
  const source=checkpoint.source||gdPracticeNormalizedCanvas||gdNormalizeLaunchMonitorTable(gdPracticePhotoBitmap)||gdPracticePhotoBitmap;
  const prepared=checkpoint.prepared||source;
  const scanImage=checkpoint.scanImage||checkpoint.cluster.flattenedCanvas||gdFlattenValueClusterShape(prepared,checkpoint.cluster,1800);
  if(!scanImage){
    gdSetPracticeScanStatus("Value-cluster shape found, but flattening it failed.");
    return null;
  }
  checkpoint.scanImage=scanImage;
  return await gdRunValueCorridorMappingFromCheckpoint(Object.assign({},checkpoint,{source,prepared,scanImage,directColumnSource:scanImage}),{sourceLabel:gdPracticePhotoName||"Practice photo scan"});
}
async function gdHandleLaunchMonitorPhoto(file){
  if(!file){
    gdPracticeDebugStartRunSafe({sourceName:"Practice photo",sourceType:"image"});
    gdPracticeDebugFailedSafe("photo_selected",new Error("No image selected"),{outputSummary:"No image selected"});
    gdPracticeFeedback("No image selected. Choose a practice photo to scan.","error");
    return;
  }
  gdPracticeDebugStartRunSafe({sourceName:file.name||"Photo shot data scan",sourceType:file.type||"image",fileName:file.name||"",fileSize:file.size||0});
  gdPracticeDebugCheckpointSafe("photo_selected","running",{inputSummary:file.name||"Selected image"});
  try{
    gdPracticeClearTemplateOutcomes();
    gdPracticePhotoBitmap=await createImageBitmap(file);
    gdPracticePhotoName=file.name||"Photo shot data scan";
    gdPracticeDebugCheckpointSafe("photo_selected","success",{outputSummary:"Browser image bitmap created",counts:{bytes:file.size||0}});
    gdPracticeDebugCheckpointSafe("image_metadata","success",{outputSummary:`${gdPracticePhotoBitmap.width} x ${gdPracticePhotoBitmap.height}`,counts:{width:gdPracticePhotoBitmap.width,height:gdPracticePhotoBitmap.height}});
    gdPracticeDebugCheckpointSafe("image_preprocess","running",{inputSummary:"Normalize table image"});
    gdPracticeNormalizedCanvas=gdNormalizeLaunchMonitorTable(gdPracticePhotoBitmap);
    gdPracticeDebugCheckpointSafe("image_preprocess","success",{outputSummary:`Prepared ${gdPracticeNormalizedCanvas?.width||0} x ${gdPracticeNormalizedCanvas?.height||0}`,counts:{width:gdPracticeNormalizedCanvas?.width||0,height:gdPracticeNormalizedCanvas?.height||0}});
    gdPracticeClusterCheckpoint=null;
    gdPracticeSetProtectedScanStage("");
    gdClosePracticeManualQuadTool();
    const preview=document.getElementById("gdPracticeScanPreview");
    if(preview)preview.src=URL.createObjectURL(file);
    document.getElementById("gdPracticeScanner")?.classList.add("active");
    document.getElementById("gdPracticeOcrReview")?.classList.remove("active","stripOnly");
    gdPracticeClearScanCheckpoint();
    gdPracticeHideDebug();
    gdPracticeSetContinueScanReady(false);
    gdPracticeFeedback("Photo ready. Checking for a value-grid shape...");
    const smallMessage=gdPracticePhotoSmallMessage();
    if(smallMessage){
      gdPracticeDebugFailedSafe("image_metadata",new Error(smallMessage),{outputSummary:"Image too small for reliable scan"});
      gdPracticeFeedback(smallMessage,"error");
      return;
    }
    gdPracticeDebugCheckpointSafe("crop_cleanup","running",{inputSummary:"Finding value-grid crop"});
    const checkpoint=await gdBuildPracticeClusterCheckpoint();
    gdPracticeClusterCheckpoint=checkpoint;
    if(checkpoint){
      gdPracticeDebugCheckpointSafe("crop_cleanup","success",{outputSummary:"Value-grid checkpoint created",counts:{hasCluster:checkpoint.cluster?1:0}});
      gdOpenPracticeManualQuadTool();
    }else{
      gdPracticeDebugCheckpointSafe("crop_cleanup","warning",{outputSummary:"Auto value-grid shape not found; manual corner stretch opened"});
      document.getElementById("gdPracticeScanner")?.classList.add("active");
      gdOpenPracticeManualQuadTool();
    }
    gdNativePracticeFeedbackBridge({
      status:"photo_selected",
      lastAction:"Uploaded photo screen ready",
      warnings:["Photo import uses the existing photo scan tools; native photo extraction is not connected yet."],
      errors:[],
      photoAction:true,
      nextStep:"Adjust the generated box around the value grid, then Scan."
    });
    gdPracticeRefreshDebugTools();
  }catch(e){
    console.warn("[GolfDaddy] launch monitor photo prepare failed",e);
    gdPracticeDebugFailedSafe("photo_selected",e,{outputSummary:"Could not open or prepare photo",technicalDetails:e&&e.stack});
    gdPracticeFeedback(e&&e.message?e.message:"Could not open photo","error");
  }
}
async function gdScanPracticePhotoCrop(){
  let scanLoaderStarted=false;
  const releaseScanLoader=()=>{
    if(!scanLoaderStarted)return;
    scanLoaderStarted=false;
    if(typeof gdSetPracticePhotoProcessing==="function")gdSetPracticePhotoProcessing(false,{immediate:true,skipJob:true});
  };
  try{
    if(gdPracticeScanReentryBlocked())return null;
    if(!gdPracticeImportCanStart(gdPracticePhotoName||"Practice photo scan"))return null;
    gdSetPracticePhotoProcessing(true,{stageIndex:1,progress:16,preserveClubs:true});
    scanLoaderStarted=true;
    await gdPracticeYieldScanPaint();
    gdPracticeDebugEnsureRunSafe({sourceName:gdPracticePhotoName||"Practice photo scan"});
    gdPracticeDebugCheckpointSafe("crop_cleanup","running",{inputSummary:"Manual scan button"});
    const checkpoint=await gdBuildPracticeClusterCheckpoint();
    gdPracticeClusterCheckpoint=checkpoint;
    if(!checkpoint){
      releaseScanLoader();
      gdPracticeDebugCheckpointSafe("crop_cleanup","warning",{outputSummary:"Auto value-grid shape not found; manual frame opened"});
      gdOpenPracticeManualQuadTool();
      return null;
    }
    gdPracticeDebugCheckpointSafe("crop_cleanup","success",{outputSummary:"Value-grid checkpoint created from scan button"});
    releaseScanLoader();
    gdOpenPracticeManualQuadTool();
  }catch(e){
    releaseScanLoader();
    console.warn("[GolfDaddy] launch monitor photo cluster failed",e);
    gdPracticeDebugFailedSafe("crop_cleanup",e,{outputSummary:"Photo cluster failed",technicalDetails:e&&e.stack});
    gdPracticeFeedback(e&&e.message?e.message:"Photo cluster failed. Frame it manually, then scan.","error");
    gdLmSetStatus("Status","Photo cluster failed",e&&e.message?e.message:"Could not find OCR cluster","conflict_check");
    gdOpenPracticeManualQuadTool();
  }
}
async function gdPracticePrimaryScanAction(){
  if(gdPracticeScanReentryBlocked())return null;
  const manual=document.getElementById("gdPracticeManualQuadTool");
  if(manual&&!manual.hidden&&manual.classList.contains("active")){
    return gdApplyPracticeManualQuad();
  }
  const checkpoint=gdPracticeClusterCheckpoint||window.__gdPracticeClusterCheckpoint||null;
  if(checkpoint){
    gdSetPracticePhotoProcessing(true,{stageIndex:0,progress:8,preserveClubs:true});
    await gdPracticeYieldScanPaint();
    return gdRunDefaultPracticePhotoScanFromCheckpoint(checkpoint,{sourceLabel:gdPracticePhotoName||"Practice photo scan"});
  }
  return gdScanPracticePhotoCrop();
}
async function gdImportReviewedPracticeOcr(){
  const text=document.getElementById("gdPracticeOcrText")?.value||"";
  const cleaned=gdCleanLaunchMonitorOcrText(text);
  const payload=gdBuildLaunchMonitorTextCapture(cleaned,gdPracticePhotoName||"Reviewed photo shot data");
  payload.inputType="photo-ocr-reviewed";
  payload.sourceIdentity={providerGuess:"photo_ocr_reviewed",confidence:.72,evidence:cleaned.split(/\n/).slice(0,6)};
  if(!(payload.clubGroups||[]).length){
    gdSetPracticeScanStatus("No usable shots found. Keep the header row and at least Club plus Carry.");
    gdLmSetStatus("Status","No usable shots found","Review OCR text before importing.","conflict_check");
    return;
  }
  if(gdPracticeToleranceCanEditSafe()){
    gdPracticeSetExtractionPreview(payload,"Reviewed photo scan");
    gdSetPracticeScanStatus(`Extraction checkpoint ready with ${payload.clubGroups.length} shots`);
    return;
  }
  await gdImportLaunchMonitorPayload(payload,"Reviewed photo scan");
  gdSetPracticeScanStatus(`Reviewed scan imported ${payload.clubGroups.length} shot${payload.clubGroups.length===1?"":"s"}`);
  gdCancelPracticePhotoScan(false);
}
function gdDownloadFlattenedGrid(){
  // Dev hook: export the flattened value-grid image (post 4-corner stretch) so
  // it can be fed to the standalone Clarity Table OCR harness for testing.
  const cp=window.__gdPracticeClusterCheckpoint||(typeof gdPracticeClusterCheckpoint!=="undefined"?gdPracticeClusterCheckpoint:null);
  const canvas=cp?.scanImage||cp?.directColumnSource||cp?.cluster?.displayCutoutCanvas||cp?.cluster?.cutoutCanvas||gdPracticeNormalizedCanvas||null;
  if(!canvas||typeof canvas.toDataURL!=="function"){
    gdPracticeFeedback("No flattened grid yet - upload a photo and frame the value grid first.","error");
    return false;
  }
  try{
    const a=document.createElement("a");
    a.href=canvas.toDataURL("image/png");
    a.download=`clarity-flattened-grid-${Date.now()}.png`;
    document.body.appendChild(a);a.click();a.remove();
    gdPracticeFeedback(`Exported flattened grid (${canvas.width}x${canvas.height}).`,"ready");
  }catch(e){
    gdPracticeFeedback("Could not export flattened grid: "+(e&&e.message?e.message:e),"error");
  }
  return false;
}
