function gdLmStatusClass(status){
  if(["corroborated","cross_distance_verified","verified_by_result","cluster_candidate","delivery_only","result_only"].includes(status))return "good";
  if(["conflict_check","alignment_signal"].includes(status))return "warn";
  return "bad";
}
function gdLmAdminRow(label,value,sub,status){
  const cls=gdLmStatusClass(status||"");
  return `<div class="gdLmSummary ${cls}"><div><span>${gdEscapeHTML(label)}</span><strong>${gdEscapeHTML(value)}</strong></div><span>${gdEscapeHTML(sub||"")}</span></div>`;
}
function gdRenderLaunchMonitorAdmin(){
  const root=document.getElementById("gdLaunchMonitorAdminResult");
  if(!root)return;
  const api=window.GolfDaddyLaunchMonitorData;
  if(!api||typeof api.analyze!=="function"){
    root.innerHTML=gdLmAdminRow("Status","Module not loaded","Check script order","needs_more_data");
    return;
  }
  const analysis=api.analyze();
  const totals=analysis.totals||{};
  if(!totals.rawShots){
    root.innerHTML=gdLmAdminRow("Status","No launch monitor data","Upload plain text launch monitor shots.","needs_more_data");
    return;
  }
  const rec=analysis.recommendation||{};
  const result=analysis.methods&&analysis.methods.resultScaledCluster||{};
  const delivery=analysis.methods&&analysis.methods.deliveryCluster||{};
  const offset=Number.isFinite(Number(rec.offsetDeg))?gdOffsetLabel(rec.offsetDeg):"—";
  root.innerHTML=[
    gdLmAdminRow("Recommendation",`${gdEscapeHTML(rec.status||"needs_more_data")} · ${offset}`,`${totals.accepted||0} accepted · ${totals.rejected||0} scrapped`,rec.status),
    `<div class="gdLmRows">`,
    gdLmAdminRow("Result pattern",result.status||"needs_more_data",`Anchor ${result.anchorClub||"—"} ${Number.isFinite(Number(result.anchorDeg))?gdOffsetLabel(result.anchorDeg):"—"} · ${((result.verificationClubs||[]).join(", ")||"no verification")}`,result.status),
    gdLmAdminRow("Delivery pattern",delivery.status||"needs_more_data",`Anchor ${delivery.anchorClub||"—"} ${Number.isFinite(Number(delivery.anchorDeg))?gdOffsetLabel(delivery.anchorDeg):"—"} · delta ${Number.isFinite(Number(delivery.resultDeltaDeg))?gdOffsetLabel(delivery.resultDeltaDeg):"—"}`,delivery.status),
    `</div>`
  ].join("");
}

