function updateMapSourceUI(){
  const current=mapSources[activeMapSourceIndex];
  const btn=document.getElementById("mapSourceBtn");
  const sub=document.getElementById("mapSourceSub");
  if(btn)btn.textContent=current.name;
  if(sub)sub.textContent=current.label;
}

function setMapSource(index, reason="manual"){
  activeMapSourceIndex=((index%mapSources.length)+mapSources.length)%mapSources.length;
  window.gdActiveMapSourceIndex=activeMapSourceIndex;
  const current=mapSources[activeMapSourceIndex];

  if(baseLayer){
    try{map.removeLayer(baseLayer)}catch(e){}
  }

  baseLayer=L.tileLayer(current.tileUrl,current.options).addTo(map);
  updateMapSourceUI();

  baseLayer.once("load",()=>{
    if(reason==="security"){
      toast(`Switched to ${current.name}`);
    }
  });
}

function cycleMapSource(){
  autoSwitchedForSecurity=false;
  setMapSource(activeMapSourceIndex+1,"manual");
}

function autoSwitchMapSource(){
  if(mapSources.length<2) return false;
  if(autoSwitchedForSecurity) return false;

  autoSwitchedForSecurity=true;
  const next=(activeMapSourceIndex+1)%mapSources.length;
  if(next===activeMapSourceIndex) return false;

  setMapSource(next,"security");
  return true;
}

