function applyMapRotationFromShot(){
  if(!canApplyShotUpRotation()){
    clearMapRotation();
    return;
  }

  const axis=gdShotUpAxis();
  if(!axis){
    clearMapRotation();
    return;
  }
  gdOrientGpsCameraToBearing(axis.bearingRad,axis.source||"shot");
}
function clearMapRotation(){
  clearTimeout(shotCameraTimer);
  clearTimeout(shotAlignTimer);
  shotLineAligned=false;
  orientationAfterPlacementLocked=false;
  currentMapRotation=0;
  gdApplyGpsMapCameraTransform();
}

function gdApplyGpsMapCameraTransform(opts={}){
  const mapEl=document.getElementById("map");
  if(!mapEl) return;
  const immediate=!!opts.immediate;
  mapEl.style.transformOrigin="50% 50%";
  mapEl.style.transition=immediate?"none":"transform .26s ease, filter .25s ease";
  mapEl.style.transform=`rotate(${currentMapRotation}deg) scale(1)`;
  if(immediate)requestAnimationFrame(()=>{try{mapEl.style.transition="transform .26s ease, filter .25s ease";}catch(e){}});
}

function gdOrientGpsCameraToBearing(bearingRad,source="mapped",opts={}){
  if(!Number.isFinite(Number(bearingRad)))return false;
  currentMapRotation=-(Number(bearingRad)*180/Math.PI);
  window.gdCurrentShotUpAxis=source;
  gdApplyGpsMapCameraTransform(opts);
  return true;
}
window.gdOrientGpsCameraToBearing=gdOrientGpsCameraToBearing;

function canApplyShotUpRotation(){
  // Only rotate once the target/bubble has actually been placed.
  return !!(shotUpFrame && start && target && mode === "aim");
}

function gdFrameDisplayTarget(){
  try{
    if(typeof gdShotDisplayTarget==="function"){
      const visible=gdShotDisplayTarget();
      if(visible)return visible;
    }
  }catch(e){}
  return target;
}
function gdUpdateFocusFrameGeometry(){
  const frameTarget=gdFrameNorthTarget()||gdFrameDisplayTarget()||target;
  if(!start||!frameTarget)return false;
  gdFocusFrameStart=L.latLng(start.lat,start.lng);
  gdFocusFrameTarget=L.latLng(frameTarget.lat,frameTarget.lng);
  return true;
}
function gdGreenNorthFrameIntent(displayTarget=gdFrameDisplayTarget()){
  if(!start||!greenCentre||!map)return false;
  const greenM=map.distance(start,greenCentre);
  const displayGap=displayTarget?map.distance(displayTarget,greenCentre):Infinity;
  const maxPlayable=typeof gdMaxPlayableCarryM==="function"?gdMaxPlayableCarryM():null;
  if(displayGap<=45)return true;
  if(targetWasMoved&&gdFairwayLineGrabAllowed())return false;
  if(Number.isFinite(maxPlayable)&&maxPlayable>0&&greenM<=maxPlayable+6)return true;
  if(greenM<=135)return true;
  return false;
}
function gdStartIsInMappedTeeArea(radiusM=78){
  if(!start||!map)return false;
  try{
    const tee=typeof gdActiveMappedTeeStartPoint==="function"?gdActiveMappedTeeStartPoint():null;
    if(!tee)return false;
    const d=map.distance(start,tee);
    return Number.isFinite(d)&&d<=Math.max(25,Number(radiusM)||78);
  }catch(e){return false}
}
function gdFairwayLineGrabAllowed(opts={}){
  if(!start||!map)return false;
  try{
    if(document.body&&document.body.classList.contains("gdHeadToTeeFrameActive"))return gdStartIsInMappedTeeArea(opts.radiusM||110);
  }catch(e){}
  return gdStartIsInMappedTeeArea(opts.radiusM||78);
}
function gdFrameNorthTarget(){
  const displayTarget=gdFrameDisplayTarget();
  if(gdGreenNorthFrameIntent(displayTarget))return greenCentre;
  return displayTarget||target;
}
function gdLiveFrameIntent(){
  if(gdGreenNorthFrameIntent(gdFrameDisplayTarget()))return "green-north";
  return gdFairwayLineGrabAllowed()?"fairway-line":"direct-shot";
}
function gdShotUpAxis(){
  const displayTarget=gdFrameDisplayTarget()||target;
  const northTarget=gdFrameNorthTarget()||displayTarget;
  const intent=gdLiveFrameIntent();
  const direct=start&&northTarget?{source:intent,bearingRad:bearing(start,northTarget)}:null;
  if(intent!=="fairway-line")return direct;
  try{
    if(typeof window.gdMappedFairwayAxisForShot==="function"){
      const axis=window.gdMappedFairwayAxisForShot(start,displayTarget);
      if(axis&&Number.isFinite(axis.bearingRad)){
        return axis;
      }
    }
  }catch(e){}
  return direct;
}
window.gdShotUpAxis=gdShotUpAxis;
window.gdFairwayLineGrabAllowed=gdFairwayLineGrabAllowed;

function gdLiveShotFrameGeometry(){
  const axis=gdShotUpAxis();
  const frameTarget=gdFrameDisplayTarget()||target;
  const northTarget=gdFrameNorthTarget()||frameTarget;
  return {
    start:start?{lat:start.lat,lng:start.lng}:null,
    target:target?{lat:target.lat,lng:target.lng}:null,
    displayTarget:frameTarget?{lat:frameTarget.lat,lng:frameTarget.lng}:null,
    northTarget:northTarget?{lat:northTarget.lat,lng:northTarget.lng}:null,
    greenCentre:greenCentre?{lat:greenCentre.lat,lng:greenCentre.lng}:null,
    intent:gdLiveFrameIntent(),
    axis:axis?{source:axis.source,bearingRad:axis.bearingRad}:null,
    distanceM:start&&frameTarget&&map?map.distance(start,frameTarget):null,
    greenDistanceM:start&&greenCentre&&map?map.distance(start,greenCentre):null,
    rotationDeg:currentMapRotation
  };
}
window.gdLiveShotFrameGeometry=gdLiveShotFrameGeometry;

function gdGpsPlainPoint(value){
  try{
    if(!value)return null;
    const ll=typeof value.getLatLng==="function"?value.getLatLng():value;
    const lat=Number(ll&&ll.lat),lng=Number(ll&&ll.lng);
    return Number.isFinite(lat)&&Number.isFinite(lng)?{lat,lng}:null;
  }catch(e){return null}
}
function gdGpsLatLngFromPlain(value){
  const point=gdGpsPlainPoint(value);
  if(!point)return null;
  try{return L.latLng(point.lat,point.lng)}catch(e){return point}
}
window.gdGpsLiveResumeSnapshot=function(reason){
  return {
    version:1,
    reason:reason||"snapshot",
    mode:String(mode||""),
    locked:!!lockedFrame,
    start:gdGpsPlainPoint(start),
    target:gdGpsPlainPoint(target),
    green:gdGpsPlainPoint(greenCentre),
    pin:gdGpsPlainPoint(pin),
    hasShot:!!(start&&target),
    at:Date.now()
  };
};
function gdForceCapturedOverlayFromCurrentShot(reason){
  try{
    if(!start||!target||!map||typeof window.gdRenderCapturedHoleFrameShotOverlay!=="function")return false;
    const display=(typeof gdShotDisplayTarget==="function"&&(gdShotDisplayTarget()||null))||target;
    if(!display)return false;
    const distance=map.distance(start,display);
    if(!Number.isFinite(distance)||distance<=0)return false;
    const raw=typeof getGpsBubblePayload==="function"?getGpsBubblePayload(distance):null;
    const center=(typeof gdBubbleRenderCenter==="function"&&gdBubbleRenderCenter(raw))||display||target;
    const payload=typeof gdGpsBubbleDisplayPayload==="function"?gdGpsBubbleDisplayPayload(raw,distance,center):raw;
    const ok=window.gdRenderCapturedHoleFrameShotOverlay(payload,center)!==false;
    window.__gdLastForcedCapturedOverlay={ok,reason:reason||"force-captured-overlay",at:Date.now()};
    return ok;
  }catch(e){
    window.__gdLastForcedCapturedOverlay={ok:false,error:String(e&&e.message||e),reason:reason||"force-captured-overlay",at:Date.now()};
    return false;
  }
}
window.gdForceCapturedOverlayFromCurrentShot=gdForceCapturedOverlayFromCurrentShot;
window.gdGpsRestoreResumeSnapshot=function(saved,opts={}){
  const s=gdGpsLatLngFromPlain(saved&&saved.start);
  const t=gdGpsLatLngFromPlain(saved&&saved.target);
  const g=gdGpsLatLngFromPlain(saved&&(saved.green||saved.greenCentre));
  const p=gdGpsLatLngFromPlain(saved&&saved.pin);
  if(!s||!t)return false;
  try{setStart(s,false)}catch(e){start=s}
  if(g)greenCentre=g;
  if(p)pin=p;
  try{gdSetTargetFromDisplayedLanding(t)}catch(e){target=t;gdWindLandingTarget=null}
  try{
    const shown=(typeof gdShotDisplayTarget==="function"&&(gdShotDisplayTarget()||null))||target||t;
    if(!targetMarker)createTargetMarker(shown);
    else targetMarker.setLatLng(shown);
  }catch(e){}
  mode="aim";
  targetWasMoved=!!saved.targetWasMoved;
  if(saved.locked){
    lockedFrame=true;
    try{document.body.classList.add("gdLockStateFrameActive","gd-frame-hard-locked","gdCapturedHoleFrameCameraOn","gdHoleImageCameraOn")}catch(e){}
  }
  try{document.body.classList.remove("gdMappedStartPromptActive","gdManualStartPlacementActive")}catch(e){}
  try{hideHint()}catch(e){}
  try{renderShot()}catch(e){}
  gdForceCapturedOverlayFromCurrentShot("resume-engine-before-fit");
  try{updatePinLine()}catch(e){}
  if(saved.locked){
    const fitted=(()=>{try{return typeof window.gdFitLockStateFrameV19==="function"&&window.gdFitLockStateFrameV19({force:true,objectName:opts.objectName||"resumeRoundEngine",reason:opts.reason||"resume-round-engine"})}catch(e){return false}})();
    if(!fitted)try{lockFrame(true)}catch(e){}
    try{if(typeof setBubbleOnlyLock==="function")setBubbleOnlyLock(true)}catch(e){}
    try{renderShot()}catch(e){}
    gdForceCapturedOverlayFromCurrentShot("resume-engine-after-fit");
  }
  return true;
};

function scheduleShotLineAlignment(){
  if(!canApplyShotUpRotation()) return;

  clearTimeout(shotAlignTimer);
  shotAlignTimer=setTimeout(()=>{
    if(!canApplyShotUpRotation()) return;
    applyMapRotationFromShot();
    shotLineAligned=true;
  },180);
}

function applyShotUpAfterPlacement(){
  if(!canApplyShotUpRotation()){
    if(document.body.classList.contains("gdMappedStartPromptActive"))return;
    clearMapRotation();
    return;
  }

  // Frame/graphics update first. Then align once after the placement settles.
  clearTimeout(shotCameraTimer);
  shotCameraTimer=setTimeout(()=>{
    orientationAfterPlacementLocked=true;
    scheduleShotLineAlignment();
  },60);
}



function toggleSearchViewMode(){
  searchViewMode = searchViewMode==="browse" ? "phone" : "browse";
  document.getElementById("pinModeToggle").textContent = searchViewMode==="browse" ? "Browse" : "Phone";
  document.getElementById("pinModeSub").textContent = searchViewMode==="browse" ? "500m browse helper" : "Phone direction helper";
  if(searchViewMode==="phone") startOrientation();
}
function cycleFrameTightness(){
  if(lockFrameTightness===0.62){
    lockFrameTightness=0.48;
    document.getElementById("frameTightToggle").textContent="Very tight";
    document.getElementById("frameTightSub").textContent="Maximum shot focus";
  }else if(lockFrameTightness===0.48){
    lockFrameTightness=0.82;
    document.getElementById("frameTightToggle").textContent="Roomy";
    document.getElementById("frameTightSub").textContent="More context";
  }else{
    lockFrameTightness=0.62;
    document.getElementById("frameTightToggle").textContent="Tight";
    document.getElementById("frameTightSub").textContent="Tight shot focus";
  }
  if(start&&target&&lockedFrame) lockFrame(false); applyShotUpAfterPlacement();
}
async function startOrientation(){
  if(orientationListening) return;

  try{
    if(typeof DeviceOrientationEvent !== "undefined" && typeof DeviceOrientationEvent.requestPermission === "function"){
      const res = await DeviceOrientationEvent.requestPermission();
      if(res !== "granted") return;
    }
  }catch(e){}

  window.addEventListener("deviceorientation", e=>{
    // iOS gives webkitCompassHeading. Other browsers may give alpha.
    if(typeof e.webkitCompassHeading === "number"){
      phoneHeading = e.webkitCompassHeading;
    }else if(typeof e.alpha === "number"){
      phoneHeading = 360 - e.alpha;
    }

    if(searchViewMode==="phone" && start && mode==="green"){
      drawPhoneDirectionHelper();
    }
  }, true);

  orientationListening=true;
}
function showSearchView(){
  closeAllPanels();
  clearSoftActive();
  setSoftActive("searchViewBtn",true);
  clearMapRotation();
  if(!start || mode!=="green") return;

  if(pinDirectionLine){
    map.removeLayer(pinDirectionLine);
    pinDirectionLine=null;
  }

  if(searchViewMode==="phone"){
    startOrientation();
    framePhoneDirection();
    drawPhoneDirectionHelper();
    setState("Search · phone direction");
  }else{
    frameBrowseAroundStart();
    setState("Search · 500m browse");
  }
}
function frameBrowseAroundStart(){
  if(!start) return;

  // Default green-pinning view: roughly 500m each way from the ball.
  const north=project(start,0,500);
  const south=project(start,Math.PI,500);
  const east=project(start,Math.PI/2,500);
  const west=project(start,Math.PI*1.5,500);

  map.fitBounds(L.latLngBounds([north,south,east,west]),{
    paddingTopLeft:[35,115],
    paddingBottomRight:[35,105],
    animate:true,
    duration:.45,
    maxZoom:17
  });
}
function framePhoneDirection(){
  if(!start) return;

  const headingDeg = phoneHeading ?? 0;
  const a = headingDeg * Math.PI / 180;

  // Phone method: no target placed. Just frames the likely shot/search direction.
  const ahead=project(start,a,520);
  const behind=project(start,a+Math.PI,45);
  const left=projectOffset(start,a,250,-170);
  const right=projectOffset(start,a,250,170);

  map.fitBounds(L.latLngBounds([ahead,behind,left,right]),{
    paddingTopLeft:[35,115],
    paddingBottomRight:[35,105],
    animate:true,
    duration:.45,
    maxZoom:18
  });
}
function drawPhoneDirectionHelper(){
  if(!start) return;
  if(pinDirectionLine){
    map.removeLayer(pinDirectionLine);
    pinDirectionLine=null;
  }

  const headingDeg = phoneHeading ?? 0;
  const a = headingDeg * Math.PI / 180;
  const ahead = project(start,a,420);

  pinDirectionLine=L.polyline([start,ahead],{
    color:"#1fd36d",
    weight:2,
    opacity:.42,
    dashArray:"6,10"
  }).addTo(map);
}


/* ---------------- Bubble Behaviour / Frame Lock v1 ----------------
   The shot stays framed. Once locked, the map is frozen and the shot
   bubble keeps its own gesture lane. */
function setMapGestures(enabled){
  if(!map) return;
  ["dragging","touchZoom","doubleClickZoom","scrollWheelZoom","boxZoom","keyboard"].forEach(k=>{
    try{ map[k] && (enabled ? map[k].enable() : map[k].disable()); }catch(e){}
  });
  try{ if(map.tap) enabled ? map.tap.enable() : map.tap.disable(); }catch(e){}
  document.body.classList.toggle("gd-frame-hard-locked", !enabled);
}
function setBubbleOnlyLock(on){
  lockedFrame=!!on;
  if(lockedFrame)gdUpdateFocusFrameGeometry();
  if(!lockedFrame){
    gdFocusFrameStart=null;
    gdFocusFrameTarget=null;
    gdSimpleGreenZoomActive=false;
    gdSimpleGreenZoomReturnView=null;
    try{document.body.classList.remove("gd-green-zoom-active");document.getElementById("gdGreenZoomBtn")?.classList.remove("softActive");}catch(e){}
  }
  setMapGestures(!lockedFrame);
  app.classList.toggle("framed", showFilter&&lockedFrame);
  if(lockedFrame)app.classList.remove("gdPreLockFrame");
  gdApplyGpsMapCameraTransform();
  const btn=document.getElementById("frameLockBtn");
  if(btn) btn.classList.toggle("softActive", lockedFrame);
  if(lockedFrame){
    setState("Locked · move shot target");
    hideHint();
  }
}

function gdScreenTargetFrameRatios(kind="lock"){
  // Ratios based on Sam's marked frame guide. These are real invisible camera frames:
  // object bounds should fill the chosen box, not merely sit near its centre.
  const frame={
    // Medium locked-in frame: green/bubble should own this area in normal lock-in.
    lock:{left:.247,top:.203,width:.497,height:.222},
    // Tightest green/hole frame: reserved for saved green / hole-object framing.
    hole:{left:.308,top:.203,width:.375,height:.160},
    // Largest green/landing zoom frame: optional button fills this bigger area.
    zoom:{left:.152,top:.203,width:.687,height:.316},
    // Tee frame sits just above the bottom controls for future tee/origin framing.
    tee:{left:.308,top:.881,width:.375,height:.037}
  }[kind]||{left:.247,top:.203,width:.497,height:.222};
  return Object.assign({},frame,{right:Math.max(0,1-frame.left-frame.width),bottom:Math.max(0,1-frame.top-frame.height)});
}
function gdScreenTargetFrameConfig(kind="lock"){
  const w=window.innerWidth||document.documentElement.clientWidth||390;
  const h=window.innerHeight||document.documentElement.clientHeight||760;
  const frame=gdScreenTargetFrameRatios(kind);
  return {
    left:Math.round(w*frame.left),
    right:Math.round(w*frame.right),
    top:Math.round(h*frame.top),
    bottom:Math.round(h*frame.bottom)
  };
}
function gdTargetFramePadding(kind="lock"){
  const f=gdScreenTargetFrameConfig(kind);
  return {paddingTopLeft:[f.left,f.top],paddingBottomRight:[f.right,f.bottom]};
}
function gdActiveGreenZoomTarget(){
  try{
    if(typeof gdShotDisplayTarget==="function"){
      const shown=gdShotDisplayTarget();
      if(shown)return shown;
    }
  }catch(e){}
  return target||greenCentre||pin||start;
}
function gdFrameAroundPoint(point,kind="zoom"){
  if(!map||!point)return false;
  const pad=gdTargetFramePadding(kind);
  const zoom=Math.min(20,Math.max(map.getZoom?map.getZoom()+2:19,19));
  try{
    map.setView(point,zoom,{animate:true,duration:.32,paddingTopLeft:pad.paddingTopLeft,paddingBottomRight:pad.paddingBottomRight});
  }catch(e){
    try{map.setView(point,zoom,{animate:true,duration:.32});}catch(_e){return false;}
  }
  return true;
}
function gdToggleSimpleGreenZoom(ev){
  if(ev){ev.preventDefault();ev.stopPropagation();if(ev.stopImmediatePropagation)ev.stopImmediatePropagation();}
  if(!map)return false;
  if(gdSimpleGreenZoomActive){
    gdSimpleGreenZoomActive=false;
    document.body.classList.remove("gd-green-zoom-active");
    const b=document.getElementById("gdGreenZoomBtn");
    if(b)b.classList.remove("softActive");
    const v=gdSimpleGreenZoomReturnView;
    gdSimpleGreenZoomReturnView=null;
    if(v&&v.center){try{map.setView(v.center,v.zoom,{animate:true,duration:.32});}catch(e){}}
    return false;
  }
  const focus=gdActiveGreenZoomTarget();
  if(!focus){try{toast("Set a shot target first")}catch(e){};return false;}
  try{gdSimpleGreenZoomReturnView={center:map.getCenter(),zoom:map.getZoom()};}catch(e){gdSimpleGreenZoomReturnView=null;}
  gdSimpleGreenZoomActive=true;
  document.body.classList.add("gd-green-zoom-active");
  const b=document.getElementById("gdGreenZoomBtn");
  if(b)b.classList.add("softActive");
  gdFrameAroundPoint(focus,"zoom");
  return false;
}
window.gdToggleSimpleGreenZoom=gdToggleSimpleGreenZoom;

function frameShotView(){
  if(!start||!target) return;
  const displayTarget=gdFrameDisplayTarget()||target;
  const frameTarget=gdFrameNorthTarget()||displayTarget;
  if(!frameTarget)return;
  const axis=gdShotUpAxis();
  const shotBrg=axis&&Number.isFinite(axis.bearingRad)?axis.bearingRad:bearing(start,frameTarget);
  const shotM=Math.max(1,map.distance(start,displayTarget||frameTarget));
  const shortShot=shotM<95;
  const back=project(start,shotBrg+Math.PI,shortShot?Math.max(12,26*lockFrameTightness):Math.max(18,40*lockFrameTightness));
  const beyond=project(frameTarget,shotBrg,shortShot?Math.max(24,58*lockFrameTightness):Math.max(55,115*lockFrameTightness));
  const mid=project(start,shotBrg,shotM*0.56);
  const lateral=shortShot?Math.max(34,64*lockFrameTightness):Math.max(48,90*lockFrameTightness);
  const left=projectOffset(mid,shotBrg,0,-lateral);
  const right=projectOffset(mid,shotBrg,0,lateral);
  const points=[back,beyond,left,right,start,frameTarget];
  if(displayTarget)points.push(displayTarget);
  if(greenCentre)points.push(greenCentre);
  if(pin)points.push(pin);
  const pad=gdTargetFramePadding("lock");
  map.fitBounds(L.latLngBounds(points),{
    paddingTopLeft:pad.paddingTopLeft,
    paddingBottomRight:pad.paddingBottomRight,
    animate:true,
    duration:.42,
    maxZoom:19
  });
}
function lockFrame(refit=true){
  if(!start||!target) return;
  if(refit && !lockedFrame){
    try{
      frameShotView();
    }catch(e){
      console.warn("[GolfDaddy] shot frame refit failed; locking current view",e);
      try{
        const centre=gdShotDisplayTarget&&gdShotDisplayTarget()?gdShotDisplayTarget():target;
        if(map&&centre&&map.setView)map.setView(centre,Math.max(map.getZoom?map.getZoom():18,18),{animate:true,duration:.25});
      }catch(_e){}
    }
  }
  setBubbleOnlyLock(true);
  renderShot();
}
function unlockFrameForReset(){
  setBubbleOnlyLock(false);
  clearMapRotation();
}
function moveBubbleTo(ll,saveUndo=true){
  if(!ll||!start) return;
  if(saveUndo&&target) undoStack.push({type:"target",value:L.latLng(target.lat,target.lng)});
  gdSetTargetFromDisplayedLanding(ll);
  targetWasMoved=true;
  gdMarkCurrentPlanDirty();
  if(targetMarker) targetMarker.setLatLng(gdShotDisplayTarget()||target);
  renderShot();
  updatePinLine();
}
function gdActiveShotBagRows(){
  try{return gdAccountShotBagRows();}catch(e){return []}
}
function gdHasPlayableBag(){
  try{return gdPlayableShotBagRows().length>0;}catch(e){return false}
}
function gdMaxPlayableCarryM(){
  try{
    const totals=gdPlayableShotBagRows().map(gdTotalM).filter(n=>Number.isFinite(n)&&n>0);
    return totals.length?Math.max(...totals):null;
  }catch(e){return null}
}
function gdTargetForGreenCentre(center,opts={}){
  if(typeof gdTournamentModeEnabled==="function"&&gdTournamentModeEnabled())return center;
  if(!start||!center)return center;
  const maxCarry=gdMaxPlayableCarryM();
  if(!(maxCarry>0))return center;
  const d=map.distance(start,center);
  if(d<=maxCarry+3)return center;
  try{
    const fairwayTarget=gdFairwayLineGrabAllowed()&&typeof window.gdMappedFairwayLayupTarget==="function"?window.gdMappedFairwayLayupTarget(start,center,maxCarry,{hole:opts.hole||gdMappedStartHoleNumber?.()}):null;
    if(fairwayTarget)return fairwayTarget;
  }catch(e){}
  return project(start,bearing(start,center),maxCarry);
}
function gdWindIconMarkup(){
  return '<svg aria-hidden="true" viewBox="0 0 48 48"><path d="M9 17h20c4.4 0 6.6-5.4 3.5-8.5-2.4-2.4-6.5-1.5-7.6 1.7" fill="none" stroke="currentColor" stroke-width="4" stroke-linecap="round"/><path d="M8 25h28c5.2 0 7.8 6.3 4.1 10-2.9 2.9-7.8 1.7-9.1-2.1" fill="none" stroke="currentColor" stroke-width="4" stroke-linecap="round"/><path d="M13 33h11" fill="none" stroke="currentColor" stroke-width="4" stroke-linecap="round"/></svg>';
}
function gdNormAngle(a){
  const full=Math.PI*2;
  return ((Number(a)||0)%full+full)%full;
}
function gdLiveWindEnabled(){
  return typeof dev==="function"?Number(dev("liveWind.enabled"))!==0:true;
}
function gdLiveWindFresh(){
  const maxMs=Math.max(5,Number(typeof dev==="function"?dev("liveWind.cacheMinutes"):25)||25)*60000;
  return !!(gdLiveWindState.data&&Date.now()-Number(gdLiveWindState.data.fetchedAt||0)<=maxMs);
}
function gdWindLevelForSpeed(kmh){
  const speed=Number(kmh);
  const level3=Math.max(8,Number(typeof dev==="function"?dev("liveWind.level3Kmh"):24)||24);
  const level2=Math.max(4,Number(typeof dev==="function"?dev("liveWind.level2Kmh"):13)||13);
  if(!Number.isFinite(speed))return 1;
  if(speed>=level3)return 3;
  if(speed>=level2)return 2;
  return 1;
}
function gdLiveWindLocation(){
  try{if(start)return {lat:Number(start.lat),lng:Number(start.lng),source:"gps-start"};}catch(e){}
  try{
    const c=JSON.parse(localStorage.getItem("gd_active_course_v1")||"null");
    const lat=Number(c?.lat??c?.courseLat??c?.finderLat);
    const lng=Number(c?.lng??c?.courseLng??c?.finderLng);
    if(Number.isFinite(lat)&&Number.isFinite(lng))return {lat,lng,source:"course"};
  }catch(e){}
  try{
    const c=typeof courseObj==="function"?courseObj():currentCourse;
    const lat=Number(c?.lat??c?.courseLat??c?.finderLat);
    const lng=Number(c?.lng??c?.courseLng??c?.finderLng);
    if(Number.isFinite(lat)&&Number.isFinite(lng))return {lat,lng,source:"course-object"};
  }catch(e){}
  try{
    const c=map?.getCenter?.();
    if(c)return {lat:Number(c.lat),lng:Number(c.lng),source:"map"};
  }catch(e){}
  return null;
}
async function gdFetchLiveWind(opts={}){
  if(!gdLiveWindEnabled())return null;
  if(!opts.force&&gdLiveWindFresh())return gdLiveWindState.data;
  if(gdLiveWindState.loading)return gdLiveWindState.data;
  const loc=gdLiveWindLocation();
  if(!loc)return null;
  gdLiveWindState.loading=true;
  gdLiveWindState.error="";
  gdSyncWindButton();
  try{
    const url=`https://api.open-meteo.com/v1/forecast?latitude=${encodeURIComponent(loc.lat.toFixed(5))}&longitude=${encodeURIComponent(loc.lng.toFixed(5))}&current=wind_speed_10m,wind_direction_10m,wind_gusts_10m&wind_speed_unit=kmh&timezone=auto`;
    const res=await fetch(url,{headers:{Accept:"application/json"},cache:"no-store"});
    if(!res.ok)throw new Error("wind fetch failed");
    const json=await res.json();
    const cur=json&&json.current||{};
    const speed=Number(cur.wind_speed_10m);
    const direction=Number(cur.wind_direction_10m);
    if(!Number.isFinite(speed)||!Number.isFinite(direction))throw new Error("wind data missing");
    gdLiveWindState.data={
      speedKmh:speed,
      directionDeg:direction,
      gustKmh:Number.isFinite(Number(cur.wind_gusts_10m))?Number(cur.wind_gusts_10m):null,
      level:gdWindLevelForSpeed(speed),
      at:cur.time||new Date().toISOString(),
      fetchedAt:Date.now(),
      source:"Open-Meteo",
      location:loc
    };
    return gdLiveWindState.data;
  }catch(e){
    gdLiveWindState.error=e&&e.message?e.message:"wind unavailable";
    return null;
  }finally{
    gdLiveWindState.loading=false;
    gdSyncWindButton();
  }
}
function gdApplyLiveWind(data,render=true){
  data=data||gdLiveWindState.data;
  if(!data||!Number.isFinite(Number(data.directionDeg)))return false;
  gdWindOriginAngle=gdNormAngle(Number(data.directionDeg)*Math.PI/180);
  gdWindLevel=Math.max(1,Math.min(3,Number(data.level)||gdWindLevelForSpeed(data.speedKmh)));
  gdWindActive=true;
  gdWindSelectionSource="live";
  gdCloseWindPicker();
  gdApplyWindToCurrentShot(render);
  gdSyncWindButton();
  try{toast(`Live wind ${gdWindLevel}`)}catch(e){}
  return true;
}
function gdHasWindVector(){
  if(typeof gdTournamentModeEnabled==="function"&&gdTournamentModeEnabled())return false;
  return !!gdWindActive&&Number.isFinite(Number(gdWindOriginAngle));
}
function gdWindEffectMeters(aimPoint=target){
  const basis=start&&aimPoint?map.distance(start,aimPoint):(start&&greenCentre?map.distance(start,greenCentre):140);
  const carry=Math.max(40,Math.min(260,Number(basis)||140));
  const base=Math.max(4,Math.min(12,carry*.045));
  return base*Math.max(1,Math.min(3,Number(gdWindLevel)||1));
}
function gdWindLandingFromAim(aimPoint){
  if(!aimPoint||!gdHasWindVector())return aimPoint||null;
  return project(aimPoint,gdNormAngle(gdWindOriginAngle+Math.PI),gdWindEffectMeters(aimPoint));
}
function gdWindAimForLanding(landingPoint){
  if(!landingPoint||!gdHasWindVector())return landingPoint||null;
  let aim=L.latLng(landingPoint.lat,landingPoint.lng);
  for(let i=0;i<3;i++){
    aim=project(landingPoint,gdWindOriginAngle,gdWindEffectMeters(aim));
  }
  return aim;
}
function gdShotDisplayTarget(){
  if(gdHasWindVector()&&gdWindLandingTarget)return gdWindLandingTarget;
  return target;
}
function gdSyncWindLandingFromAim(){
  if(!gdHasWindVector()||!target){gdWindLandingTarget=null;return null;}
  gdWindLandingTarget=gdWindLandingFromAim(target);
  return gdWindLandingTarget;
}
function gdSetTargetFromDisplayedLanding(ll){
  if(!ll)return;
  if(gdHasWindVector()){
    gdWindLandingTarget=L.latLng(ll.lat,ll.lng);
    target=gdWindAimForLanding(gdWindLandingTarget);
  }else{
    target=ll;
    gdWindLandingTarget=null;
  }
}
function gdClearWindVisuals(){
  [gdWindEffectLine,gdWindAimMarker].forEach(l=>{try{if(l)map.removeLayer(l)}catch(e){}});
  gdWindEffectLine=gdWindAimMarker=null;
}
function gdRenderWindEffect(){
  gdClearWindVisuals();
  if(!gdHasWindVector()||!target||!gdWindLandingTarget)return;
  const drift=map.distance(target,gdWindLandingTarget);
  if(!(drift>.5))return;
  gdWindEffectLine=L.polyline([target,gdWindLandingTarget],{color:"#66dcff",weight:3,opacity:.82,dashArray:"6,8",interactive:false}).addTo(map);
  gdWindAimMarker=L.marker(target,{interactive:false,icon:L.divIcon({className:"",html:'<div class="gdWindAimDot"></div>',iconSize:[18,18],iconAnchor:[9,9]})}).addTo(map);
}
function gdApplyWindToCurrentShot(render=true){
  if(!gdHasWindVector()||!target){gdWindLandingTarget=null;gdClearWindVisuals();gdSyncWindButton();return false;}
  gdSyncWindLandingFromAim();
  const visible=gdShotDisplayTarget();
  if(targetMarker&&visible)targetMarker.setLatLng(visible);
  if(render){renderShot();updatePinLine();}
  gdSyncWindButton();
  return true;
}
function gdOpenWindPicker(){
  const picker=document.getElementById("gdWindPicker");
  if(!picker)return;
  picker.classList.remove("hidden");
  picker.setAttribute("aria-hidden","false");
}
function gdCloseWindPicker(){
  const picker=document.getElementById("gdWindPicker");
  if(!picker)return;
  picker.classList.add("hidden");
  picker.setAttribute("aria-hidden","true");
}
function gdSyncWindButton(){
  const btn=document.getElementById("windToolBtn");
  if(!btn)return;
  const active=gdHasWindVector();
  const ready=!active&&gdLiveWindEnabled()&&gdLiveWindFresh();
  btn.classList.toggle("windActive",active);
  btn.classList.toggle("windReady",ready);
  btn.classList.toggle("windLoading",!!gdLiveWindState.loading);
  btn.setAttribute("aria-label",active?`Wind ${gdWindLevel}`:(ready?"Live wind ready":"Wind"));
  btn.title=active?`Wind ${gdWindLevel}`:(ready?"Live wind ready":"Wind");
  const html=active?`<span class="gdWindLevelText">${gdWindLevel}</span>`:gdWindIconMarkup();
  if(btn.dataset.gdWindHtml!==html){
    btn.innerHTML=html;
    btn.dataset.gdWindHtml=html;
  }
}
async function gdWindToolPressed(event){
  if(event){event.preventDefault?.();event.stopPropagation?.();event.stopImmediatePropagation?.();}
  if(Date.now()<gdWindLongPressSuppressUntil)return false;
  if(typeof gdTournamentModeEnabled==="function"&&gdTournamentModeEnabled()){
    try{toast("Wind off in tournament mode")}catch(e){}
    return false;
  }
  if(!gdHasWindVector()){
    if(gdLiveWindEnabled()){
      const live=gdLiveWindFresh()?gdLiveWindState.data:await gdFetchLiveWind();
      if(live&&gdApplyLiveWind(live,true))return false;
      try{toast("Live wind unavailable")}catch(e){}
    }
    gdOpenWindPicker();
    gdSyncWindButton();
    return false;
  }
  if(gdWindLevel>=3){
    gdWindActive=false;
    gdWindOriginAngle=null;
    gdWindLandingTarget=null;
    gdWindSelectionSource=null;
    gdClearWindVisuals();
    if(targetMarker&&target)targetMarker.setLatLng(target);
    renderShot();
    updatePinLine();
    gdSyncWindButton();
    try{toast("Wind off")}catch(e){}
    return false;
  }
  gdWindLevel=gdWindLevel+1;
  gdWindSelectionSource="user";
  gdApplyWindToCurrentShot(true);
  try{toast(`Wind ${gdWindLevel}`)}catch(e){}
  return false;
}
function gdWindPickDirection(event){
  if(event){event.preventDefault?.();event.stopPropagation?.();}
  const picker=document.getElementById("gdWindPicker");
  const rect=picker?.getBoundingClientRect?.();
  if(!rect)return false;
  const cx=rect.left+rect.width/2;
  const cy=rect.top+rect.height/2;
  const dx=event.clientX-cx;
  const dy=event.clientY-cy;
  if(Math.sqrt(dx*dx+dy*dy)<22){try{toast("Tap wind origin near the edge")}catch(e){};return false;}
  const screenAngle=Math.atan2(dx,-dy);
  const mapRotation=((Number(currentMapRotation)||0)*Math.PI)/180;
  gdWindOriginAngle=gdNormAngle(screenAngle-mapRotation);
  gdWindActive=true;
  gdWindLevel=1;
  gdWindSelectionSource="user";
  gdCloseWindPicker();
  gdApplyWindToCurrentShot(true);
  gdSyncWindButton();
  try{toast("Wind 1")}catch(e){}
  return false;
}
window.gdWindToolPressed=gdWindToolPressed;
window.gdWindPickDirection=gdWindPickDirection;
window.gdFetchLiveWind=gdFetchLiveWind;
window.gdApplyLiveWind=gdApplyLiveWind;
function gdInstallWindLongPress(){
  const btn=document.getElementById("windToolBtn");
  if(!btn||btn.__gdWindLongPressInstalled)return;
  btn.__gdWindLongPressInstalled=true;
  let press=null;
  btn.addEventListener("pointerdown",ev=>{
    if(ev.button!=null&&ev.button!==0)return;
    press={id:ev.pointerId,x:ev.clientX,y:ev.clientY,long:false,timer:null};
    press.timer=setTimeout(()=>{
      if(!press)return;
      press.long=true;
      gdWindLongPressSuppressUntil=Date.now()+650;
      gdOpenWindPicker();
      try{toast("Set wind direction")}catch(e){}
    },560);
  },true);
  btn.addEventListener("pointermove",ev=>{
    if(!press||press.id!==ev.pointerId)return;
    if(Math.hypot((ev.clientX||0)-press.x,(ev.clientY||0)-press.y)>10){
      clearTimeout(press.timer);
      press=null;
    }
  },true);
  ["pointerup","pointercancel"].forEach(type=>btn.addEventListener(type,ev=>{
    if(!press||press.id!==ev.pointerId)return;
    const wasLong=press.long;
    clearTimeout(press.timer);
    press=null;
    if(wasLong){
      ev.preventDefault?.();
      ev.stopPropagation?.();
      ev.stopImmediatePropagation?.();
    }
  },true));
}
if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",()=>{gdInstallWindLongPress();gdFetchLiveWind({}).catch(()=>null);});
else{gdInstallWindLongPress();setTimeout(()=>gdFetchLiveWind({}).catch(()=>null),400);}
setTimeout(gdSyncWindButton,0);
function gdIsLayupTarget(center,targetPoint){
  if(!center||!targetPoint)return false;
  return map.distance(center,targetPoint)>4;
}


/* ---------------- Course flow ---------------- */
function gdCoursePickerFinitePoint(point){
  if(!point)return null;
  const rawLat=point.lat;
  const rawLng=point.lng??point.lon;
  if(rawLat==null||rawLat===""||rawLng==null||rawLng==="")return null;
  const lat=Number(rawLat);
  const lng=Number(rawLng);
  return Number.isFinite(lat)&&Number.isFinite(lng)?{lat,lng}:null;
}
function gdCoursePickerNeutralPoint(point){
  const p=gdCoursePickerFinitePoint(point);
  return !!(p&&Math.abs(p.lat)<0.000001&&Math.abs(p.lng)<0.000001);
}
function gdCoursePickerRecentGpsPoint(maxAgeMs=10*60*1000){
  try{
    const state=window.gdGpsState||{};
    const fix=state.lastFix;
    const at=Number(state.lastFixAt||0);
    const point=gdCoursePickerFinitePoint(fix);
    if(!point)return null;
    if(!Number.isFinite(at)||at<=0||Date.now()-at>maxAgeMs)return null;
    if(state.permissionKnown===true&&state.permissionGranted!==true)return null;
    if(fix&&fix.simulated===true)return null;
    const source=String(fix?.source||"").toLowerCase();
    if(/manual|tap|click|map|green-focus|pin/.test(source))return null;
    return point;
  }catch(e){return null}
}
function gdCoursePickerPayloadHasPoint(payload){
  return !!gdCoursePickerFinitePoint(payload);
}
function gdCoursePickerSetDatasetPoint(element,payload){
  if(!element)return;
  const point=gdCoursePickerFinitePoint(payload);
  element.dataset.gdCourseLat=point?String(point.lat):"";
  element.dataset.gdCourseLng=point?String(point.lng):"";
}
function gdCoursePickerDefaultPoint(){
  try{const point=gdCoursePickerFinitePoint(window.start);if(point)return point;}catch(e){}
  const gps=gdCoursePickerRecentGpsPoint();
  if(gps)return gps;
  try{
    if(window.map&&typeof map.getCenter==="function"){
      const center=map.getCenter();
      const point=gdCoursePickerFinitePoint(center);
      if(point&&!gdCoursePickerNeutralPoint(point))return point;
    }
  }catch(e){}
  return null;
}
function gdAssumedCourseLabelForPicker(point=gdCoursePickerDefaultPoint()){
  const lat=Number(point?.lat),lng=Number(point?.lng);
  if(Number.isFinite(lat)&&Number.isFinite(lng))return `Assumed course ${lat.toFixed(2)}, ${lng.toFixed(2)}`;
  return "Assumed course";
}
function gdCurrentAssumedCoursePayload(){
  try{
    if(typeof window.gdRefreshCourseAssumedNearby==="function"&&!window.__gdRenderingNearbyCourseSuggestion){
      const nearby=window.gdRefreshCourseAssumedNearby();
      if(nearby&&nearby.name)return gdNormalizeCoursePickerPayload(nearby);
    }
  }catch(e){}
  const point=gdCoursePickerDefaultPoint();
  return gdNormalizeCoursePickerPayload({
    name:"Manual GPS",
    lat:point?.lat??null,
    lng:point?.lng??null,
    assumedCandidate:false,
    source:"manual-gps"
  });
}
function gdRefreshCourseAssumedOption(course){
  const payload=gdNormalizeCoursePickerPayload(course&&course.assumedCandidate?course:gdCurrentAssumedCoursePayload());
  const name=document.getElementById("gdCourseAssumedName");
  const button=document.getElementById("gdCourseAssumedPlayBtn");
  const option=document.getElementById("gdCourseAssumedOption");
  if(name)name.textContent=payload.name;
  if(button)button.textContent=window.gdCourseChangeMode==="assumed-label"?"Confirm":"Play";
  if(option){
    option.__gdCoursePayload=payload;
    option.dataset.gdCourseName=payload.name;
    gdCoursePickerSetDatasetPoint(option,payload);
  }
}
function gdRefreshAssumedCourseFromLocation(fallbackCourse){
  try{
    if(typeof window.gdRefreshCourseAssumedNearby==="function"&&!window.__gdRenderingNearbyCourseSuggestion){
      const nearby=window.gdRefreshCourseAssumedNearby();
      if(nearby&&nearby.name)return gdNormalizeCoursePickerPayload(nearby);
    }
  }catch(e){}
  gdRefreshCourseAssumedOption(fallbackCourse);
  try{
    const option=document.getElementById("gdCourseAssumedOption");
    return option&&option.__gdCoursePayload?option.__gdCoursePayload:null;
  }catch(e){return null}
}
function renderCourses(courses){
  const list=document.getElementById("courseList");
  if(!list)return;
  list.innerHTML="";
  courses=Array.isArray(courses)?courses:[];
  if(courses.length===1&&courses[0]?.assumedCandidate&&document.getElementById("gdCourseAssumedOption")){
    gdRefreshAssumedCourseFromLocation(courses[0]);
    courses=[];
  }else{
    gdRefreshAssumedCourseFromLocation();
  }
  courses.forEach(c=>{
    c=gdNormalizeCoursePickerPayload(c);
    const row=document.createElement("div");
    row.className="course";
    row.__gdCoursePayload=c;
    row.dataset.gdCourseName=c.name;
    gdCoursePickerSetDatasetPoint(row,c);
    row.innerHTML=`<div><div class="name"></div><div class="meta">Course result</div></div><button class="play">Play</button>`;
    row.querySelector(".name").textContent=c.name||"Course";
    row.onclick=()=>gdOpenCoursePickerCourse(c);
    row.querySelector("button").onclick=e=>{e.preventDefault();e.stopPropagation();if(e.stopImmediatePropagation)e.stopImmediatePropagation();gdOpenCoursePickerCourse(c);return false;};
    list.appendChild(row);
  });
  const count=document.getElementById("countLine");
  if(count)count.textContent=courses.length?`${courses.length} found`:"Search";
}
function gdNormalizeCoursePickerPayload(c){
  const src=c&&typeof c==="object"?c:{};
  const name=String(src.name||src.courseName||"Manual GPS").trim()||"Manual GPS";
  const rawLat=src.lat??src.courseLat??src.latitude;
  const rawLng=src.lng??src.courseLng??src.longitude??src.lon;
  const lat=rawLat===""||rawLat==null?NaN:Number(rawLat);
  const lng=rawLng===""||rawLng==null?NaN:Number(rawLng);
  return Object.assign({},src,{
    name,
    lat:Number.isFinite(lat)?lat:null,
    lng:Number.isFinite(lng)?lng:null
  });
}
function gdCoursePickerPayloadFromRow(row){
  if(row&&row.__gdCoursePayload)return gdNormalizeCoursePickerPayload(row.__gdCoursePayload);
  const name=(row?.querySelector(".name")?.textContent||row?.dataset?.gdCourseName||"Manual GPS").trim()||"Manual GPS";
  return gdNormalizeCoursePickerPayload({
    name,
    lat:row?.dataset?.gdCourseLat,
    lng:row?.dataset?.gdCourseLng,
    courseId:row?.dataset?.gdCourseId||""
  });
}
function gdCoursePickerPayloadFromAssumedOption(){
  const option=document.getElementById("gdCourseAssumedOption");
  if(!option)return null;
  return gdNormalizeCoursePickerPayload({
    name:(option.dataset.gdCourseName||document.getElementById("gdCourseAssumedName")?.textContent||"Manual GPS").trim(),
    lat:option.dataset.gdCourseLat,
    lng:option.dataset.gdCourseLng,
    courseId:option.dataset.gdCourseId||""
  });
}
function gdCoursePickerPayloadFromRecommendedBlock(block){
  if(block&&block.__gdCoursePayload)return gdNormalizeCoursePickerPayload(block.__gdCoursePayload);
  if(!block)return gdCoursePickerPayloadFromAssumedOption();
  return gdNormalizeCoursePickerPayload({
    name:(block.dataset.gdCourseName||block.querySelector(".courseAssumedName")?.textContent||"Manual GPS").trim(),
    lat:block.dataset.gdCourseLat,
    lng:block.dataset.gdCourseLng,
    courseId:block.dataset.gdCourseId||""
  });
}
function gdCoursePickerPayloadFromSelectionElement(element){
  const recommended=element?.closest?.("#gdCourseAssumedOption .courseAssumedBlock");
  if(recommended)return gdCoursePickerPayloadFromRecommendedBlock(recommended);
  const row=element?.closest?.("#courseScreen .course");
  if(row)return gdCoursePickerPayloadFromRow(row);
  return gdCoursePickerPayloadFromAssumedOption()||gdCurrentAssumedCoursePayload();
}
function gdOpenCoursePickerSelectionFromElement(element){
  return gdOpenCoursePickerCourse(gdCoursePickerPayloadFromSelectionElement(element));
}
window.gdOpenCoursePickerSelectionFromElement=gdOpenCoursePickerSelectionFromElement;
function gdOpenChangeCourse(event){
  if(event){
    event.preventDefault?.();
    event.stopPropagation?.();
    event.stopImmediatePropagation?.();
  }
  try{window.gdCourseChangeMode="change-course";}catch(e){}
  try{window.__gdCoursePickerReturnTarget="gps";}catch(e){}
  try{
    window.__gdCoursePickerChangingAt=Date.now();
    window.__gdCoursePickerFirstHoleOpenToken=null;
    window.__gdStableMappedHoleOneLast=null;
    if(window.__gdPreLockHoleFrameTimer)clearTimeout(window.__gdPreLockHoleFrameTimer);
    if(typeof gdClearMappedStartPromptChrome==="function")gdClearMappedStartPromptChrome();
  }catch(e){}
  try{window.GDShell?.openCoursePicker?.({source:"legacy-change-course",returnTarget:"gps"});}catch(e){}
  try{
    document.body.classList.remove("gdProfileOpen","gdStatsOpen","gdBubbleStudioOpen","gdToolRailOpen","gdCourseOpening","gdCoursePinPromptActive");
    [
      "gdCourseNeedsPin",
      "gdCourseNeedsPinCourse",
      "gdCoursePinDecision",
      "gdCourseDatabaseMapAvailable",
      "gdCourseDatabaseMapSource",
      "gdCourseAutoMapStatus",
      "gdCourseAutoMappedHoles",
      "gdCourseAutoMapSaved",
      "gdCourseScannerSeed"
    ].forEach(key=>delete document.body.dataset[key]);
    window.__gdCoursePickerPinPromptActive=false;
  }catch(e){}
  try{
    const input=document.getElementById("searchInput");
    if(input)input.value="";
    renderCourses([]);
    gdRefreshAssumedCourseFromLocation();
    const count=document.getElementById("countLine");
    if(count)count.textContent="Search";
  }catch(e){}
  try{setTimeout(()=>document.getElementById("searchInput")?.focus(),80);}catch(e){}
  return false;
}
window.gdOpenChangeCourse=gdOpenChangeCourse;
function gdStoreCoursePickerSelection(payload){
  try{currentCourse=payload;}catch(e){}
  try{window.currentCourse=payload;}catch(e){}
  try{window.gdActiveCourse=payload;}catch(e){}
  try{window.gdActiveCourseDisplayName=payload.name||"";}catch(e){}
  try{window.gdManualGpsActive=payload.name==="Manual GPS";}catch(e){}
  try{document.body.dataset.gdActiveCourseName=payload.name||"";}catch(e){}
  try{
    if(payload.name==="Manual GPS"){
      const badge=document.getElementById("gdV62GpsBadge");
      badge?.querySelector(".courseTop")?.remove();
      if(badge)delete badge.dataset.gdBadgeSig;
    }
  }catch(e){}
  try{
	    if(payload.name&&payload.name!=="Manual GPS"){
	      window.gdAssumedCourseName=payload.name;
	      sessionStorage.setItem("gd_assumed_course_name",payload.name);
	      sessionStorage.setItem("gd_active_course_session_key",gdStoredCourseSessionKey(payload));
	    }
	  }catch(e){}
	}
function gdEnsureGpsCourseSurface(){
  try{window.GDShell?.enterGps?.({source:"core-ensure-gps-course-surface",replace:true,fromCoursePicker:true});}catch(e){}
  try{document.body.classList.remove("gdProfileOpen","gdStatsOpen","gdBubbleStudioOpen");document.body.classList.add("gps-open","manual-gps-active","gdModeTwoTap");}catch(e){}
	  try{window.gdApplyGpsMapVisibilityOwner?.("ensure-gps-course-surface-before-map");}catch(e){}
	  const mapEl=document.getElementById("map");
		  if(mapEl){
		    mapEl.classList.remove("hidden");
		    mapEl.style.display="block";
		    const liveAllowed=!!((window.gdGpsLiveMapExplicitlyAllowed&&window.gdGpsLiveMapExplicitlyAllowed("ensure-gps-course-surface"))||document.body.classList.contains("gdGpsLiveMapAllowed"));
		    mapEl.style.visibility=liveAllowed?"visible":"hidden";
		    mapEl.style.opacity=liveAllowed?"1":"0";
		    mapEl.style.pointerEvents=liveAllowed?"auto":"none";
		  }
		  try{window.gdApplyGpsMapVisibilityOwner?.("ensure-gps-course-surface");}catch(e){}
		}
function gdCoursePayloadIsManual(payload){
  return /^manual gps$/i.test(String(payload?.name||payload?.courseName||"").trim());
}
const GD_COURSE_PICKER_PIN_STORE_KEY="gd_course_picker_course_pins_v1";
function gdCoursePickerReadPinStore(){
  try{
    const store=JSON.parse(localStorage.getItem(GD_COURSE_PICKER_PIN_STORE_KEY)||"{}");
    return store&&typeof store==="object"?store:{};
  }catch(e){return {}}
}
function gdCoursePickerWritePinStore(store){
  try{localStorage.setItem(GD_COURSE_PICKER_PIN_STORE_KEY,JSON.stringify(store||{}));}catch(e){}
}
function gdCoursePickerPinKey(payload){
  const key=gdStoredCourseSessionKey(payload);
  return key&&key!=="manual-gps"?key:"";
}
function gdCoursePickerStoredPin(payload){
  const owner=window.GDCourseLocation;
  if(owner&&typeof owner.get==="function"){
    const resolved=owner.get(payload);
    if(resolved&&resolved.centre)return Object.assign({},resolved,resolved.centre,{source:resolved.source||"course-location-owner"});
  }
  const key=gdCoursePickerPinKey(payload);
  if(!key)return null;
  const saved=gdCoursePickerReadPinStore()[key];
  const point=gdCoursePickerFinitePoint(saved);
  return point?Object.assign({},saved,point):null;
}
function gdCoursePickerRememberPin(payload,point){
  const owner=window.GDCourseLocation;
  if(owner&&typeof owner.confirm==="function")return !!owner.confirm(payload,point,{source:"course-picker-pin"});
  const key=gdCoursePickerPinKey(payload);
  const pin=gdCoursePickerFinitePoint(point);
  if(!key||!pin)return false;
  const store=gdCoursePickerReadPinStore();
  store[key]={
    lat:pin.lat,
    lng:pin.lng,
    courseName:payload?.name||payload?.courseName||"",
    pinnedAt:new Date().toISOString(),
    source:"course-picker-pin"
  };
  gdCoursePickerWritePinStore(store);
  return true;
}
function gdCoursePickerApplyStoredPin(payload){
  const owner=window.GDCourseLocation;
  if(owner&&typeof owner.attachToCourse==="function")return owner.attachToCourse(payload,{requireConfirmed:true});
  if(gdCoursePayloadIsManual(payload))return payload;
  const pin=gdCoursePickerStoredPin(payload);
  if(!pin)return payload;
  return gdNormalizeCoursePickerPayload(Object.assign({},payload,{
    lat:pin.lat,
    lng:pin.lng,
    courseLat:pin.lat,
    courseLng:pin.lng,
    finderLat:pin.lat,
    finderLng:pin.lng,
    coursePinned:true,
    pinnedByUser:true,
    pinSource:pin.source||"stored-course-pin",
    gdTrustedCoursePin:true
  }));
}
function gdCoursePickerMapCenterPoint(){
  try{
    if(typeof map==="undefined"||!map||typeof map.getCenter!=="function")return null;
    const center=gdCoursePickerFinitePoint(map.getCenter());
    return center&&!gdCoursePickerNeutralPoint(center)?center:null;
  }catch(e){return null}
}
function gdCoursePickerPinPointForPayload(payload){
  return gdCoursePickerMapCenterPoint()||gdCoursePickerFinitePoint(payload)||gdCoursePickerDefaultPoint();
}
function gdCoursePickerNeedsCoursePin(payload){
  const mark=reason=>{try{document.body.dataset.gdCoursePinDecision=reason;}catch(e){}};
  if(gdCoursePayloadIsManual(payload)){mark("manual-course");return false;}
		  if(payload?.gdDatabaseMapAvailable===true){mark("database-map");return false;}
  const owner=window.GDCourseLocation;
  const resolved=owner&&typeof owner.get==="function"?owner.get(payload):null;
  if(resolved&&resolved.centre&&resolved.confirmed){mark("confirmed-course-location");return false;}
		  if(window.__gdCoursePickerBypassPinOnce){
		    window.__gdCoursePickerBypassPinOnce=false;
		    mark("bypass-once");
	    return false;
	  }
	  mark("needs-pin");
	  return true;
	}
function gdCoursePickerUsesPinSeed(payload){
  return !!(payload&&!gdCoursePayloadIsManual(payload)&&payload.courseLocationConfirmed===true&&gdCoursePickerFinitePoint(payload));
}
async function gdCoursePickerDatabaseMapAvailable(payload){
  if(!payload||gdCoursePayloadIsManual(payload))return {available:false,attempted:false,reason:"manual-course"};
  try{
    document.body.dataset.gdCoursePinDecision="checking-database-map";
    document.body.dataset.gdCourseNeedsPin="checking_database_map";
  }catch(e){}
	  try{
	    const library=window.GolfDaddyCourseLibrary||window.ClarityCaddieCourseLibrary||{};
	    if(typeof library.publishedCourseMapAvailability==="function"){
      const result=await library.publishedCourseMapAvailability(payload,{hole:1,wholeCourse:true,source:"course-picker-db-map-check"});
      if(result&&result.available)return Object.assign({source:"published-course-map"},result);
      return Object.assign({available:false,source:"published-course-map"},result||{});
    }
  }catch(error){
    return {available:false,attempted:true,failed:true,source:"published-course-map",reason:error&&error.message||String(error)};
  }
  return {available:false,attempted:false,reason:"database-map-check-unavailable"};
}
function gdCoursePickerCheckDatabaseThenOpen(payload){
  payload=gdNormalizeCoursePickerPayload(payload);
  const token=`${Date.now()}-${Math.random()}`;
  window.__gdCoursePickerDbCheckToken=token;
  try{
    window.__gdLiveCoursePickerSelection=payload;
    window.__gdLiveCoursePickerSelectionAt=Date.now();
    document.body.dataset.gdCourseNeedsPin="checking_database_map";
    document.body.dataset.gdCourseNeedsPinCourse=payload?.courseId||payload?.canonicalKey||payload?.name||"";
    document.body.dataset.gdCoursePinDecision="checking-database-map";
  }catch(e){}
  gdCoursePickerDatabaseMapAvailable(payload).then(result=>{
    if(window.__gdCoursePickerDbCheckToken!==token)return false;
    const hasDatabaseMap=!!(result&&result.available);
    try{
      document.body.dataset.gdCourseDatabaseMapAvailable=hasDatabaseMap?"yes":"no";
      document.body.dataset.gdCourseDatabaseMapSource=result&&result.source||result&&result.reason||"";
    }catch(e){}
    const next=gdNormalizeCoursePickerPayload(Object.assign({},payload,{
      gdDatabaseMapChecked:true,
      gdDatabaseMapAvailable:hasDatabaseMap,
      gdDatabaseMapSource:result&&result.source||""
    }));
    return gdOpenCoursePickerCourse(next);
  }).catch(error=>{
    if(window.__gdCoursePickerDbCheckToken!==token)return false;
    try{
      document.body.dataset.gdCourseDatabaseMapAvailable="error";
      document.body.dataset.gdCourseDatabaseMapSource=error&&error.message||"database-map-check-error";
    }catch(e){}
    return gdOpenCoursePickerCourse(Object.assign({},payload,{gdDatabaseMapChecked:true,gdDatabaseMapAvailable:false}));
  });
  return false;
}
function gdSetCoursePickerPinMode(on){
  const active=!!on;
  try{
    const screen=document.getElementById("courseScreen");
    if(screen)screen.classList.toggle("gdCoursePinMode",active);
    document.body.classList.toggle("gdCoursePinPromptActive",active);
    window.__gdCoursePickerPinPromptActive=active;
  }catch(e){}
}
function gdEnsureCoursePinScreen(){
  let panel=document.getElementById("gdCoursePinScreen");
  if(panel)return panel;
  panel=document.createElement("div");
  panel.id="gdCoursePinScreen";
  panel.className="gdCoursePinScreen hidden";
  panel.innerHTML='<div class="gdCoursePinCrosshair" aria-hidden="true"></div><div class="gdCoursePinPanel" role="dialog" aria-live="polite" aria-labelledby="gdCoursePinTitle"><div class="gdCoursePinKicker">GPS not available</div><div class="gdCoursePinTitle" id="gdCoursePinTitle">Pin course</div><div class="gdCoursePinText" id="gdCoursePinText">Move the map over the course, then pin it.</div><div class="gdCoursePinActions"><button type="button" class="gdCoursePinSecondary" onclick="gdCancelCoursePin(event)">Back</button><button type="button" class="gdCoursePinPrimary" onclick="gdConfirmCoursePin(event)">Pin Course</button></div></div>';
  (document.getElementById("courseScreen")||document.body).appendChild(panel);
  return panel;
}
function gdCenterCoursePinMap(payload){
  const point=gdCoursePickerFinitePoint(payload)||gdCoursePickerMapCenterPoint()||gdCoursePickerDefaultPoint();
  if(!point)return false;
  try{
    if(typeof map==="undefined"||!map||typeof map.setView!=="function")return false;
    const currentZoom=typeof map.getZoom==="function"?Number(map.getZoom()):NaN;
    const zoom=Number.isFinite(currentZoom)&&currentZoom>=16?currentZoom:16;
    map.setView([point.lat,point.lng],zoom,{animate:false});
    if(typeof map.invalidateSize==="function"){
      setTimeout(()=>map.invalidateSize(false),40);
      setTimeout(()=>map.invalidateSize(false),240);
    }
    return true;
  }catch(e){return false}
}
function gdHideCoursePinScreen(){
  try{document.getElementById("gdCoursePinScreen")?.classList.add("hidden");}catch(e){}
  gdSetCoursePickerPinMode(false);
}
function gdShowCoursePinScreen(payload){
  payload=gdNormalizeCoursePickerPayload(payload);
  try{
    window.__gdPendingCoursePinPayload=payload;
    window.__gdLiveCoursePickerSelection=payload;
    window.__gdLiveCoursePickerSelectionAt=Date.now();
    window.__gdCoursePickerFirstHoleOpenToken=null;
    window.__gdCoursePickerChangingAt=Date.now();
  }catch(e){}
  try{
    document.body.dataset.gdCourseNeedsPin="choose-course-pin";
    document.body.dataset.gdCourseNeedsPinCourse=payload?.courseId||payload?.canonicalKey||payload?.name||"";
    document.body.classList.remove("gdMappedStartPromptActive","gdCapturedHoleFrameCameraOn","gdHoleImageCameraOn","gdGpsPresentationReady","gdHeadToTeeFrameActive","gdLockStateFrameActive","gd-frame-hard-locked");
  }catch(e){}
  try{window.gdClearHoleImageRuntime?.("course-picker-pin-prompt");}catch(e){}
  const screen=document.getElementById("courseScreen");
  if(screen){
    screen.classList.remove("hidden");
    screen.style.display="flex";
    screen.style.visibility="";
    screen.style.opacity="";
    screen.style.pointerEvents="auto";
  }
  const panel=gdEnsureCoursePinScreen();
  const title=panel.querySelector("#gdCoursePinTitle");
  const text=panel.querySelector("#gdCoursePinText");
  if(title)title.textContent=`Pin ${payload.name||"course"}`;
  if(text)text.textContent="Move the map over the course, then pin it.";
  gdSetCoursePickerPinMode(true);
  panel.classList.remove("hidden");
  gdCenterCoursePinMap(payload);
  try{
    const owner=window.GDCourseLocation;
    const proposal=gdCoursePickerMapCenterPoint()||gdCoursePickerFinitePoint(payload)||gdCoursePickerDefaultPoint();
    if(owner&&typeof owner.propose==="function"&&proposal)owner.propose(payload,proposal,{source:"course-picker-pin-proposal",confidence:.35});
  }catch(e){}
  try{window.gdApplyGpsMapVisibilityOwner?.("course-picker-pin-prompt");}catch(e){}
  try{if(typeof toast==="function")toast("Pin the course location");}catch(e){}
  return false;
}
function gdCancelCoursePin(event){
  if(event){
    event.preventDefault?.();
    event.stopPropagation?.();
    event.stopImmediatePropagation?.();
  }
  try{window.__gdPendingCoursePinPayload=null;}catch(e){}
  try{document.body.dataset.gdCourseNeedsPin="pending";}catch(e){}
  gdHideCoursePinScreen();
  try{setTimeout(()=>document.getElementById("searchInput")?.focus(),60);}catch(e){}
  return false;
}
function gdConfirmCoursePin(event){
  if(event){
    event.preventDefault?.();
    event.stopPropagation?.();
    event.stopImmediatePropagation?.();
  }
  const payload=gdNormalizeCoursePickerPayload(window.__gdPendingCoursePinPayload||window.__gdLiveCoursePickerSelection||gdCurrentAssumedCoursePayload());
  const point=gdCoursePickerPinPointForPayload(payload);
  if(!point){
    try{if(typeof toast==="function")toast("Move the map over the course first");}catch(e){}
    return false;
  }
  const owner=window.GDCourseLocation;
  const resolved=owner&&typeof owner.confirm==="function"?owner.confirm(payload,point,{source:"course-picker-pin"}):null;
  if(!resolved)gdCoursePickerRememberPin(payload,point);
  const savedPoint=resolved&&resolved.centre||point;
  const pinned=owner&&typeof owner.attachToCourse==="function"
    ?owner.attachToCourse(payload,{requireConfirmed:true})
    :gdNormalizeCoursePickerPayload(Object.assign({},payload,{
    lat:savedPoint.lat,
    lng:savedPoint.lng,
    courseLat:savedPoint.lat,
    courseLng:savedPoint.lng,
    finderLat:savedPoint.lat,
    finderLng:savedPoint.lng,
    coursePinned:true,
    pinnedByUser:true,
    pinSource:"course-picker-pin",
    gdTrustedCoursePin:true
  }));
  gdHideCoursePinScreen();
  try{window.__gdPendingCoursePinPayload=null;window.__gdCoursePickerBypassPinOnce=true;}catch(e){}
  return gdOpenCoursePickerCourse(pinned);
}
window.gdCoursePickerNeedsCoursePin=gdCoursePickerNeedsCoursePin;
window.gdShowCoursePinScreen=gdShowCoursePinScreen;
window.gdHideCoursePinScreen=gdHideCoursePinScreen;
window.gdConfirmCoursePin=gdConfirmCoursePin;
