  document.body.classList.remove("gdMappedStartPromptActive","gdManualStartPlacementActive","gdLockStateFrameActive","gd-frame-hard-locked","gdHeadToTeeFrameActive");
  try{document.getElementById("shotTile")?.classList.remove("visible")}catch(e){}
