    if(typeof window.gdFocusMappedHoleOrSavedGreen==="function"){
      window.gdFocusMappedHoleOrSavedGreen(payload?.hole||gdMappedStartHoleNumber(),{course:payload?.course||null,quiet:true,frame:true,allowAnyStart:true,skipAutoLock:true,stablePreLock:true});
    }
