function gdHeadToTeeShotFrame(){
  if(!map||!start||!target)return false;
  try{
    const displayTarget=typeof gdShotDisplayTarget==="function"?(gdShotDisplayTarget()||target):target;
    const green=greenCentre||displayTarget||target;
    if(!displayTarget||!green)return false;
    const axis=typeof gdShotUpAxis==="function"?gdShotUpAxis():null;
    const brg=axis&&Number.isFinite(axis.bearingRad)?axis.bearingRad:bearing(start,green);
    if(!Number.isFinite(brg))return false;
    const shotM=Math.max(1,map.distance(start,displayTarget));
    const mid=project(start,brg,shotM*.54);
    const lateral=Math.max(70,Math.min(135,shotM*.32));
    const back=project(start,brg+Math.PI,Math.max(36,Math.min(78,shotM*.16)));
    const beyond=project(green,brg,Math.max(48,Math.min(98,shotM*.18)));
    const points=[start,displayTarget,target,green,mid,back,beyond,
      projectOffset(mid,brg,0,-lateral),
      projectOffset(mid,brg,0,lateral)
    ].filter(Boolean);
    if(Array.isArray(greenPolygon))greenPolygon.forEach(point=>{if(point)points.push(point);});
    if(points.length<2)return false;
    map.fitBounds(L.latLngBounds(points),{
      paddingTopLeft:[42,126],
      paddingBottomRight:[54,124],
      animate:true,
      duration:.36,
      maxZoom:17
    });
    setTimeout(()=>{
      try{if(map&&map.getZoom&&map.getZoom()>17)map.setZoom(17,{animate:true});}catch(e){}
    },80);
    return true;
  }catch(e){
    return false;
  }
}
function gdApplyHeadToTeeBagTarget(hole){
  if(!start||!greenCentre||!target||!map)return false;
  const maxCarry=gdMaxPlayableCarryM();
  if(!(maxCarry>0))return false;
  const greenDistance=map.distance(start,greenCentre);
  if(!Number.isFinite(greenDistance)||greenDistance<=maxCarry+3)return false;
  let next=null;
  try{
    if(typeof window.gdMappedFairwayLayupTarget==="function"){
      next=window.gdMappedFairwayLayupTarget(start,greenCentre,maxCarry,{hole:hole||gdMappedStartHoleNumber()});
    }
  }catch(e){}
  if(!next){
    try{next=project(start,bearing(start,greenCentre),maxCarry);}catch(e){}
  }
  if(!next)return false;
  gdSetTargetFromDisplayedLanding(next);
  targetWasMoved=false;
  if(targetMarker)targetMarker.setLatLng(gdShotDisplayTarget()||target);
  try{setState("Layup · move shot target")}catch(e){}
  return true;
}
function gdFinalizeHeadToTeeShot(hole){
  if(!start||!target)return false;
  const runHeadToTeeFrame=()=>{
    try{if(typeof window.gdHeadToTeeShotFrame==="function")return window.gdHeadToTeeShotFrame()}catch(e){}
    try{if(typeof gdHeadToTeeShotFrame==="function")return gdHeadToTeeShotFrame()}catch(e){}
    return false;
  };
  try{mode="aim"}catch(e){}
  try{document.getElementById("shotTile")?.classList.add("visible")}catch(e){}
  try{gdApplyHeadToTeeBagTarget(hole)}catch(e){}
  runHeadToTeeFrame();
  try{if(!lockedFrame&&typeof lockFrame==="function")lockFrame(false);else if(!lockedFrame&&typeof setBubbleOnlyLock==="function")setBubbleOnlyLock(true);}catch(e){}
  try{if(typeof renderShot==="function")renderShot();}catch(e){}
  try{if(typeof updatePinLine==="function")updatePinLine();}catch(e){}
  try{if(!gdIsLayupTarget(greenCentre,target))setState(`Hole ${hole||""}`.trim()||"Hole")}catch(e){}
  try{hideHint()}catch(e){}
  try{const hint=document.getElementById("hint");if(hint){hint.classList.remove("visible","gdMappedStartPill");hint.textContent="";}}catch(e){}
  [180,520,980].forEach(delay=>setTimeout(runHeadToTeeFrame,delay));
  toast("Tee start set");
  return true;
}
