function gdRemoveOrphanTargetMarkerDom(){
  const activeTargetEl=target&&targetMarker&&targetMarker.getElement?targetMarker.getElement():null;
  document.querySelectorAll(".targetDot,.gdBubbleDragHit").forEach(el=>{
    try{
      const markerEl=el.closest(".leaflet-marker-icon")||el;
      if(activeTargetEl&&(markerEl===activeTargetEl||activeTargetEl.contains(el)))return;
      markerEl.remove();
    }catch(e){}
  });
  try{
    if(!map||!map._layers)return;
    Object.values(map._layers).forEach(layer=>{
      if(!layer||layer===targetMarker&&target)return;
      const el=layer.getElement&&layer.getElement();
      const html=String(layer.options&&layer.options.icon&&layer.options.icon.options&&layer.options.icon.options.html||"");
      const isTargetLayer=!!(
        (el&&el.querySelector&&el.querySelector(".targetDot,.gdBubbleDragHit"))||
        html.includes("targetDot")||
        html.includes("gdBubbleDragHit")
      );
      if(!isTargetLayer)return;
      try{map.removeLayer(layer)}catch(e){}
      if(layer===targetMarker)targetMarker=null;
    });
  }catch(e){}
}
