let gdSmoothBubbleDragState=null;
const GD_BUBBLE_LONG_PRESS_ZOOM_MS=460;
const GD_BUBBLE_LONG_PRESS_CANCEL_PX=9;
function gdActiveShotObjectBounds(payloadInput=null,centerInput=null){
  if(!map||!target||typeof L==="undefined")return null;
  const points=[];
  let payload=payloadInput;
  const display=(()=>{try{return typeof gdShotDisplayTarget==="function"&&(gdShotDisplayTarget()||null)}catch(e){return null}})()||target;
  if(!payload){
    try{
      const d=start&&display&&map.distance?map.distance(start,display):0;
      payload=typeof getGpsBubblePayload==="function"?getGpsBubblePayload(d):null;
    }catch(e){payload=null}
  }
  const center=centerInput||(()=>{try{return gdBubbleRenderCenter(payload)}catch(e){return null}})()||display||target||greenCentre;
  try{
    if(center&&payload&&typeof buildBubbleShape==="function")points.push(...buildBubbleShape(center,payload,1).filter(Boolean));
  }catch(e){}
  [center,display,target].forEach(p=>{if(p)points.push(p);});
  try{
    if(center&&greenCentre&&map.distance(center,greenCentre)<95)points.push(greenCentre);
  }catch(e){}
  if(points.length>=2){
    try{return L.latLngBounds(points.filter(Boolean));}catch(e){}
  }
  if(center){
    try{
      return L.latLngBounds([center,project(center,0,12),project(center,Math.PI/2,12)]);
    }catch(e){}
  }
  return null;
}
window.gdGetActiveShotObjectBounds=gdActiveShotObjectBounds;
