function gdParseCssOriginValue(value,size){
  const raw=String(value||"").trim();
  if(raw.endsWith("%"))return (parseFloat(raw)||0)/100*size;
  const n=parseFloat(raw);
  return Number.isFinite(n)?n:size/2;
}
function gdGetMapTransformPoint(clientX,clientY){
  const el=map.getContainer();
  const style=window.getComputedStyle?getComputedStyle(el):null;
  const rect=el.getBoundingClientRect();
  const w=el.offsetWidth||rect.width;
  const h=el.offsetHeight||rect.height;
  const originParts=String(style?.transformOrigin||"50% 50%").split(/\s+/);
  const origin=L.point(
    gdParseCssOriginValue(originParts[0]||"50%",w),
    gdParseCssOriginValue(originParts[1]||"50%",h)
  );
  const originScreen=L.point(
    rect.left+(origin.x/Math.max(w,1))*rect.width,
    rect.top+(origin.y/Math.max(h,1))*rect.height
  );
  const dx=clientX-originScreen.x;
  const dy=clientY-originScreen.y;
  const angle=((Number(currentMapRotation)||0)*Math.PI)/180;
  const cos=Math.cos(angle);
  const sin=Math.sin(angle);
  return L.point(origin.x+(dx*cos+dy*sin),origin.y+(-dx*sin+dy*cos));
}
function gdClientToMapContainerPoint(clientX,clientY){
  try{
    return gdGetMapTransformPoint(clientX,clientY);
  }catch(e){
    return null;
  }
}
	function gdLiveLatLngFromClient(clientX,clientY){
	  const p=gdClientToMapContainerPoint(clientX,clientY);
	  if(!p)return null;
	  try{return map.containerPointToLatLng(p);}catch(e){return null;}
	}
	try{window.gdLiveLatLngFromClient=gdLiveLatLngFromClient;}catch(e){}
	function gdCapturedLatLngFromClientStrict(clientX,clientY,reason="client-event"){
	  const capturedActive=!!(document.body&&document.body.classList.contains("gdCapturedHoleFrameCameraOn"));
	  if(!capturedActive)return null;
	  try{
	    if(typeof window.gdEnsureCurrentCapturedSurfaceManifest==="function"){
	      const manifest=window.gdEnsureCurrentCapturedSurfaceManifest(reason);
	      if(!manifest){
	        if(document.body&&document.body.dataset)document.body.dataset.gdCapturedTapResolver="blocked-no-current-scan";
	        return null;
	      }
	    }else if(typeof window.gdCapturedSurfaceManifestMatchesActive==="function"&&!window.gdCapturedSurfaceManifestMatchesActive()){
	      if(document.body&&document.body.dataset)document.body.dataset.gdCapturedTapResolver="blocked-stale-scan";
	      return null;
	    }
	    if(typeof window.gdCapturedClientToLatLng!=="function"){
	      if(document.body&&document.body.dataset)document.body.dataset.gdCapturedTapResolver="blocked-no-converter";
	      return null;
	    }
	    const captured=window.gdCapturedClientToLatLng(clientX,clientY);
	    if(typeof window.gdCapturedSurfaceAccuracyProbe==="function")window.__gdLastClientSurfaceProbe=window.gdCapturedSurfaceAccuracyProbe(clientX,clientY);
	    if(document.body&&document.body.dataset)document.body.dataset.gdCapturedTapResolver=captured?"captured":"blocked-null-captured";
	    return captured||null;
	  }catch(e){
	    if(document.body&&document.body.dataset)document.body.dataset.gdCapturedTapResolver="blocked-error";
	    return null;
	  }
	}
	try{window.gdCapturedLatLngFromClientStrict=gdCapturedLatLngFromClientStrict;}catch(e){}
	function gdLatLngFromClientEvent(ev){
	  if(!ev)return null;
	  if(document.body&&document.body.classList.contains("gdCapturedHoleFrameCameraOn"))return gdCapturedLatLngFromClientStrict(ev.clientX,ev.clientY,"client-event");
	  const live=gdLiveLatLngFromClient(ev.clientX,ev.clientY);
	  return live;
	}
function gdLatLngFromBubblePointer(ev,offset){
  const p=gdClientToMapContainerPoint(ev.clientX,ev.clientY);
  if(!p)return null;
  const adjusted=L.point(p.x-(offset?.x||0),p.y-(offset?.y||0));
  try{return map.containerPointToLatLng(adjusted);}catch(e){return null;}
}
function gdQueueSmoothBubbleRender(marker,ll){
  if(!gdSmoothBubbleDragState)return;
  gdSmoothBubbleDragState.pending=ll;
  if(gdSmoothBubbleDragState.raf)return;
  gdSmoothBubbleDragState.raf=requestAnimationFrame(()=>{
    const state=gdSmoothBubbleDragState;
    if(!state)return;
    state.raf=null;
    const next=state.pending;
    if(!next)return;
    gdSetTargetFromDisplayedLanding(next);
    targetWasMoved=true;
    gdMarkCurrentPlanDirty();
    marker.setLatLng(gdShotDisplayTarget()||target);
    renderShot();
  });
}
function gdInstallSmoothBubbleDrag(marker){
  if(!marker||marker.__gdSmoothBubbleDragInstalled)return;
  marker.__gdSmoothBubbleDragInstalled=true;
  const install=()=>{
    const el=marker.getElement&&marker.getElement();
    if(!el||el.__gdSmoothBubbleDragInstalled)return;
    el.__gdSmoothBubbleDragInstalled=true;
    el.style.touchAction="none";
    el.style.cursor="grab";
    el.addEventListener("pointerdown",ev=>{
      if(ev.button!=null&&ev.button!==0)return;
      if(mode==="start"||mode==="green"||placingPin){
        const ll=gdLatLngFromClientEvent(ev);
        if(gdCompleteTwoTapPlacement(ll)){
          ev.preventDefault();
          ev.stopPropagation();
          return;
        }
      }
      ev.preventDefault();
      ev.stopPropagation();
      targetDragging=true;
      const hadMapDragging=!!(map.dragging&&map.dragging.enabled&&map.dragging.enabled());
      if(hadMapDragging)map.dragging.disable();
      if(target) undoStack.push({type:"target",value:L.latLng(target.lat,target.lng)});
      const pointerPoint=gdClientToMapContainerPoint(ev.clientX,ev.clientY);
      const markerPoint=target?map.latLngToContainerPoint(target):map.latLngToContainerPoint(marker.getLatLng());
      const longPressTimer=setTimeout(()=>gdBeginBubbleLongPressZoom(),GD_BUBBLE_LONG_PRESS_ZOOM_MS);
      gdSmoothBubbleDragState={
        pointerId:ev.pointerId,
        startClientX:ev.clientX,
        startClientY:ev.clientY,
        offset:pointerPoint?L.point(pointerPoint.x-markerPoint.x,pointerPoint.y-markerPoint.y):L.point(0,0),
        pending:null,
        raf:null,
        hadMapDragging,
        movedBeforeLongPress:false,
        longPressTimer,
        longPressZoomActive:false
      };
      try{el.setPointerCapture(ev.pointerId);}catch(e){}
      el.style.cursor="grabbing";
      const move=moveEv=>{
        if(!gdSmoothBubbleDragState||moveEv.pointerId!==gdSmoothBubbleDragState.pointerId)return;
        moveEv.preventDefault();
        moveEv.stopPropagation();
        const movedPx=Math.hypot(
          moveEv.clientX-gdSmoothBubbleDragState.startClientX,
          moveEv.clientY-gdSmoothBubbleDragState.startClientY
        );
        if(!gdSmoothBubbleDragState.longPressZoomActive&&movedPx>GD_BUBBLE_LONG_PRESS_CANCEL_PX){
          gdSmoothBubbleDragState.movedBeforeLongPress=true;
          gdClearBubbleLongPressTimer(gdSmoothBubbleDragState);
        }
        const ll=gdLatLngFromBubblePointer(moveEv,gdSmoothBubbleDragState.offset);
        if(ll)gdQueueSmoothBubbleRender(marker,ll);
      };
      const end=endEv=>{
        if(gdSmoothBubbleDragState&&endEv.pointerId!==gdSmoothBubbleDragState.pointerId)return;
        endEv.preventDefault();
        endEv.stopPropagation();
        document.removeEventListener("pointermove",move);
        document.removeEventListener("pointerup",end);
        document.removeEventListener("pointercancel",end);
        const finishedFromLongPressZoom=!!(gdSmoothBubbleDragState&&gdSmoothBubbleDragState.longPressZoomActive);
        gdClearBubbleLongPressTimer(gdSmoothBubbleDragState);
        if(gdSmoothBubbleDragState&&gdSmoothBubbleDragState.raf)cancelAnimationFrame(gdSmoothBubbleDragState.raf);
        const ll=gdLatLngFromBubblePointer(endEv,gdSmoothBubbleDragState?.offset);
        if(ll){
          gdSetTargetFromDisplayedLanding(ll);
          targetWasMoved=true;
          gdMarkCurrentPlanDirty();
          marker.setLatLng(gdShotDisplayTarget()||target);
        }
        gdSmoothBubbleDragState=null;
        targetDragging=false;
        if(hadMapDragging)map.dragging.enable();
        el.style.cursor="grab";
        renderShot();
        if(lockedFrame)setBubbleOnlyLock(true);
        gdFinishBubbleLongPressZoom(finishedFromLongPressZoom);
        try{el.releasePointerCapture(endEv.pointerId);}catch(e){}
      };
      document.addEventListener("pointermove",move,{passive:false});
      document.addEventListener("pointerup",end,{passive:false});
      document.addEventListener("pointercancel",end,{passive:false});
    },{passive:false});
  };
  marker.__gdRefreshSmoothBubbleDrag=install;
  marker.on("add",()=>requestAnimationFrame(install));
  requestAnimationFrame(install);
}
function gdBubbleDragHitIcon(gdb){
  const display=gdShotDisplayTarget()||target;
  if(!display)return targetIcon;
  let size=64;
  try{
    const payload=gdBubblePayloadForRender(gdb);
    const metres=Math.max(
      gdFiniteNumber(payload.radius,0),
      gdFiniteNumber(payload.lateralRadiusM,0),
      gdFiniteNumber(payload.depthRadiusM,0),
      Math.abs(gdFiniteNumber(payload.aimOffsetM,0))
    )+10;
    const p0=map.latLngToContainerPoint(display);
    const p1=map.latLngToContainerPoint(project(display,Math.PI/2,metres));
    size=Math.max(46,Math.min(260,Math.ceil(p0.distanceTo(p1)*2.18)));
  }catch(e){}
  return L.divIcon({
    className:"gdBubbleDragHitIcon",
    html:`<div class="targetDot gdBubbleDragHit" style="width:${size}px;height:${size}px;opacity:0;border:0;background:transparent;box-shadow:none;pointer-events:auto"></div>`,
    iconSize:[size,size],
    iconAnchor:[size/2,size/2]
  });
}
function gdSyncBubbleDragHitArea(gdb){
  if(!targetMarker)return;
  const display=gdShotDisplayTarget()||target;
  if(display)targetMarker.setLatLng(display);
  const icon=gdBubbleDragHitIcon(gdb);
  const size=icon.options&&icon.options.iconSize&&icon.options.iconSize[0];
  if(!targetMarker.__gdBubbleHitSize||Math.abs(targetMarker.__gdBubbleHitSize-size)>3){
    targetMarker.__gdBubbleHitSize=size;
    targetMarker.setIcon(icon);
    requestAnimationFrame(()=>targetMarker.__gdRefreshSmoothBubbleDrag&&targetMarker.__gdRefreshSmoothBubbleDrag());
  }
}
function createTargetMarker(ll){
  targetMarker=L.marker(gdShotDisplayTarget()||ll,{icon:targetIcon,draggable:false,autoPan:false}).addTo(map);
  gdInstallSmoothBubbleDrag(targetMarker);
}
/* ---------------- Core Shot / Bubble Dispersion Logic v24 ----------------
   Clean-input integration from golf_daddy_core_shot_dispersion_logic_handoff.
   GPS is account-first. The ghost bag is only a no-account-bag fallback. */
const GD_DEFAULT_CLUB_CARRY_M={Driver:230,"3W":205,"4H":180,"4i":178,"5i":170,"6i":160,"7i":155,"8i":142,"9i":130,PW:115,GW:98,SW:82,LW:66};
const GD_CLUB_GROUPS={driver:/driver/i,woodHybrid:/3w|wood|hybrid|4h/i,wedge:/pw|gw|sw|lw|wedge/i};
const GD_BAG_FIRMNESS_KEY="gd_bag_total_firmness_v1";
const GD_BAG_FIRMNESS_PRESETS={soft:{label:"Soft",multiplier:.45},medium:{label:"Medium",multiplier:1},hard:{label:"Hard",multiplier:1.65}};
const GD_CLUB_PATTERN_RATIOS={driver:{width:.19,depth:.23,carryWindowPct:5.4,faceWindowDeg:.95,tiltBaseDeg:5},woodHybrid:{width:.17,depth:.215,carryWindowPct:4.9,faceWindowDeg:.85,tiltBaseDeg:4.5},iron:{width:.148,depth:.195,carryWindowPct:4.2,faceWindowDeg:.7,tiltBaseDeg:4},wedge:{width:.12,depth:.16,carryWindowPct:3.4,faceWindowDeg:.55,tiltBaseDeg:2.5}};
function gdBagFirmness(){try{const stored=localStorage.getItem(GD_BAG_FIRMNESS_KEY);if(GD_BAG_FIRMNESS_PRESETS[stored])return stored}catch(e){}return"medium"}
function gdBagFirmnessLabel(preset=gdBagFirmness()){return GD_BAG_FIRMNESS_PRESETS[preset]?.label||"Medium"}
function gdBagTotalLabel(preset=gdBagFirmness()){return `Total (${gdBagFirmnessLabel(preset)})`}
function gdBagFirmnessMultiplier(preset=gdBagFirmness()){return GD_BAG_FIRMNESS_PRESETS[preset]?.multiplier??1}
function gdRolloutBasePct(club="7i"){
  const group=gdGetClubGroup(club);
  const fallback={driver:.11,woodHybrid:.095,iron:.075,wedge:.047}[group]||.075;
  try{
    if(group==="driver")return gdFiniteNumber(dev("clubScaling.driverRolloutPct"),fallback);
    if(group==="woodHybrid")return gdFiniteNumber(dev("clubScaling.ironRolloutPct"),.075)*1.35;
    if(group==="wedge")return gdFiniteNumber(dev("clubScaling.wedgeRolloutPct"),fallback);
    return gdFiniteNumber(dev("clubScaling.ironRolloutPct"),fallback);
  }catch(e){return fallback}
}
function gdBagTotalForCarry(club,carry,preset=gdBagFirmness()){
  const c=Math.max(0,Math.round(Number(carry)||0));
  if(!c)return 0;
  const pct=Math.max(0,gdRolloutBasePct(club)*gdBagFirmnessMultiplier(preset));
  return Math.max(c,Math.round(c*(1+pct)));
}
function gdCarryM(row){return Math.round(Number(row?.baseCarry??row?.carry??row?.distance??row?.meters)||0)}
function gdTotalM(row){
  const carry=gdCarryM(row);
  const saved=Math.round(Number(row?.totalM??row?.total??row?.totalDistance??row?.baseTotal)||0);
  return saved>=carry&&saved>0?saved:gdBagTotalForCarry(row?.club||row?.name,carry);
}
function gdDefaultStandInBag(){return Object.entries(GD_DEFAULT_CLUB_CARRY_M).map(([club,baseCarry])=>({club,baseCarry,totalM:gdBagTotalForCarry(club,baseCarry)}))}
function gdShotActiveProfile(){
  try{
    const api=window.GolfDaddyAccounts||window.ClarityCaddieAccounts;
    const account=api&&typeof api.current==="function"?api.current():null;
    if(account){
      let profile=null;
      try{profile=typeof gdActiveAccountProfile==="function"?gdActiveAccountProfile(account):null;}catch(e){}
      if(!profile&&account.profileId&&typeof gdProfileById==="function")profile=gdProfileById(account.profileId);
      if(profile&&!profile.placeholderProfile)return profile;
    }
  }catch(e){}
  try{
    const p=activePlayerProfile&&activePlayerProfile();
    if(p&&!p.placeholderProfile)return p;
  }catch(e){}
  return null;
}
function gdNormaliseShotBagRows(rows){
  return (Array.isArray(rows)?rows:[]).map(row=>gdNormaliseBagRow(row)).filter(row=>row&&String(row.club||"").trim()&&gdCarryM(row)>0).sort((a,b)=>gdTotalM(b)-gdTotalM(a));
}
function gdAccountShotBagRows(){
  const p=gdShotActiveProfile();
  if(!p||p.placeholderProfile||p.bagSeededDefault||!Array.isArray(p.bag))return [];
  return gdNormaliseShotBagRows(p.bag);
}
function gdGhostShotBagRows(){
  return gdNormaliseShotBagRows(gdDefaultStandInBag()).map(row=>({...row,ghostBag:true}));
}
function gdPlayableShotBagRows(){
  const accountRows=gdAccountShotBagRows();
  return accountRows.length?accountRows:gdGhostShotBagRows();
}
function gdResolveShotBagClub(rows,club="Bag",distance=155){
  const bag=gdNormaliseShotBagRows(rows);
  if(!bag.length)return null;
  const wanted=String(club||"").trim().toLowerCase();
  if(wanted&&wanted!=="bag"){
    const exact=bag.find(row=>String(row.club||"").trim().toLowerCase()===wanted);
    if(exact)return exact;
  }
  const d=Math.max(1,Number(distance)||155);
  return bag.reduce((best,row)=>Math.abs(gdTotalM(row)-d)<Math.abs(gdTotalM(best)-d)?row:best,bag.find(row=>String(row.club).toLowerCase()==="7i")||bag[0]);
}
const PLACEHOLDER_PLAYER_PROFILE={
  source:"placeholder-profile",
  playerId:"placeholder-v24",
  handedness:"right",
  // Clean app input for now: no user-facing face/path controls here.
  // This represents face relative to ACTUAL alignment line, not face-to-path.
  baseCalibration:{club:"7i",baseCarry:155,faceAlignmentOffsetDeg:1.4,faceWindowDeg:.7,faceToPathToleranceDeg:.7,carryWindowPct:4.2,dispersionMultiplier:1,gdbTrust:1},
  // Internal-only fallback used when GPS needs a safe generic bubble without showing bag placeholders.
  standInBag:gdDefaultStandInBag()
};
function gdClamp(value,min,max){return Math.max(min,Math.min(max,Number(value)||0))}
function gdRound(value,decimals=2){const p=Math.pow(10,decimals);return Math.round((Number(value)||0)*p)/p}
function gdHandednessSign(handedness="right"){return handedness==="left"?-1:1}
function gdGetClubGroup(club="7i"){if(GD_CLUB_GROUPS.driver.test(club))return"driver";if(GD_CLUB_GROUPS.woodHybrid.test(club))return"woodHybrid";if(GD_CLUB_GROUPS.wedge.test(club))return"wedge";return"iron"}
function gdDefaultCarryForClub(club="7i"){return GD_DEFAULT_CLUB_CARRY_M[club]??155}
function gdGetClubPatternDefaults(club="7i"){return GD_CLUB_PATTERN_RATIOS[gdGetClubGroup(club)]}
// Single maths board for bubble geometry. EVERY bubble (GPS projection,
// practice, preview, ghost bag) must derive size/tilt through these tunables
// so the control board is always respected. Defaults are identity (=today's
// behaviour).
function gdBubbleGeometryTuning(){
  const get=path=>{try{return typeof dev==="function"?Number(dev(path)):NaN;}catch(e){return NaN;}};
  const num=(value,fallback)=>Number.isFinite(value)?value:fallback;
  return{
    widthScale:gdClamp(num(get("bubbleGeometry.widthScale"),1),.3,2.5),
    depthScale:gdClamp(num(get("bubbleGeometry.depthScale"),1),.3,2.5),
    tiltScale:gdClamp(num(get("bubbleGeometry.tiltScale"),1),0,3),
    tiltMaxDeg:gdClamp(num(get("bubbleGeometry.tiltMaxDeg"),8),1,25),
    gpsMaxLateralPct:gdClamp(num(get("bubbleGeometry.gpsMaxLateralPct"),.13),.03,.5),
    gpsMaxDepthPct:gdClamp(num(get("bubbleGeometry.gpsMaxDepthPct"),.18),.04,.6),
    gpsMaxLateralM:gdClamp(num(get("bubbleGeometry.gpsMaxLateralM"),28),8,120),
    gpsMaxDepthM:gdClamp(num(get("bubbleGeometry.gpsMaxDepthM"),38),10,150),
    gpsPixelCapScale:gdClamp(num(get("bubbleGeometry.gpsPixelCapScale"),1),.3,3)
  };
}
