function gdSmoothBubbleLocalRing(points,passes=2){
  if(!Array.isArray(points)||points.length<8)return points||[];
  let current=points.map(p=>({x:p.x,y:p.y}));
  for(let pass=0;pass<passes;pass++){
    current=current.map((point,index,all)=>{
      const prev=all[(index-1+all.length)%all.length];
      const next=all[(index+1)%all.length];
      return {
        x:point.x*.72+(prev.x+next.x)*.14,
        y:point.y*.72+(prev.y+next.y)*.14
      };
    });
  }
  return current;
}
function buildBubbleShape(center, payloadInput, scale=1){
  const payload=gdBubblePayloadForRender(payloadInput);
  const pts=[];
  const axes=gdBubbleAxes(payload,scale);
  const steps=168;
  for(let i=0;i<steps;i++){
    const rel=(Math.PI*2*i)/steps;
    const rf=bubbleRadiusFactor(rel,payload);
    pts.push({x:Math.cos(rel)*axes.depth*rf,y:Math.sin(rel)*axes.lateral*rf});
  }
  return gdSmoothBubbleLocalRing(pts,2).map(point=>gdBubbleLocalToLatLng(center,payload,point.x,point.y));
}
function localPointToLatLng(center, shotBrg, x, y){
  const ang=shotBrg + Math.atan2(y,x);
  const dist=Math.sqrt(x*x+y*y);
  return project(center, ang, dist);
}
function renderCustomBubble(payloadInput){
  const payload=gdBubblePayloadForRender(payloadInput);
  const center=gdBubbleRenderCenter(payload)||gdShotDisplayTarget()||target;

  const shellOuter=buildBubbleShape(center, payload, dev("bubbleVisuals.outerScale"));
  const shellMid=buildBubbleShape(center, payload, dev("bubbleVisuals.mainScale"));
  const shellInner=buildBubbleShape(center, payload, dev("bubbleVisuals.innerScale"));

  bubbleShadow=null;
  bubbleShade=null;

  if(!targetDragging){
    bubbleShade=L.polygon(shellInner,{
      color:"#000",
      weight:0,
      opacity:0,
      fillColor:"#000",
      fillOpacity:dev("bubbleVisuals.lockedShadeOpacity"),
      interactive:false
    }).addTo(map);
  }

  if(targetDragging){
    bubbleOuter=null;
    bubbleMiss=null;
    bubbleCore=null;
    bubbleTexture=[];
    bubbleMain=L.polygon(shellMid,{
      color:"#fff",
      weight:2.8,
      opacity:Math.max(.78,dev("bubbleVisuals.mainOutlineOpacity")),
      fillColor:"#fff",
      fillOpacity:0,
      interactive:false
    }).addTo(map);
    return;
  }

  bubbleOuter=L.polygon(shellOuter,{
    color:"#fff",
    weight:0.65,
    opacity:.12,
    fillColor:"#fff",
    fillOpacity:.01,
    interactive:false
  }).addTo(map);

  bubbleMain=L.polygon(shellMid,{
    color:"#fff",
    weight:2.6,
    opacity:Math.max(.72,dev("bubbleVisuals.mainOutlineOpacity")),
    fillColor:"#fff",
    fillOpacity: targetDragging ? dev("bubbleVisuals.dragFillOpacity") : dev("bubbleVisuals.mainFillOpacity"),
    interactive:false
  }).addTo(map);

  bubbleMiss=L.polygon(shellInner,{
    color:"#fff",
    weight:0.75,
    opacity: targetDragging ? .09 : .075,
    fillColor:"#fff",
    fillOpacity: targetDragging ? .018 : .01,
    interactive:false
  }).addTo(map);

  bubbleCore=null;
  bubbleTexture=[];

  [0.42,0.58,0.74].forEach((scale, idx)=>{
    const pts=[];
    const steps=68;
    const axes=gdBubbleAxes(payload,scale);
    for(let i=0;i<steps;i++){
      const rel=(Math.PI*2*i)/steps;
      const rf=bubbleRadiusFactor(rel,payload);
      const drift=bubbleTextureFactor(rel,payload,.75 + idx*.15);
      pts.push(gdBubbleLocalToLatLng(center,payload,Math.cos(rel)*axes.depth*rf*drift,Math.sin(rel)*axes.lateral*rf*drift));
    }
    const layer=L.polygon(pts,{
      color:"#fff",
      weight:0.55,
      opacity: idx===1 ? .085 : .07,
      fillOpacity:0,
      interactive:false,
      dashArray: idx===1 ? "2,12" : "1,15"
    }).addTo(map);
    bubbleTexture.push(layer);
  });

  [-0.22, 0.18].forEach((offset, idx)=>{
    const pts=[];
    const axes=gdBubbleAxes(payload,1);
    for(let t=-1.0;t<=1.0;t+=0.12){
      const rel=offset + t*.48;
      const rf=bubbleRadiusFactor(rel,payload);
      const drift=bubbleTextureFactor(rel,payload,.8);
      const local=0.22 + 0.15*Math.cos(t*1.45 + idx*.4);
      pts.push(gdBubbleLocalToLatLng(center,payload,Math.cos(rel)*axes.depth*local*rf*drift,Math.sin(rel)*axes.lateral*local*rf*drift));
    }
    bubbleTexture.push(
      L.polyline(pts,{
        color:"#fff",
        weight:0.8,
        opacity:.07,
        interactive:false,
        dashArray:"1,13"
      }).addTo(map)
    );
  });

  const ridgePts=[];
  const ridgeAxes=gdBubbleAxes(payload,1);
  for(let t=-0.55;t<=0.55;t+=0.1){
    const rel=t*.34;
    const rf=bubbleRadiusFactor(rel,payload);
    const drift=bubbleTextureFactor(rel,payload,.65);
    const local=0.58 + 0.12*Math.cos(t*2);
    ridgePts.push(gdBubbleLocalToLatLng(center,payload,Math.cos(rel)*ridgeAxes.depth*local*rf*drift,Math.sin(rel)*ridgeAxes.lateral*local*rf*drift));
  }
  bubbleTexture.push(
    L.polyline(ridgePts,{
      color:"#fff",
      weight:0.95,
      opacity:.075,
      interactive:false,
      dashArray:"2,11"
    }).addTo(map)
  );
}

/* ---------------- Elevation channel: opportunistic plays-like distance ---------------- */
const GD_ELEVATION_URL="https://api.open-meteo.com/v1/elevation";
const GD_ELEVATION_RESOLUTION_M=90;
const gdElevationPointCache=new Map();
let gdShotElevationState={key:null,result:null,pendingKey:null};
let gdShotElevationTimer=null;
let gdShotElevationSeq=0;

function gdElevationValidPoint(point){
  return !!(point &&
    Number.isFinite(Number(point.lat)) &&
    Number.isFinite(Number(point.lng)) &&
    Number(point.lat)>=-90 &&
    Number(point.lat)<=90 &&
    Number(point.lng)>=-180 &&
    Number(point.lng)<=180);
}

function gdElevationPointKey(point){
  if(!gdElevationValidPoint(point))return null;
  return `${Number(point.lat).toFixed(5)},${Number(point.lng).toFixed(5)}`;
}

function gdElevationShotKey(origin,target){
  const a=gdElevationPointKey(origin), b=gdElevationPointKey(target);
  return (a&&b)?`${a}|${b}`:null;
}

function gdElevationFailedPoint(point,reason,source="unknown"){
  return {
    ok:false,
    lat:Number(point&&point.lat),
    lng:Number(point&&point.lng),
    elevationM:null,
    source,
    confidence:"none",
    reason
  };
}

function gdElevationPlays(deltaM){
  if(deltaM>1)return "uphill";
  if(deltaM<-1)return "downhill";
  return "level";
}

function gdElevationRound(value,decimals=1){
  const p=10**decimals;
  return Math.round(value*p)/p;
}

async function gdFetchOpenMeteoElevations(points){
  if(!points.length)return [];
  if(points.some(point=>!gdElevationValidPoint(point))){
    return points.map(point=>gdElevationFailedPoint(point,"INVALID_LAT_LNG"));
  }
  const latitude=points.map(point=>Number(point.lat).toFixed(6)).join(",");
  const longitude=points.map(point=>Number(point.lng).toFixed(6)).join(",");
  try{
    const response=await fetch(`${GD_ELEVATION_URL}?latitude=${latitude}&longitude=${longitude}`);
    if(!response.ok)return points.map(point=>gdElevationFailedPoint(point,`HTTP_${response.status}`,"open-meteo"));
    const data=await response.json();
    if(!Array.isArray(data.elevation)){
      return points.map(point=>gdElevationFailedPoint(point,"MISSING_ELEVATION_ARRAY","open-meteo"));
    }
    return points.map((point,index)=>{
      const elevationM=Number(data.elevation[index]);
      if(!Number.isFinite(elevationM)){
        return {...gdElevationFailedPoint(point,"ELEVATION_NOT_AVAILABLE","open-meteo"),resolutionM:GD_ELEVATION_RESOLUTION_M};
      }
      return {
        ok:true,
        lat:Number(point.lat),
        lng:Number(point.lng),
        elevationM,
        source:"open-meteo",
        confidence:"medium",
        resolutionM:GD_ELEVATION_RESOLUTION_M
      };
    });
  }catch(error){
    return points.map(point=>gdElevationFailedPoint(point,(error&&error.message)||"NETWORK_ERROR"));
  }
}

async function gdGetShotElevation(origin,target){
  const sampledAt=new Date().toISOString();
  if(!gdElevationValidPoint(origin)||!gdElevationValidPoint(target)){
    return {
      ok:false,
      origin:gdElevationFailedPoint(origin||{},"INVALID_ORIGIN_OR_TARGET"),
      target:gdElevationFailedPoint(target||{},"INVALID_ORIGIN_OR_TARGET"),
      deltaM:null,
      deltaMRounded:null,
      plays:"unknown",
      sourceMatch:false,
      sampledAt,
      reason:"INVALID_ORIGIN_OR_TARGET"
    };
  }
  const originKey=gdElevationPointKey(origin);
  const targetKey=gdElevationPointKey(target);
  let originResult=gdElevationPointCache.get(originKey);
  let targetResult=gdElevationPointCache.get(targetKey);
  const pointsToFetch=[];
  const fetchSlots=[];
  if(!originResult){pointsToFetch.push(origin);fetchSlots.push("origin");}
  if(!targetResult){pointsToFetch.push(target);fetchSlots.push("target");}
  if(pointsToFetch.length){
    const fetched=await gdFetchOpenMeteoElevations(pointsToFetch);
    fetched.forEach((result,index)=>{
      const slot=fetchSlots[index];
      const key=slot==="origin"?originKey:targetKey;
      if(result.ok)gdElevationPointCache.set(key,result);
      if(slot==="origin")originResult=result;
      if(slot==="target")targetResult=result;
    });
  }
  if(!originResult||!targetResult||!originResult.ok||!targetResult.ok){
    return {
      ok:false,
      origin:originResult||gdElevationFailedPoint(origin,"ORIGIN_LOOKUP_FAILED"),
      target:targetResult||gdElevationFailedPoint(target,"TARGET_LOOKUP_FAILED"),
      deltaM:null,
      deltaMRounded:null,
      plays:"unknown",
      sourceMatch:false,
      sampledAt,
      reason:"ONE_OR_BOTH_ELEVATIONS_UNAVAILABLE"
    };
  }
  const deltaM=targetResult.elevationM-originResult.elevationM;
  return {
    ok:true,
    origin:originResult,
    target:targetResult,
    deltaM,
    deltaMRounded:gdElevationRound(deltaM,1),
    plays:gdElevationPlays(deltaM),
    sourceMatch:originResult.source===targetResult.source,
    sampledAt
  };
}

function gdQueueShotElevation(origin,target,key){
  if(gdShotElevationState.pendingKey===key)return;
  clearTimeout(gdShotElevationTimer);
  gdShotElevationTimer=setTimeout(()=>{
    const seq=++gdShotElevationSeq;
    gdShotElevationState.pendingKey=key;
    gdGetShotElevation(origin,target).then(result=>{
      if(seq!==gdShotElevationSeq||gdShotElevationState.key!==key)return;
      gdShotElevationState.result={...result,key};
      gdShotElevationState.pendingKey=null;
      if(typeof renderShot==="function")renderShot();
    }).catch(()=>{
      if(seq!==gdShotElevationSeq||gdShotElevationState.key!==key)return;
      gdShotElevationState.result={ok:false,key};
      gdShotElevationState.pendingKey=null;
    });
  },650);
}

function gdSlopeAdjustedDistanceData(origin,target,flatDistanceM){
  if(typeof gdTournamentModeEnabled==="function"&&gdTournamentModeEnabled())return null;
  if(targetDragging)return null;
  const key=gdElevationShotKey(origin,target);
  if(!key)return null;
  if(gdShotElevationState.key!==key){
    gdShotElevationState={key,result:null,pendingKey:null};
  }
  if(gdShotElevationState.result&&gdShotElevationState.result.key===key){
    const result=gdShotElevationState.result;
    if(!result.ok||!result.sourceMatch||!Number.isFinite(Number(result.deltaM)))return null;
    const adjustedM=Math.max(0,Number(flatDistanceM)+Number(result.deltaM));
    const adjusted=fmt(adjustedM);
    const delta=result.deltaMRounded>0?`+${result.deltaMRounded}`:`${result.deltaMRounded}`;
    const label=result.plays==="level"?"level":`${delta}m ${result.plays}`;
    const relation=adjustedM>Number(flatDistanceM)+.5?"over":(adjustedM<Number(flatDistanceM)-.5?"under":"level");
    return {adjusted,relation,label};
  }
  gdQueueShotElevation(origin,target,key);
  return null;
}
/* The legacy .gdSlopeAdjustedLine renderer and gdSlopeAdjustedDistanceHtml were
   removed with the Conditions Engine work: slope has rendered into #tilePlays
   via gdRenderShotCardSlope since that tile landed, the legacy class carried no
   CSS, and leaving a second slope-render path in place invited exactly the kind
   of duplicate environmental handling the Conditions Engine consolidates. */
function gdRenderShotCardSlope(tilePlays,slopeData){
  if(!tilePlays)return;
  tilePlays.classList.remove("slopeOver","slopeUnder","slopeLevel");
  tilePlays.innerHTML="";
  if(!slopeData)return;
  const tone=slopeData.relation==="over"?"slopeOver":(slopeData.relation==="under"?"slopeUnder":"slopeLevel");
  tilePlays.classList.add(tone);
  tilePlays.title=`Slope adjusted: ${slopeData.label||""}`;
  tilePlays.innerHTML=gdShotMetricHtml("Slope",slopeData.adjusted);
}

function gdClubTargetDeltaText(payload,centreDistanceM){
  if(!start||!target||!payload)return "";
  const stockM=gdFiniteNumber(payload.baseCarry,null);
  if(!(stockM>0))return "";
  const endLabel=pin?"pin":"centre";
  const endDistanceM=pin?map.distance(start,pin):centreDistanceM;
  const deltaM=endDistanceM-stockM;
  const shown=fmt(Math.abs(deltaM));
  const sign=Math.abs(deltaM)<0.5?"±":(deltaM>0?"+":"-");
  return `stock/${endLabel} ${sign}${shown.value}${shown.unit}`;
}
function gdShotStockDeltaData(payload,centreDistanceM){
  if(!start||!target||!payload)return null;
  const stockM=gdFiniteNumber(payload.baseCarry,null);
  const targetM=gdFiniteNumber(centreDistanceM,null);
  if(!(stockM>0)||!(targetM>0))return null;
  const deltaM=stockM-targetM;
  const shown=fmt(Math.abs(deltaM));
  const sign=Math.abs(deltaM)<0.5?"±":(deltaM>0?"+":"-");
  return {
    deltaM,
    sign,
    value:shown.value,
    unit:shown.unit,
    tone:Math.abs(deltaM)<0.5?"even":(deltaM>0?"plus":"minus")
  };
}
function gdShotStockDeltaHtml(payload,centreDistanceM){
  const data=gdShotStockDeltaData(payload,centreDistanceM);
  if(!data)return "Good stock number";
  const label=data.tone==="even"?"±0":`${data.sign}${data.value}`;
  return `Stock carry <span class="tileStockDelta ${data.tone}">${label}${data.unit}</span>`;
}
function gdShotTotalDeltaData(payload,centreDistanceM){
  if(!payload)return null;
  const stockTotalM=gdFiniteNumber(payload.totalM,gdFiniteNumber(payload.baseCarry,null));
  const targetM=gdFiniteNumber(centreDistanceM,null);
  if(!(stockTotalM>0)||!(targetM>0))return null;
  const deltaM=stockTotalM-targetM;
  const shown=fmt(Math.abs(deltaM));
  const sign=Math.abs(deltaM)<0.5?"±":(deltaM>0?"+":"-");
  return {
    deltaM,
    sign,
    value:shown.value,
    unit:shown.unit,
    tone:Math.abs(deltaM)<0.5?"even":(deltaM>0?"plus":"minus")
  };
}
function gdShotMetricValueHtml(metric,options={}){
  if(!metric||metric.value===null||metric.value===undefined||metric.value==="")return `<span class="${options.valueClass||"tileMetricValue"} missing">—<span class="dashUnit">${options.unit||""}</span></span>`;
  const tone=options.tone?` ${options.tone}`:"";
  return `<span class="${options.valueClass||"tileMetricValue"}${tone}">${metric.value}<span>${metric.unit||options.unit||""}</span></span>`;
}
function gdShotMetricHtml(label,metric,options={}){
  return `<span class="${options.labelClass||"tileMetricLabel"}">${label}</span>${gdShotMetricValueHtml(metric,options)}`;
}
function gdShotDistanceStackHtml(totalMetric,carryMetric){
  const total=gdShotMetricValueHtml(totalMetric,{});
  const carry=gdShotMetricValueHtml(carryMetric,{valueClass:"tileCarryValue"});
  return `<span class="tileMetricLabel">Total</span>${total}<span class="tileCarryLabel">Carry</span>${carry}`;
}
function gdCompactClubCode(label){
  const raw=String(label||"").trim();
  if(!raw)return "";
  const compact=raw.replace(/\s+/g,"");
  const lower=compact.toLowerCase();
  let match=lower.match(/^(\d+)(?:wood|w)$/);
  if(match)return `${match[1]}W`;
  match=lower.match(/^(\d+)(?:hybrid|hy|h)$/);
  if(match)return `${match[1]}H`;
  match=lower.match(/^(\d+)(?:iron|i)$/);
  if(match)return `${match[1]}i`;
  if(lower==="driver"||lower==="drv"||lower==="dr")return "DR";
  if(lower==="fairwaywood"||lower==="fairway"||lower==="fw")return "FW";
  if(lower==="hybrid"||lower==="rescue")return "HY";
  if(lower==="pitchingwedge"||lower==="pw")return "PW";
  if(lower==="gapwedge"||lower==="gw"||lower==="approachwedge"||lower==="aw")return "GW";
  if(lower==="sandwedge"||lower==="sw")return "SW";
  if(lower==="lobwedge"||lower==="lw")return "LW";
  if(lower==="putter"||lower==="pt")return "PT";
  if(/^[1-9][whi]$/i.test(compact))return compact[0]+compact[1].toUpperCase().replace("I","i");
  if(compact.length<=3)return compact;
  return compact.slice(0,3).toUpperCase();
}
function gdShotDisplayClubLabel(label){
  return gdCompactClubCode(label)||"GPS";
}
function gdResetShotDistanceDisplay(){
  const tile=document.getElementById("shotTile");
  const dist=document.getElementById("tileDist");
  const sub=document.getElementById("tileSub");
  const meta=document.getElementById("tileMeta");
  const back=document.getElementById("tileBack");
  const front=document.getElementById("tileFront");
  const plays=document.getElementById("tilePlays");
  const pinDiff=document.getElementById("pinDiff");
  if(dist)dist.innerHTML=`—<span>${units==="yd"?"yd":"m"}</span>`;
  if(sub)sub.textContent="";
  if(meta)meta.textContent="";
  if(back)back.innerHTML="";
  if(front)front.innerHTML="";
  if(plays){plays.classList.remove("slopeOver","slopeUnder","slopeLevel");plays.innerHTML="";}
  if(pinDiff){pinDiff.style.display="none";pinDiff.textContent="";}
  if(tile)tile.classList.remove("visible");
}
function gdShotBagIconHtml(){
  const railSrc=document.querySelector("#bagRailBtn img")?.getAttribute("src");
  const src=railSrc||"assets/home/bag.png";
  return `<button class="gdSetBagLink" onclick="gdOpenBagFromGps(event)" aria-label="Open bag"><img src="${src}" alt=""></button>`;
}
function gdShotPlaysData(origin,targetPoint,flatDistanceM){
  const data=gdSlopeAdjustedDistanceData(origin,targetPoint,flatDistanceM);
  if(!data)return {metric:null,tone:""};
  return {metric:data.adjusted,tone:data.relation==="over"?"slopeOver":(data.relation==="under"?"slopeUnder":"slopeLevel")};
}
function gdShotPinDiffData(){
  if(!start||!pin||!map)return null;
  const bubbleTarget=typeof gdShotDisplayTarget==="function"?gdShotDisplayTarget():target;
  if(!bubbleTarget)return null;
  const targetM=map.distance(start,bubbleTarget);
  const pinM=map.distance(start,pin);
  if(!Number.isFinite(targetM)||!Number.isFinite(pinM))return null;
  const deltaM=pinM-targetM;
  const shown=fmt(Math.abs(deltaM));
  return {
    value:Math.abs(deltaM)<0.5?"±0":`${deltaM>0?"+":"-"}${shown.value}`,
    unit:shown.unit,
    deltaM,
    tone:Math.abs(deltaM)<0.5?"even":(deltaM>0?"plus":"minus")
  };
}
function gdShotClubComparisonDistance(bubbleCenterDistance){
  return bubbleCenterDistance;
}
function gdShotStockDecisionText(payload,centreDistanceM){
  if(!start||!target||!payload)return "";
  const stockM=gdFiniteNumber(payload.baseCarry,null);
  if(!(stockM>0))return "";
  const endLabel=pin?"pin":"centre";
  const endDistanceM=pin?map.distance(start,pin):centreDistanceM;
  const deltaM=endDistanceM-stockM;
  if(Math.abs(deltaM)<0.5)return `Stock carry is on the ${endLabel}`;
  const shown=fmt(Math.abs(deltaM));
  return `Stock carry is ${shown.value}${shown.unit} ${deltaM>0?"short":"long"}`;
}
function gdRenderCarryLandingLine(payload){
  if(!start||!target||!payload||!map)return;
  if(!gdHasPlayableBag())return;
  const carryM=gdFiniteNumber(payload.baseCarry,null);
  const totalM=gdFiniteNumber(payload.totalM,null);
  if(!(carryM>0)||!(totalM>carryM+1))return;
  const center=gdBubbleRenderCenter(payload)||gdShotDisplayTarget()||target;
  if(!center)return;
  const shotBrg=gdBubbleShotBearing();
  const centerDistance=map.distance(start,center);
  const centerAngle=bearing(start,center);
  const centerForwardM=Math.cos(normAng(centerAngle-shotBrg))*centerDistance;
  const x=carryM-centerForwardM;
  const axes=gdBubbleAxes(payload,Math.max(.72,dev("bubbleVisuals.mainScale")*.88));
  const edgeRatio=Math.abs(x)/Math.max(1,axes.depth);
  if(edgeRatio>=.98)return;
  if(gdHasWindVector()){
    const stockPoint=gdBubbleLocalToLatLng(center,payload,x,0);
    bubbleCarryLine=L.circleMarker(stockPoint,{
      radius:4.25,
      color:"#d8ffe9",
      weight:1.25,
      opacity:.7,
      fillColor:"#d8ffe9",
      fillOpacity:.42,
      interactive:false
    }).addTo(map);
    return;
  }
  const halfWidth=Math.max(3,axes.lateral*Math.sqrt(1-edgeRatio*edgeRatio)*.82);
  const left=gdBubbleLocalToLatLng(center,payload,x,-halfWidth);
  const right=gdBubbleLocalToLatLng(center,payload,x,halfWidth);
  bubbleCarryLine=L.polyline([left,right],{
    color:"#d8ffe9",
    weight:1.35,
    opacity:.36,
    dashArray:"2,5",
    interactive:false
  }).addTo(map);
}
function clearRemainingGreenLine(){
  [remainingGreenLine,remainingGreenLabel].forEach(l=>l&&map.removeLayer(l));
  remainingGreenLine=remainingGreenLabel=null;
}
function updateRemainingGreenLine(){
  clearRemainingGreenLine();
}
function gdGreenEdgeDistanceMetrics(pts){
  if(!start||!Array.isArray(pts)||pts.length<3||typeof map==="undefined"||!map)return null;
  let frontM=Infinity,backM=-Infinity;
  pts.forEach(p=>{
    try{
      const d=map.distance(start,p);
      if(!Number.isFinite(d))return;
      if(d<frontM)frontM=d;
      if(d>backM)backM=d;
    }catch(e){}
  });
  if(!Number.isFinite(frontM)||!Number.isFinite(backM)||frontM===Infinity||backM<0)return null;
  return {frontM,backM,front:fmt(frontM),back:fmt(backM)};
}
function gdShotGreenEdgeMetrics(){
  let pts=greenPolygon;
  if((!Array.isArray(pts)||pts.length<3)&&window.GolfDaddyCourseLibrary&&typeof window.GolfDaddyCourseLibrary.activeGreenShape==="function"){
    try{
      const saved=window.GolfDaddyCourseLibrary.activeGreenShape();
      if(Array.isArray(saved)&&saved.length>=3)pts=saved.map(p=>L.latLng(Number(p.lat),Number(p.lng))).filter(p=>Number.isFinite(p.lat)&&Number.isFinite(p.lng));
    }catch(e){}
  }
  return gdGreenEdgeDistanceMetrics(pts);
}
function gdShotGreenEdgesHtml(){
  const metrics=gdShotGreenEdgeMetrics();
  if(!metrics)return "";
  return `<span>Front ${metrics.front.value}${metrics.front.unit}</span><span>Back ${metrics.back.value}${metrics.back.unit}</span>`;
}

window.GolfDaddyElevationChannel={
  getShotElevation:gdGetShotElevation,
  clearCache:()=>{gdElevationPointCache.clear();gdShotElevationState={key:null,result:null,pendingKey:null};}
};

function gdStatsRoundId(){
  try{
    const course=currentCourse&&currentCourse.name?String(currentCourse.name):"Manual GPS";
    const profile=typeof activePlayerProfile==="function"?activePlayerProfile():null;
    const player=String(profile?.id||"player").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-+|-+$/g,"").slice(0,28)||"player";
    return `round-${player}-${course.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-+|-+$/g,"")||"manual-gps"}-${new Date().toISOString().slice(0,10)}`;
  }catch(e){
    return `round-manual-gps-${new Date().toISOString().slice(0,10)}`;
  }
}
function gdStatsHoleId(){
  try{return `hole-${Number(currentPlayingHole||selectedHole||1)||1}`;}catch(e){return "hole-1";}
}
function gdCaptureShotStatsFromGps(distanceM,payload,clubLabel,reason="lock-in"){
  if(typeof gdTournamentModeEnabled==="function"&&gdTournamentModeEnabled())return null;
  try{
    const stats=window.GolfDaddy&&window.GolfDaddy.modules&&window.GolfDaddy.modules.shotEvents;
    if(!stats||!start||!target||targetDragging)return;
    const center=gdBubbleRenderCenter(payload)||target;
    if(!center)return;
    const lengthM=Math.max(1,gdFiniteNumber(payload.depthRadiusM,gdFiniteNumber(payload.visual&&payload.visual.visualDepthM,payload.radius*2)/2)*2);
    const widthM=Math.max(1,gdFiniteNumber(payload.lateralRadiusM,gdFiniteNumber(payload.visual&&payload.visual.visualWidthM,payload.radius*2)/2)*2);
    const orientationDeg=((bearing(start,target)*180/Math.PI)+360)%360;
    const key=[
      "gps-bubble",
      Math.round(start.lat*100000),
      Math.round(start.lng*100000),
      Math.round(center.lat*100000),
      Math.round(center.lng*100000),
      Math.round(lengthM*10),
      Math.round(widthM*10),
      clubLabel||"GPS"
    ].join(":");
    return stats.captureBubbleRendered({
      roundId:gdStatsRoundId(),
      holeId:gdStatsHoleId(),
      origin:{lat:start.lat,lng:start.lng},
      plannedBubble:{
        centerLat:center.lat,
        centerLng:center.lng,
        orientationDeg,
        lengthYards:lengthM*1.0936132983,
        widthYards:widthM*1.0936132983,
        shape:"oval"
      },
	      club:clubLabel||"GPS",
	      expectedDistanceYards:Number(distanceM)*1.0936132983,
	      renderKey:key,
	      captureReason:reason
	    });
  }catch(e){
    console.warn("[GolfDaddy] shot stat capture skipped",e);
    return null;
  }
}

function gdRefreshCourseDataSurfaces(){
  try{if(typeof renderStats==="function")renderStats();}catch(e){}
  try{if(typeof renderDataHubStatus==="function")renderDataHubStatus();}catch(e){}
  try{if(typeof renderCompareData==="function")renderCompareData();}catch(e){}
}
function gdDiscardCurrentPlannedShot(){
  try{
    const shotId=gdCurrentPlannedShotId;
    const api=window.GolfDaddyShotEvents||window.GolfDaddy?.modules?.shotEvents;
    if(api&&typeof api.clearPendingShot==="function"){
      api.clearPendingShot();
      return;
    }
    if(!shotId)return;
    const store=api?.getStore?.();
    if(!api||!store)return;
    const planned=Array.isArray(store.plannedShots)?store.plannedShots:[];
    const shot=planned.find(item=>item&&item.shotId===shotId);
    if(shot&&!shot.pairedOutcomeId){
      if(typeof api.deleteShot==="function")api.deleteShot(shotId);
      else{
        store.plannedShots=planned.filter(item=>item&&item.shotId!==shotId);
        store.updatedAt=new Date().toISOString();
        gdSafeLocalSet(api.storageKey||"gd_shot_events_v1",JSON.stringify(store));
      }
    }
  }catch(e){
    console.warn("[GolfDaddy] planned shot discard skipped",e);
  }finally{
    gdCurrentPlannedShotId=null;
    currentShotLogged=false;
    gdRefreshCourseDataSurfaces();
  }
}
function gdMarkCurrentPlanDirty(){
  if(gdCurrentPlannedShotId)gdDiscardCurrentPlannedShot();
  currentShotLogged=false;
}
function gdCaptureCurrentPlannedShot(reason="lock-in"){
  if(typeof gdTournamentModeEnabled==="function"&&gdTournamentModeEnabled())return null;
  try{
    if(!start||!target)return null;
    if(currentShotLogged&&gdCurrentPlannedShotId)return gdCurrentPlannedShotId;
    const d=map.distance(start,target);
    const shot=calculateShot(d);
    const payload=getGpsBubblePayload(d);
    const clubLabel=payload.club||shot.club||"GPS";
	    const planned=gdCaptureShotStatsFromGps(d,payload,clubLabel,reason);
    if(planned&&planned.shotId){
      gdCurrentPlannedShotId=planned.shotId;
      currentShotLogged=true;
      try{planned.captureReason=reason;}catch(e){}
      gdRefreshCourseDataSurfaces();
      return planned.shotId;
    }
  }catch(e){
    console.warn("[GolfDaddy] planned shot capture failed",e);
  }
  return null;
}
function gdShotEventsApi(){
  const existing=window.GolfDaddyShotEvents||window.GolfDaddy?.modules?.shotEvents;
  if(existing&&typeof existing.logBallPosition==="function")return existing;
  const key="gd_shot_events_v1";
  const root=window.GolfDaddy=window.GolfDaddy||{};
  root.modules=root.modules||{};
  const read=()=>{
    try{return JSON.parse(localStorage.getItem(key)||"null")||{version:1,ballEvents:[],plannedShots:[],outcomes:[]};}
    catch(e){return {version:1,ballEvents:[],plannedShots:[],outcomes:[]};}
  };
  const write=store=>{
    store.ballEvents=Array.isArray(store.ballEvents)?store.ballEvents:[];
    store.plannedShots=Array.isArray(store.plannedShots)?store.plannedShots:[];
    store.outcomes=Array.isArray(store.outcomes)?store.outcomes:[];
    store.updatedAt=new Date().toISOString();
    try{localStorage.setItem(key,JSON.stringify(store));}catch(e){}
    return store;
  };
  const api={
    storageKey:key,
    getStore:read,
    listBallEvents:()=>read().ballEvents.slice(),
    listPlannedShots:()=>read().plannedShots.slice(),
    listOutcomes:()=>read().outcomes.slice(),
    pairPendingShots:()=>[],
    logBallPosition(input){
      const store=read();
      const event={
        eventId:"bpe-"+Date.now().toString(36)+"-"+Math.random().toString(36).slice(2,8),
        roundId:input?.roundId||gdStatsRoundId(),
        holeId:input?.holeId||gdStatsHoleId(),
        source:input?.source||"at_my_ball_button",
        timestamp:input?.timestamp||new Date().toISOString(),
        lat:Number(input?.lat),
        lng:Number(input?.lng),
        gpsAccuracyM:Number.isFinite(Number(input?.gpsAccuracyM))?Number(input.gpsAccuracyM):null,
        motionContext:input?.motionContext||"outcome_log_button",
        courseContext:input?.courseContext||"gps_course",
        confidence:input?.confidence||"high",
        mergedEventIds:[]
      };
      if(!Number.isFinite(event.lat)||!Number.isFinite(event.lng))throw new Error("Shot event needs a point");
      store.ballEvents=Array.isArray(store.ballEvents)?store.ballEvents:[];
      store.ballEvents.push(event);
      write(store);
      return {event,merged:false};
    }
  };
  root.modules.shotEvents=api;
  window.GolfDaddyShotEvents=api;
  window.ClarityCaddieShotEvents=api;
  return api;
}
/* ---------------- Course Data handoff: immutable Shot Snapshot ----------------
   GPS Play's only analytical output. At shot completion we record the best raw
   evidence available and hand it to Course Data, which owns validation,
   persistence and the Conditions Engine. GPS Play performs no wind correction,
   no slope correction, no My Bubble comparison and no variant selection, and it
   never waits for analysis: submitShotSnapshot persists the raw snapshot and
   returns, with analysis deferred to a later tick.
------------------------------------------------------------------------------ */
function gdCourseDataIntake(){
  return window.GolfDaddyCourseDataIntake||window.GolfDaddy?.modules?.courseDataIntake||null;
}
function gdSnapshotPlayerId(){
  try{
    const events=window.GolfDaddyShotEvents||window.GolfDaddy?.modules?.shotEvents;
    const scope=events&&typeof events.activePlayerScope==="function"?events.activePlayerScope():null;
    return scope&&scope.playerId?scope.playerId:null;
  }catch(e){return null;}
}
function gdSnapshotCourseId(){
  try{
    const course=JSON.parse(localStorage.getItem("gd_active_course_v1")||"null");
    return course&&(course.id||course.courseId)||null;
  }catch(e){return null;}
}
function gdLiveWindEvidenceForSnapshot(){
  const data=gdLiveWindState&&gdLiveWindState.data;
  if(!data||!Number.isFinite(Number(data.directionDeg)))return {liveWindAvailable:false};
  return {
    liveWindAvailable:true,
    liveWindSpeed:Number(data.speedKmh),
    liveWindDirection:Number(data.directionDeg),
    liveWindScaleLevel:Number(data.level)||gdWindLevelForSpeed(data.speedKmh),
    liveWindSource:data.source||"Open-Meteo",
    liveWindCapturedAt:data.fetchedAt?new Date(Number(data.fetchedAt)).toISOString():null,
    // Freshness is the only confidence signal the wind source gives us.
    liveWindConfidence:gdLiveWindFresh()?"high":"low"
  };
}
function gdLiveSlopeEvidenceForSnapshot(){
  const result=gdShotElevationState&&gdShotElevationState.result;
  if(!result||!result.ok||!Number.isFinite(Number(result.deltaM)))return {liveSlopeAvailable:false};
  return {
    liveSlopeAvailable:true,
    liveSlopeValue:Number(result.deltaM),
    liveSlopeDirection:result.plays||null,
    liveSlopeSource:result.origin?.source||"open-meteo",
    liveSlopeCapturedAt:result.sampledAt||null,
    // A mixed-source pair cannot be trusted as a like-for-like elevation delta.
    liveSlopeConfidence:result.sourceMatch?(result.origin?.confidence||"medium"):"none"
  };
}
function gdSubmitCourseDataShotSnapshot(landing,gpsAccuracyM,reason,ballEvent){
  if(typeof gdTournamentModeEnabled==="function"&&gdTournamentModeEnabled())return null;
  try{
    const intake=gdCourseDataIntake();
    const builder=window.GolfDaddyShotSnapshot||window.GolfDaddy?.modules?.shotSnapshot;
    if(!intake||!builder||!start||!landing)return null;

    const aimTarget=target||landing;
    const flatDistance=map.distance(start,landing);
    const payload=target?getGpsBubblePayload(map.distance(start,target)):null;
    const clubLabel=payload?.club||(target?calculateShot(map.distance(start,target)).club:null)||"GPS";

    // Freeze the bubble geometry that was live at capture time so this shot is
    // never re-analysed against a newer My Bubble.
    let bubbleVersionId=null,bubbleGeometry=null;
    if(payload&&target){
      const centre=gdBubbleRenderCenter(payload)||target;
      const depthM=Math.max(1,gdFiniteNumber(payload.depthRadiusM,1)*2);
      const widthM=Math.max(1,gdFiniteNumber(payload.lateralRadiusM,1)*2);
      const geometry={
        club:clubLabel,
        centerLat:centre.lat,
        centerLng:centre.lng,
        orientationDeg:((bearing(start,target)*180/Math.PI)+360)%360,
        widthM,
        depthM,
        carryM:gdFiniteNumber(payload.baseCarry,null),
        totalM:gdFiniteNumber(payload.totalM,null),
        offsetDeg:gdFiniteNumber(payload.faceAlignmentOffsetDeg,0),
        source:"gps-bubble"
      };
      const version=intake.registerMyBubbleVersion(geometry,{source:"gps-bubble"});
      bubbleVersionId=version?.versionId||null;
      bubbleGeometry=version?.geometry||geometry;
    }

    const windEvidence=gdLiveWindEvidenceForSnapshot();
    const slopeEvidence=gdLiveSlopeEvidenceForSnapshot();
    const userSelectedWind=!!gdWindActive&&gdWindSelectionSource==="user";

    const snapshot=builder.buildShotSnapshot(Object.assign({
      shotId:gdCurrentPlannedShotId||(ballEvent&&ballEvent.eventId?`snap-${ballEvent.eventId}`:null)||`snap-${Date.now()}`,
      roundId:gdStatsRoundId(),
      playerId:gdSnapshotPlayerId(),
      courseId:gdSnapshotCourseId(),
      holeNumber:Number(currentPlayingHole||selectedHole||0)||null,
      capturedAt:new Date().toISOString(),

      clubId:clubLabel,
      shotStartPosition:{lat:start.lat,lng:start.lng},
      shotLandingPosition:{lat:landing.lat,lng:landing.lng},
      targetPosition:{lat:aimTarget.lat,lng:aimTarget.lng},
      intendedDirection:target?((bearing(start,target)*180/Math.PI)+360)%360:null,
      shotDistance:flatDistance,

      myBubbleVersionId:bubbleVersionId,
      myBubbleGeometry:bubbleGeometry,
      bagVersionId:null,

      userSelectedWind,
      userWindSelection:userSelectedWind?{
        scaleLevel:gdWindLevel,
        directionDeg:Number.isFinite(Number(gdWindOriginAngle))?((Number(gdWindOriginAngle)*180/Math.PI)+360)%360:null
      }:null,
      userWindIntent:userSelectedWind?"manual-wind-tool":null,

      // No slope selection surface exists in GPS Play today; recorded honestly
      // rather than inferred.
      userSelectedSlope:false,
      userSlopeSelection:null,
      userSlopeIntent:null,

      gpsAccuracy:Number.isFinite(Number(gpsAccuracyM))?Number(gpsAccuracyM):null,
      landingConfidence:ballEvent&&ballEvent.confidence?ballEvent.confidence:"medium",
      targetConfidence:targetWasMoved?"high":"medium",
      shotCaptureMethod:reason||"next_shot_button"
    },windEvidence,slopeEvidence));

    return intake.submitShotSnapshot(snapshot);
  }catch(e){
    // Course Data handoff must never interrupt the round.
    console.warn("[GolfDaddy] shot snapshot submission skipped",e);
    return null;
  }
}
function gdLogBallPositionForTracking(ll,reason="next_shot_button",gpsAccuracyM=null){
  if(typeof gdTournamentModeEnabled==="function"&&gdTournamentModeEnabled())return null;
  try{
    const stats=gdShotEventsApi();
    if(!stats||!ll)return null;
    const source=String(reason||"").includes("shake")?"phone_shake":"at_my_ball_button";
    if(typeof stats.logOutcomeForPending==="function"){
      const logged=stats.logOutcomeForPending({
        roundId:gdStatsRoundId(),
        holeId:gdStatsHoleId(),
        source,
        lat:ll.lat,
        lng:ll.lng,
        gpsAccuracyM:Number.isFinite(Number(gpsAccuracyM))?Number(gpsAccuracyM):null,
        motionContext:reason,
        courseContext:"gps_course",
        confidence:source==="phone_shake"?"medium":"high"
      });
      gdSubmitCourseDataShotSnapshot(ll,gpsAccuracyM,reason,logged);
      gdRefreshCourseDataSurfaces();
      return logged;
    }
    const result=stats.logBallPosition({
      roundId:gdStatsRoundId(),
      holeId:gdStatsHoleId(),
      source,
      lat:ll.lat,
      lng:ll.lng,
      gpsAccuracyM:Number.isFinite(Number(gpsAccuracyM))?Number(gpsAccuracyM):null,
      motionContext:reason,
      courseContext:"gps_course",
      confidence:source==="phone_shake"?"medium":"high"
    });
    try{stats.pairPendingShots&&stats.pairPendingShots();}catch(e){}
    gdSubmitCourseDataShotSnapshot(ll,gpsAccuracyM,reason,result);
    gdRefreshCourseDataSurfaces();
    return result;
  }catch(e){
    console.warn("[GolfDaddy] ball position log failed",e);
    return null;
  }
}
function gdClearShotForNextStart(nextStart){
  try{if(typeof clearReplaceGreenMode==="function")clearReplaceGreenMode();}catch(e){}
  try{if(typeof unlockFrameForReset==="function")unlockFrameForReset();else if(typeof setBubbleOnlyLock==="function")setBubbleOnlyLock(false);}catch(e){}
  try{clearShot();}catch(e){}
  try{[targetMarker,greenMarker,pinMarker,pinDirectionLine,greenOutline,greenSoft,greenLabel,frontLabel,backLabel].forEach(gdRemoveMapLayer);}catch(e){}
  targetMarker=greenMarker=pinMarker=pinDirectionLine=greenOutline=greenSoft=greenLabel=frontLabel=backLabel=null;
  greenPolygon=null;
  target=greenCentre=pin=null;
  gdWindLandingTarget=null;
  lockedFrame=false;
  targetWasMoved=false;
  currentShotLogged=false;
  gdCurrentPlannedShotId=null;
  targetDragging=false;
  undoStack=[];
  if(nextStart){
    start=nextStart;
    if(startMarker)startMarker.setLatLng(start);
    else startMarker=L.marker(start,{icon:startIcon,interactive:false}).addTo(map);
    mode="green";
  }else{
    start=null;
    gdRemoveMapLayer(startMarker);
    startMarker=null;
    mode="start";
  }
  document.getElementById("shotTile")?.classList.remove("visible");
  app.classList.remove("framed");
}
function gdPendingCourseShot(){
  try{
    const api=window.GolfDaddyShotEvents||window.GolfDaddy?.modules?.shotEvents;
    return api&&typeof api.getPendingShot==="function"?api.getPendingShot():null;
  }catch(e){
    return null;
  }
}
function gdOutcomeLogMessage(logged){
  if(!logged)return "No locked shot to log";
  const reason=String(logged.excludedReason||logged.outcome?.excludedReason||"");
  if(logged.excluded||logged.outcome?.excluded){
    if(reason==="weak_gps")return "Shot saved but not counted: GPS was weak";
    if(reason==="stale_outcome")return "Shot saved but not counted: too much time passed";
    return "Shot saved but not counted";
  }
  return "Outcome logged";
}
function gdBeginManualShotVerification(reason="manual_outcome_button"){
  window.gdPendingManualShotVerification=true;
  window.gdPendingManualShotVerificationReason=reason;
  gdClearShotForNextStart(null);
  setState("Verify shot");
  showHint("Tap where the shot finished");
  toast("Tap your ball to verify the shot");
  try{gdSyncNewShotButtonState();}catch(e){}
}
function gdCompleteManualShotVerification(ll){
  if(!window.gdPendingManualShotVerification||!ll)return;
  window.gdPendingManualShotVerification=false;
  const reason=window.gdPendingManualShotVerificationReason||"manual_shot_hit_verification";
  window.gdPendingManualShotVerificationReason="";
  const logged=gdLogBallPositionForTracking(ll,reason,null);
  if(gdMappedCourseAssistActive()){setState("Mapped: set position");showHint("Tap where you are standing")}
  else{setState("Set green");showHint("Tap green centre")}
  toast(gdOutcomeLogMessage(logged));
  try{gdSyncNewShotButtonState();}catch(e){}
}
function gdUseNextShotPosition(ll,reason,gpsAccuracyM){
  if(!ll)return gdBeginManualShotVerification(reason||"manual_outcome_button");
  const previousShot=gdShotStateSnapshot("before-next-shot");
  const logged=gdLogBallPositionForTracking(ll,reason||"next_shot_button",gpsAccuracyM);
  gdClearShotForNextStart(ll);
  if(previousShot)undoStack=[previousShot];
  if(gdMappedCourseAssistActive()){setState("Mapped: set position");showHint("Tap where you are standing")}
  else{setState("Set green");showHint("Tap green centre")}
  toast(logged?`${gdOutcomeLogMessage(logged)} · New shot ready`:"Lock a shot before logging outcome");
  try{gdSyncNewShotButtonState();}catch(e){}
}
function gdAutoNextShotSetting(path,fallback){
  try{
    if(typeof dev==="function"){
      const value=Number(dev("autoNextShot."+path));
      if(Number.isFinite(value))return value;
    }
  }catch(e){}
  return fallback;
}
function gdAutoNextShotEnabled(){
  return false;
}
function gdMaybeAutoNextShotFromGps(here,accuracyM){
  return false;
}
function gdGpsNewShot(reason="next_shot_button"){
  if(document.body.classList.contains("gdGreenArrivalMode"))return gdFinishActiveGreenFocus(reason||"shot_end_green_focus");
  const pending=gdPendingCourseShot();
  if(!pending&&!target){
    toast("Lock in a shot first");
    return false;
  }
  if(target){
    if(!currentShotLogged||!gdCurrentPlannedShotId)gdCaptureCurrentPlannedShot("next-shot");
  }
  const manualMode=typeof gdGpsPlayMode==="function"&&gdGpsPlayMode()!=="live";
  if(manualMode||!navigator.geolocation){
    gdBeginManualShotVerification(reason||"manual_outcome_button");
    return false;
  }
  setState("Logging outcome");
  toast("Checking GPS for outcome");
  navigator.geolocation.getCurrentPosition(pos=>{
    const here=L.latLng(pos.coords.latitude,pos.coords.longitude);
    gdUseNextShotPosition(here,reason||"next_shot_button",pos.coords.accuracy);
  },()=>{
    gdBeginManualShotVerification(reason||"manual_outcome_button");
  },{enableHighAccuracy:true,maximumAge:0,timeout:7000});
  return false;
}
function gdSyncNewShotButtonState(){
  const unlockBtn=document.getElementById("gdV62NewShotBtn");
  const logBtn=document.getElementById("gdV62LogShotBtn");
  if(!unlockBtn&&!logBtn)return;
  const pending=!!window.gdPendingManualShotVerification;
  const greenFocusActive=!!document.body.classList.contains("gdGreenArrivalMode");
  const hasLockedShot=greenFocusActive||!!(gdPendingCourseShot()||target);
  const icon=`<svg class="gdLogShotIcon" viewBox="0 0 100 100" aria-hidden="true">
    <path class="gdShakeEcho faint" d="M25 25c-5 1-8 4-8 9l9 41c1 5 4 8 9 8h3"/>
    <path class="gdShakeEcho" d="M32 24c-5 1-8 4-8 9l5 42c1 5 4 8 9 8h4"/>
    <path class="gdShakeEcho" d="M68 24c5 1 8 4 8 9l-5 42c-1 5-4 8-9 8h-4"/>
    <path class="gdShakeEcho faint" d="M75 25c5 1 8 4 8 9l-9 41c-1 5-4 8-9 8h-3"/>
    <rect class="gdPhoneFace" x="36" y="22" width="28" height="58" rx="7"/>
    <rect class="gdPhoneIsland" x="46" y="27.2" width="8" height="2.8" rx="1.4"/>
    <circle class="gdCameraLens" cx="52.6" cy="28.6" r=".65"/>
    <rect class="gdSideButton" x="33.9" y="34.5" width="2.1" height="5.8" rx="1"/>
    <rect class="gdSideButton" x="33.9" y="42.6" width="2.1" height="5.4" rx="1"/>
    <rect class="gdSideButton" x="64" y="35.5" width="2.1" height="7.5" rx="1"/>
    <path class="gdTopArrow" d="M35 16c9-7 21-7 30 0"/>
    <path class="gdTopArrowHead" d="M35.8 11.6 29.8 17l7.6 2.4Z"/>
    <path class="gdTopArrowHead" d="M64.2 11.6 70.2 17l-7.6 2.4Z"/>
  </svg>`;
  if(unlockBtn){
    unlockBtn.classList.remove("pending","unlock-ready");
    unlockBtn.textContent="Unlock";
    unlockBtn.title=hasLockedShot||target?"Unlock the current shot frame":"Unlock shot setup";
    unlockBtn.setAttribute("aria-label",unlockBtn.title);
  }
  if(logBtn){
    logBtn.classList.toggle("pending",pending);
    logBtn.classList.toggle("disabled",!hasLockedShot&&!pending);
    logBtn.setAttribute("aria-disabled",(!hasLockedShot&&!pending)?"true":"false");
    logBtn.innerHTML=`${icon}<span class="gdLogShotText">Shot End</span>`;
    logBtn.title=greenFocusActive?"Log green position":pending?"Tap where the shot finished. You can also shake your phone to log it.":hasLockedShot?"Log this shot outcome":"Lock in a shot first";
    logBtn.setAttribute("aria-label",logBtn.title);
  }
}
window.gdGpsNewShot=gdGpsNewShot;
window.gdGpsLogShot=gdGpsNewShot;
window.gdSyncNewShotButtonState=gdSyncNewShotButtonState;
let gdOutcomeShakeLastAt=0;
function gdOutcomeShakeMagnitude(event){
  const a=event&&event.accelerationIncludingGravity||event&&event.acceleration;
  if(!a)return 0;
  const x=Number(a.x)||0,y=Number(a.y)||0,z=Number(a.z)||0;
  return Math.hypot(x,y,z);
}
function gdMaybeLogOutcomeFromShake(event){
  try{
    if(!gdPendingCourseShot()||window.gdPendingManualShotVerification)return;
    const now=Date.now();
    if(now-gdOutcomeShakeLastAt<3500)return;
    if(gdOutcomeShakeMagnitude(event)<26)return;
    gdOutcomeShakeLastAt=now;
    toast("Shake detected");
    gdGpsNewShot("phone_shake");
  }catch(e){}
}
function gdInstallOutcomeShakeLogging(){
  try{
    if(window.__gdOutcomeShakeLoggingInstalled)return;
    window.__gdOutcomeShakeLoggingInstalled=true;
    window.addEventListener("devicemotion",gdMaybeLogOutcomeFromShake,true);
  }catch(e){}
}
gdInstallOutcomeShakeLogging();

function gdClearGpsFocusModeLayer(){
  if(gdFocusMasks&&gdFocusMasks.length)gdFocusMasks.forEach(layer=>{try{map.removeLayer(layer)}catch(e){}});
  gdFocusMasks=[];
}
function gdFocusOuterMask(hole,opacity,className="gdGpsFocusMask"){
  if(!hole||hole.length<3)return null;
  const outer=[
    L.latLng(85,-180),
    L.latLng(85,180),
    L.latLng(-85,180),
    L.latLng(-85,-180)
  ];
  return L.polygon([outer,hole],{
    pane:"gd-focus",
    interactive:false,
    bubblingMouseEvents:false,
    stroke:false,
    fill:true,
    fillRule:"evenodd",
    fillColor:"#000000",
    fillOpacity:opacity,
    className
  }).addTo(map);
}
function gdFocusModeCorridor(gdb,scale=1,shotStart=start,shotTarget=target){
  if(!shotStart||!shotTarget)return null;
  const shotBrg=bearing(shotStart,shotTarget);
  const distance=Math.max(1,map.distance(shotStart,shotTarget));
  const bubbleRadius=gdFiniteNumber(gdb?.radius,Math.max(14,distance*.08));
  const lateralRadius=gdFiniteNumber(gdb?.lateralRadiusM,bubbleRadius);
  const baseHalfWidth=Math.max(34,Math.min(108,lateralRadius+28,distance*.28));
  const sideScale=gdShouldShowMiddleDistanceGuide(gdb) ? .54 : 1;
  const halfWidth=baseHalfWidth*scale*sideScale;
  const startRadius=Math.max(18,Math.min(38,baseHalfWidth*.58))*scale;
  const targetRadius=Math.max(baseHalfWidth*1.16,bubbleRadius*1.42)*scale;
  const back=project(shotStart,shotBrg+Math.PI,startRadius);
  const capCenter=project(shotTarget,shotBrg,Math.max(18,targetRadius*.32));
  const beyond=project(shotTarget,shotBrg,Math.max(28,targetRadius*.88));
  const leftStart=projectOffset(back,shotBrg,0,-halfWidth*.72);
  const rightStart=projectOffset(back,shotBrg,0,halfWidth*.72);
  const leftMid=projectOffset(shotStart,shotBrg,distance*.45,-halfWidth);
  const rightMid=projectOffset(shotStart,shotBrg,distance*.45,halfWidth);
  const shoulderWidth=Math.max(halfWidth,targetRadius*.72*sideScale);
  const leftShoulder=projectOffset(shotStart,shotBrg,distance*.78,-shoulderWidth);
  const rightShoulder=projectOffset(shotStart,shotBrg,distance*.78,shoulderWidth);
  const cap=[];
  for(let i=0;i<=10;i++){
    const t=i/10;
    const rel=-Math.PI/2 + t*Math.PI;
    cap.push(projectOffset(capCenter,shotBrg,Math.max(0,Math.cos(rel))*targetRadius,Math.sin(rel)*targetRadius*sideScale));
  }
  return [leftStart,leftMid,leftShoulder,...cap,rightShoulder,rightMid,rightStart];
}
function gdFocusBubbleHole(gdb,scale=1){
  const center=(typeof gdBubbleRenderCenter==="function"&&gdBubbleRenderCenter(gdb))||gdShotDisplayTarget()||target;
  if(!center)return null;
  try{
    return buildBubbleShape(center,gdb,scale);
  }catch(e){
    const shotBrg=(start&&target)?bearing(start,target):0;
    const radius=Math.max(12,gdFiniteNumber(gdb?.radius,24))*scale;
    return Array.from({length:72},(_,i)=>{
      const a=(Math.PI*2*i)/72;
      return projectOffset(center,shotBrg,Math.cos(a)*radius,Math.sin(a)*radius);
    });
  }
}
function gdUpdateGpsFocusModeLayer(gdb){
  gdClearGpsFocusModeLayer();
  if(!start||!target||mode!=="aim")return;
  const frameStart=(lockedFrame&&gdFocusFrameStart)?gdFocusFrameStart:start;
  const frameTarget=(lockedFrame&&gdFocusFrameTarget)?gdFocusFrameTarget:target;
  [
    {scale:2.12,opacity:.34},
    {scale:1.82,opacity:.18},
    {scale:1.58,opacity:.12},
    {scale:1.38,opacity:.08},
    {scale:1.22,opacity:.055},
    {scale:1.08,opacity:.035}
  ].forEach(part=>{
    const corridor=gdFocusModeCorridor(gdb,part.scale,frameStart,frameTarget);
    const mask=gdFocusOuterMask(corridor,part.opacity,"gdGpsFocusMask gdGpsFrameMask");
    if(mask)gdFocusMasks.push(mask);
  });
  const bubbleHole=gdFocusBubbleHole(gdb,1);
  const bubbleMask=gdFocusOuterMask(bubbleHole,.34,"gdGpsFocusMask gdGpsBubbleMask");
  if(bubbleMask)gdFocusMasks.push(bubbleMask);
}
function gdBuildAimLinePixelCanvas(){
  try{
    const mapEl=document.getElementById("map");
    const size=map.getSize?map.getSize():{x:mapEl.clientWidth,y:mapEl.clientHeight};
    const canvas=document.createElement("canvas");
    canvas.width=Math.round(size.x||mapEl.clientWidth);
    canvas.height=Math.round(size.y||mapEl.clientHeight);
    const ctx=canvas.getContext("2d",{willReadFrequently:true});
    if(!ctx)return null;
    const mapPane=map.getPane?map.getPane("mapPane"):mapEl.querySelector(".leaflet-map-pane");
    const tilePane=map.getPane?map.getPane("tilePane"):mapEl.querySelector(".leaflet-tile-pane");
    const mapPanePos=gdTilePos(mapPane);
    const tilePanePos=gdTilePos(tilePane);
    let drawn=0;
    [...mapEl.querySelectorAll("img.leaflet-tile")]
      .filter(img=>img.complete&&img.naturalWidth&&img.naturalHeight)
      .forEach(img=>{
        try{
          const tilePos=gdTilePos(img);
          const w=parseFloat(img.style.width)||img.width||img.naturalWidth||256;
          const h=parseFloat(img.style.height)||img.height||img.naturalHeight||256;
          const x=Math.round(mapPanePos.x+tilePanePos.x+tilePos.x);
          const y=Math.round(mapPanePos.y+tilePanePos.y+tilePos.y);
          if(x+w<0||y+h<0||x>canvas.width||y>canvas.height)return;
          ctx.drawImage(img,x,y,w,h);
          drawn++;
        }catch(e){}
      });
    if(!drawn||!gdCanvasHasUsefulPixels(canvas))return null;
    ctx.getImageData(0,0,1,1);
    return{canvas,ctx};
  }catch(e){
    return null;
  }
}
function gdAimSignificantPixelScore(ctx,x,y){
  let hits=0,total=0,lumSum=0,lumSq=0;
  let rSum=0,gSum=0,bSum=0;
  for(let dy=-5;dy<=5;dy+=2){
    for(let dx=-5;dx<=5;dx+=2){
      try{
        const p=ctx.getImageData(Math.round(x+dx),Math.round(y+dy),1,1).data;
        const r=p[0],g=p[1],b=p[2],a=p[3];
        if(a<20)continue;
        total++;
        const max=Math.max(r,g,b),min=Math.min(r,g,b),lum=(r+g+b)/3;
        lumSum+=lum;
        lumSq+=lum*lum;
        rSum+=r;gSum+=g;bSum+=b;
        const chroma=max-min;
        const darkMass=lum>16&&lum<96&&chroma>8;
        const brightObject=lum>138&&chroma>10;
        const saturatedObject=chroma>34&&lum>28&&lum<178;
        const realWorldColourCue=chroma>48&&lum>42&&lum<215&&(
          r>g*1.18&&r>b*1.18 ||
          b>r*1.16&&b>g*1.12 ||
          r>150&&g>82&&g<178&&b<92 ||
          r>170&&g>150&&b>120
        );
        const hardShadowOrEdge=lum>18&&lum<118&&chroma>18;
        if(darkMass||brightObject||saturatedObject||realWorldColourCue||hardShadowOrEdge)hits++;
      }catch(e){}
    }
  }
  if(!total)return 0;
  const avg=lumSum/total;
  const variance=Math.max(0,lumSq/total-avg*avg);
  const localContrast=Math.sqrt(variance);
  const colourAvg={r:rSum/total,g:gSum/total,b:bSum/total};
  const colourChroma=Math.max(colourAvg.r,colourAvg.g,colourAvg.b)-Math.min(colourAvg.r,colourAvg.g,colourAvg.b);
  const colourCueBoost=colourChroma>42?.16:0;
  return Math.min(1,hits/total+(localContrast>24?.18:0)+colourCueBoost);
}
function gdAimPixelIsSignificant(r,g,b,a){
  if(a<20)return false;
  const max=Math.max(r,g,b),min=Math.min(r,g,b),lum=(r+g+b)/3,chroma=max-min;
  const darkMass=lum>16&&lum<96&&chroma>8;
  const brightObject=lum>138&&chroma>10;
  const saturatedObject=chroma>34&&lum>28&&lum<178;
  const realWorldColourCue=chroma>48&&lum>42&&lum<215&&(
    r>g*1.18&&r>b*1.18 ||
    b>r*1.16&&b>g*1.12 ||
    r>150&&g>82&&g<178&&b<92 ||
    r>170&&g>150&&b>120
  );
  const hardShadowOrEdge=lum>18&&lum<118&&chroma>18;
  return darkMass||brightObject||saturatedObject||realWorldColourCue||hardShadowOrEdge;
}
function gdAimTriggerPixels(ctx,x,y,ux,uy){
  const pts=[];
  const perp={x:-uy,y:ux};
  [-6,-3,0,3,6].forEach(side=>{
    [-6,-2,2,6].forEach(along=>{
      const px=x+perp.x*side+ux*along;
      const py=y+perp.y*side+uy*along;
      try{
        const p=ctx.getImageData(Math.round(px),Math.round(py),1,1).data;
        if(gdAimPixelIsSignificant(p[0],p[1],p[2],p[3]))pts.push(L.point(px,py));
      }catch(e){}
    });
  });
  return pts.slice(0,14);
}
function gdAimLineFallbackEnd(distance,payloadInput=null,lineTarget=target){
  if(!start||!lineTarget)return lineTarget||target;
  const shotBrg=bearing(start,lineTarget);
  const payload=payloadInput?gdBubblePayloadForRender(payloadInput):null;
  const bubbleDepth=payload?Math.max(
    gdFiniteNumber(payload.radius,0),
    gdFiniteNumber(payload.depthRadiusM,0),
    gdFiniteNumber(payload.lateralRadiusM,0),
    Math.abs(gdFiniteNumber(payload.aimOffsetM,0))
  ):0;
  try{
    const size=map.getSize();
    const p0=map.latLngToContainerPoint(lineTarget);
    const p1=map.latLngToContainerPoint(project(lineTarget,shotBrg,20));
    const dx=p1.x-p0.x,dy=p1.y-p0.y,len=Math.hypot(dx,dy)||1;
    const ux=dx/len,uy=dy/len;
    const limits=[
      ux>0?(size.x-p0.x)/ux:Infinity,
      ux<0?(0-p0.x)/ux:Infinity,
      uy>0?(size.y-p0.y)/uy:Infinity,
      uy<0?(0-p0.y)/uy:Infinity
    ].filter(n=>Number.isFinite(n)&&n>0);
    if(limits.length){
      const t=Math.max(40,Math.min(...limits)-8);
      return map.containerPointToLatLng(L.point(p0.x+ux*t,p0.y+uy*t));
    }
  }catch(e){}
  return project(lineTarget,shotBrg,Math.max(180,distance*1.25,bubbleDepth+90));
}
function gdClearAimPixelGlows(){
  if(aimPixelGlows&&aimPixelGlows.length)aimPixelGlows.forEach(layer=>{try{map.removeLayer(layer)}catch(e){}});
  aimPixelGlows=[];
}
function gdClearAimLine(){
  try{if(aimLine)map.removeLayer(aimLine)}catch(e){}
  aimLine=null;
  gdAimLineRenderKey="";
  gdClearAimPixelGlows();
}
function gdRenderAimPixelGlows(points){
  gdClearAimPixelGlows();
  if(!Array.isArray(points)||!points.length)return null;
  try{
    const xs=points.map(p=>p.x).filter(Number.isFinite);
    const ys=points.map(p=>p.y).filter(Number.isFinite);
    if(!xs.length||!ys.length)return null;
    const minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);
    const cx=(minX+maxX)/2,cy=(minY+maxY)/2;
    const rx=Math.max(18,(maxX-minX)/2+14);
    const ry=Math.max(14,(maxY-minY)/2+12);
    let ux=1,uy=0;
    try{
      const lineTarget=typeof gdShotDisplayTarget==="function"&&gdShotDisplayTarget()?gdShotDisplayTarget():target;
      const shotBrg=bearing(start,lineTarget);
      const p0=map.latLngToContainerPoint(lineTarget);
      const p1=map.latLngToContainerPoint(project(lineTarget,shotBrg,20));
      const dx=p1.x-p0.x,dy=p1.y-p0.y,len=Math.hypot(dx,dy)||1;
      ux=dx/len;uy=dy/len;
    }catch(e){}
    const perp={x:-uy,y:ux};
    const layout=[
      [-.72,-.44],[-.68,-.12],[-.66,.22],[-.58,.48],
      [-.45,-.32],[-.42,.04],[-.38,.34],
      [-.26,-.50],[-.22,-.18],[-.18,.16],[-.14,.42],
      [-.04,-.28],[-.02,.06]
    ];
    const flecks=layout.map(([along,side])=>L.point(
      cx+ux*rx*along+perp.x*ry*side,
      cy+uy*rx*along+perp.y*ry*side
    ));
    const arcExtent=Math.PI*.62;
    const arcSteps=14;
    const arcAngles=[];
    for(let i=0;i<=arcSteps;i++)arcAngles.push(Math.PI-arcExtent/2+(arcExtent*i/arcSteps));
    const arcPoints=arcAngles.map(a=>L.point(
      cx+ux*rx*Math.cos(a)+perp.x*ry*Math.sin(a),
      cy+uy*rx*Math.cos(a)+perp.y*ry*Math.sin(a)
    ));
    const arcBase=arcPoints[Math.floor(arcPoints.length/2)];
    for(let i=0;i<arcPoints.length-1;i++){
      const mid=(i+.5)/(arcPoints.length-1);
      const centreFalloff=1-Math.min(1,Math.abs(mid-.5)*2);
      const opacity=.06+centreFalloff*.26;
      aimPixelGlows.push(L.polyline([
        map.containerPointToLatLng(arcPoints[i]),
        map.containerPointToLatLng(arcPoints[i+1])
      ],{
        interactive:false,
        bubblingMouseEvents:false,
        color:"#f4fbff",
        weight:1.4,
        opacity,
        lineCap:"round",
        lineJoin:"round"
      }).addTo(map));
    }
    flecks.forEach((point,index)=>{
      aimPixelGlows.push(L.marker(map.containerPointToLatLng(point),{
        interactive:false,
        keyboard:false,
        icon:L.divIcon({
          className:"",
          html:`<div class="gdAimRecognitionFleck" style="opacity:${Math.max(.16,.28-(index%6)*.018)};width:${index%4===0?5:4}px;height:${index%4===0?5:4}px"></div>`,
          iconSize:[6,6],
          iconAnchor:[3,3]
        })
      }).addTo(map));
    });
    return map.containerPointToLatLng(arcBase);
  }catch(e){}
  return null;
}
function gdAimLineEndPoint(distance,payloadInput=null){
  if(!start||!target)return target;
  const lineTarget=typeof gdShotDisplayTarget==="function"&&gdShotDisplayTarget()?gdShotDisplayTarget():target;
  return gdAimLineFallbackEnd(distance,payloadInput,lineTarget);
}
function gdRenderAimLine(distance,payloadInput=null){
  if(!showAim||!start||!target){gdClearAimLine();return;}
  const end=gdAimLineEndPoint(distance,payloadInput);
  if(!end){gdClearAimLine();return;}
  const key=[start.lat,start.lng,end.lat,end.lng].map(n=>Number(n).toFixed(7)).join("|");
  if(aimLine){
    if(gdAimLineRenderKey!==key)aimLine.setLatLngs([start,end]);
  }else{
    aimLine=L.polyline([start,end],{
      color:"#fff",
      weight:3.25,
      opacity:.78,
      dashArray:"8,10",
      lineCap:"round",
      lineJoin:"round",
      interactive:false,
      bubblingMouseEvents:false
    }).addTo(map);
  }
  gdAimLineRenderKey=key;
  try{aimLine.bringToFront();}catch(e){}
}
function gdClearMiddleDistanceGuide(){
  [middleGuideLine,middleGuideLabel].forEach(l=>{try{if(l)map.removeLayer(l)}catch(e){}});
  middleGuideLine=middleGuideLabel=null;
}
function gdMiddleGuideAnchor(payloadInput=null){
  return gdBubbleRenderCenter(payloadInput)||gdShotDisplayTarget()||target;
}
function gdShouldShowMiddleDistanceGuide(payloadInput=null){
  if(!start||!target||!greenCentre||!map)return false;
  if(typeof gdTournamentModeEnabled==="function"&&gdTournamentModeEnabled())return false;
  if(!gdHasPlayableBag())return false;
  const anchor=gdMiddleGuideAnchor(payloadInput);
  if(!anchor)return false;
  const maxCarry=gdMaxPlayableCarryM();
  if(!(maxCarry>0))return false;
  const raw=map.distance(start,greenCentre);
  const playable=map.distance(start,anchor);
  const targetGap=map.distance(anchor,greenCentre);
  return raw>maxCarry+3&&targetGap>4&&raw>playable+4;
}
function gdMiddleGuideLabelPosition(payloadInput=null){
  try{
    const anchor=gdMiddleGuideAnchor(payloadInput);
    if(!anchor)return greenCentre;
    const a=map.latLngToLayerPoint(anchor);
    const b=map.latLngToLayerPoint(greenCentre);
    const dx=b.x-a.x,dy=b.y-a.y,len=Math.hypot(dx,dy)||1;
    const t=.52;
    const side=18;
    const px=L.point(a.x+dx*t+(-dy/len)*side,a.y+dy*t+(dx/len)*side);
    return map.layerPointToLatLng(px);
  }catch(e){return greenCentre}
}
function gdMiddleGuidePath(payloadInput=null){
  try{
    const anchor=gdMiddleGuideAnchor(payloadInput);
    if(!anchor)return [start,greenCentre];
    const a=map.latLngToLayerPoint(anchor);
    const b=map.latLngToLayerPoint(greenCentre);
    const dx=b.x-a.x,dy=b.y-a.y,len=Math.hypot(dx,dy)||1;
    const trim=Math.min(10,len*.05);
    const ux=dx/len,uy=dy/len;
    return [
      map.layerPointToLatLng(L.point(a.x+ux*trim,a.y+uy*trim)),
      map.layerPointToLatLng(L.point(b.x-ux*trim,b.y-uy*trim))
    ];
  }catch(e){return [start,greenCentre]}
}
function gdRenderMiddleDistanceGuide(payloadInput=null){
  gdClearMiddleDistanceGuide();
  if(!gdShouldShowMiddleDistanceGuide(payloadInput))return;
  const anchor=gdMiddleGuideAnchor(payloadInput);
  const remaining=anchor&&greenCentre?fmt(map.distance(anchor,greenCentre)):null;
  middleGuideLine=L.polyline(gdMiddleGuidePath(payloadInput),{
    color:"#fff",
    weight:1.45,
    opacity:.34,
    dashArray:"1,9",
    lineCap:"round",
    lineJoin:"round",
    interactive:false,
    bubblingMouseEvents:false
  }).addTo(map);
  try{middleGuideLine.bringToBack();}catch(e){}
  middleGuideLabel=L.marker(gdMiddleGuideLabelPosition(payloadInput),{
    interactive:false,
    keyboard:false,
    icon:L.divIcon({
      className:"",
      html:`<div class="gdMiddleGuideLabel">${remaining?`Green ${remaining.value}${remaining.unit}`:"Green"}</div>`,
      iconSize:[84,18],
      iconAnchor:[42,9]
    })
  }).addTo(map);
}

function gdMappedStartPromptActiveForShot(){
  try{return !!(document.body&&document.body.classList.contains("gdMappedStartPromptActive"));}catch(e){return false}
}
function gdSuppressShotForMappedStartPrompt(){
  if(!gdMappedStartPromptActiveForShot())return false;
  try{clearShot({preserveAimLine:false});}catch(e){}
  try{gdResetShotDistanceDisplay();}catch(e){}
  try{document.getElementById("shotTile")?.classList.remove("visible");}catch(e){}
  try{if(typeof window.gdClearCapturedHoleFrameShotOverlay==="function")window.gdClearCapturedHoleFrameShotOverlay();}catch(e){}
  return true;
}
window.gdSuppressShotForMappedStartPrompt=gdSuppressShotForMappedStartPrompt;
function gdSuppressUnlockedGpsShotRender(){
  try{
    const gpsSurface=!!(document.body&&(document.body.classList.contains("gdGpsActive")||document.body.classList.contains("gps-active")||document.body.classList.contains("shell-gps")));
    if(!gpsSurface||lockedFrame||document.body.classList.contains("gdGreenArrivalMode"))return false;
    clearShot({preserveAimLine:false});
    gdResetShotDistanceDisplay();
    document.getElementById("shotTile")?.classList.remove("visible");
    if(typeof window.gdClearCapturedHoleFrameShotOverlay==="function")window.gdClearCapturedHoleFrameShotOverlay();
    return true;
  }catch(e){
    return false;
  }
}
window.gdSuppressUnlockedGpsShotRender=gdSuppressUnlockedGpsShotRender;

function renderShot(){
  if(gdSuppressShotForMappedStartPrompt())return;
  if(gdSuppressUnlockedGpsShotRender())return;
  if((mode==="start"||mode==="green")&&(target||greenCentre||targetMarker||greenMarker||pinMarker||pinDirectionLine||greenOutline||greenSoft||greenLabel||frontLabel||backLabel)){
    clearShot();
    clearPendingGreenTarget();
    gdResetShotDistanceDisplay();
    if(mode==="green")showHint(gdMappedCourseAssistActive()?"Tap where you are standing":"Tap green centre");
    return;
  }
  if(!start||!target){clearShot();gdResetShotDistanceDisplay();return;}
  if(typeof gdTournamentModeEnabled==="function"&&gdTournamentModeEnabled()&&typeof gdRenderTournamentShot==="function"){
    clearShot();
    gdRenderTournamentShot();
    return;
  }
  if(gdHasWindVector()&&!gdWindLandingTarget)gdSyncWindLandingFromAim();
  const displayTarget=gdShotDisplayTarget();
  if(!displayTarget){clearShot();gdResetShotDistanceDisplay();return;}
  if(targetMarker&&displayTarget)targetMarker.setLatLng(displayTarget);
  const d=map.distance(start,displayTarget);
  if(!Number.isFinite(d)||d<=0){clearShot();gdResetShotDistanceDisplay();return;}
  const shot=calculateShot(d);
  const rawGdb=getGpsBubblePayload(d);
  const bubbleCenter=gdBubbleRenderCenter(rawGdb)||displayTarget||target;
  const bubbleCenterDistance=map.distance(start,bubbleCenter);
  if(!Number.isFinite(bubbleCenterDistance)||bubbleCenterDistance<=0){clearShot();gdResetShotDistanceDisplay();return;}
  const gdb=gdGpsBubbleDisplayPayload(rawGdb,d,bubbleCenter);
  clearShot({preserveAimLine:showAim});
  gdSyncBubbleDragHitArea(gdb);
  const fd=fmt(bubbleCenterDistance);
  const carryDistance=fmt(Math.max(0,gdFiniteNumber(gdb.baseCarry,0)));
  const fb=fmt(gdb.radius);
  const clubLabel=gdb.club||shot.club||"GPS";
  const aimOffset=Number(gdb.aimOffsetM);
  const aimText=Number.isFinite(aimOffset)&&Math.abs(aimOffset)>=0.5
    ?`Aim offset ${aimOffset>0?"+":""}${Math.round(aimOffset)}m`
    :"Aim at centre";
  const tile=document.getElementById("shotTile");
  const labelEl=tile?tile.querySelector(".tileLabel"):null;
  const clubEl=tile?tile.querySelector(".tileClub"):null;
  const tileSub=document.getElementById("tileSub");
  const tileMeta=document.getElementById("tileMeta");
  const tileBack=document.getElementById("tileBack");
  const tileFront=document.getElementById("tileFront");
  const tilePlays=document.getElementById("tilePlays");
  const readyBag=gdHasUsableBag();
  const playableBag=typeof gdHasPlayableBag==="function"?gdHasPlayableBag():readyBag;
  const isLayup=!!(greenCentre&&target&&gdIsLayupTarget(greenCentre,target));
  if(tile){
    tile.classList.toggle("noBag",!readyBag);
    tile.classList.toggle("ghostBag",!readyBag&&playableBag);
  }
  if(labelEl)labelEl.textContent="";
  if(clubEl){
    if(readyBag)clubEl.innerHTML=gdShotMetricHtml("Club",{value:gdShotDisplayClubLabel(clubLabel),unit:""});
    else clubEl.innerHTML=gdShotBagIconHtml();
  }
  const edgeMetrics=isLayup?null:gdShotGreenEdgeMetrics();
  const slopeData=isLayup?null:gdSlopeAdjustedDistanceData(start,bubbleCenter,bubbleCenterDistance);
  const pinDiffMetric=gdShotPinDiffData();
  if(tileBack)tileBack.innerHTML=isLayup?"":gdShotMetricHtml("Back",edgeMetrics?edgeMetrics.back:null);
  if(tileFront)tileFront.innerHTML=isLayup?"":gdShotMetricHtml("Front",edgeMetrics?edgeMetrics.front:null);
  gdRenderShotCardSlope(tilePlays,slopeData);
  const tileDist=document.getElementById("tileDist");
  if(tileDist){
    tileDist.classList.remove("slopeOver","slopeUnder","slopeLevel");
    tileDist.innerHTML=gdShotDistanceStackHtml(fd,carryDistance);
  }
  const clubComparisonDistance=gdShotClubComparisonDistance(bubbleCenterDistance);
  const totalDelta=readyBag?gdShotTotalDeltaData(gdb,clubComparisonDistance):null;
  if(tileSub){
    tileSub.innerHTML=pinDiffMetric
      ? gdShotMetricHtml("Pin diff",pinDiffMetric,{valueClass:"tileSmallValue"})
      : gdShotMetricHtml("Stock",totalDelta?{value:`${totalDelta.sign}${totalDelta.value}`,unit:totalDelta.unit}:null,{valueClass:"tileSmallValue"});
    tileSub.classList.toggle("tileStockMetric",!pinDiffMetric);
    tileSub.classList.toggle("tileFlagMetric",!!pinDiffMetric);
  }
  if(tileMeta){
    tileMeta.innerHTML="";
  }
  if(bubbleTexture&&bubbleTexture.length){bubbleTexture.forEach(l=>l&&map.removeLayer(l));bubbleTexture=[];}
  if(bubbleShadow){map.removeLayer(bubbleShadow);bubbleShadow=null;}
  if(bubbleShade){map.removeLayer(bubbleShade);bubbleShade=null;}
  if(bubbleRenderMode==="classic"){
    bubbleOuter=L.circle(bubbleCenter,{radius:gdb.radius*1.28,color:"#fff",weight:1,opacity:.22,fillColor:"#fff",fillOpacity:.022,interactive:false}).addTo(map);
    bubbleMain=L.circle(bubbleCenter,{radius:gdb.radius,color:"#fff",weight:2.5,opacity:dev("bubbleVisuals.classicOutlineOpacity"),fillColor:"#fff",fillOpacity:dev("bubbleVisuals.classicFillOpacity"),interactive:false}).addTo(map);
    bubbleCore=L.circle(bubbleCenter,{radius:Math.max(2.8,gdb.radius*.22),color:"#fff",weight:1.2,opacity:.78,fillColor:"#fff",fillOpacity:.12,interactive:false}).addTo(map);
  }else{
    renderCustomBubble(gdb);
  }
  gdRenderMiddleDistanceGuide(gdb);
  gdRenderMappedLayupReference(gdb);
  gdRenderAimLine(d,gdb);
  gdRenderCarryLandingLine(gdb);
  gdRenderWindEffect();
  clearRemainingGreenLine();
  updatePinLine();
  gdUpdateGpsFocusModeLayer(gdb);
  try{if(typeof window.gdRenderCapturedHoleFrameShotOverlay==="function")window.gdRenderCapturedHoleFrameShotOverlay(gdb,bubbleCenter);}catch(e){}
  app.classList.toggle("framed",showFilter&&lockedFrame);
}
function clearShot(options={}){
  const preserveAimLine=!!(options&&options.preserveAimLine);
  if(!preserveAimLine)gdClearAimLine();
  [pinLine,pinLabel,remainingGreenLine,remainingGreenLabel,middleGuideLine,middleGuideLabel,bubbleOuter,bubbleMain,bubbleCore,bubbleMiss,bubbleShadow,bubbleShade,bubbleCarryLine].forEach(l=>l&&map.removeLayer(l));
  gdClearGpsFocusModeLayer();gdClearWindVisuals();gdClearMappedLayupReference();if(bubbleTexture&&bubbleTexture.length){bubbleTexture.forEach(l=>l&&map.removeLayer(l));}bubbleTexture=[];pinLine=pinLabel=remainingGreenLine=remainingGreenLabel=middleGuideLine=middleGuideLabel=bubbleOuter=bubbleMain=bubbleCore=bubbleMiss=bubbleShadow=bubbleShade=bubbleCarryLine=null
  try{if(typeof window.gdClearCapturedHoleFrameShotOverlay==="function")window.gdClearCapturedHoleFrameShotOverlay();}catch(e){}
}

