/* ---------------- Flag ---------------- */
/* Flag/pin placement carved out to scripts/gd-flag-pin.js (Phase B, 2026-07-19).
   That module loads immediately after this file and declares placingPin,
   cancelPinPlacement, finishPinPlacement etc. in the shared global scope. */
let gdPinDragState=null;
const GD_PIN_LONG_PRESS_MS=650;
const GD_PIN_LONG_PRESS_CANCEL_PX=9;
function gdHasPlacedPin(){try{return !!(pin||pinMarker)}catch(e){return false}}
function gdClearPlacedPin(message){
  if(typeof gdUndoPinOnly==="function"){gdUndoPinOnly(message||"Pin cleared");return}
  try{
    pin=null;
    if(pinMarker&&map)map.removeLayer(pinMarker);
    pinMarker=null;
    if(pinLine&&map)map.removeLayer(pinLine);
    if(pinLabel&&map)map.removeLayer(pinLabel);
    pinLine=pinLabel=null;
    if(typeof renderShot==="function")renderShot();
    if(typeof updatePinLine==="function")updatePinLine();
    if(typeof toast==="function")toast(message||"Pin cleared");
  }catch(e){}
}
function gdOpenPinLockStart(){
  if(typeof window.gdOpenPinLockSheet==="function"){window.gdOpenPinLockSheet();return true}
  if(typeof window.gdTogglePinToolFlyout==="function"){window.gdTogglePinToolFlyout(null);return true}
  return false;
}
function gdClearPinAndOpenPinLock(message){
  if(gdHasPlacedPin())gdClearPlacedPin(message||"Pin cleared");
  setTimeout(()=>{if(!gdOpenPinLockStart())try{toast(message||"Pin cleared")}catch(e){}},30);
}
function gdInstallPinDrag(marker){
  if(!marker||marker.__gdPinDragInstalled)return;
  marker.__gdPinDragInstalled=true;
  const install=()=>{
    const el=marker.getElement&&marker.getElement();
    if(!el||el.__gdPinDragBound)return;
    el.__gdPinDragBound=true;
    el.style.touchAction="none";
    el.style.cursor="default";
    el.addEventListener("pointerdown",ev=>{
      if(ev.button!=null&&ev.button!==0)return;
      ev.preventDefault();
      ev.stopPropagation();
      const press={
        pointerId:ev.pointerId,
        startX:ev.clientX,
        startY:ev.clientY,
        longPressed:false,
        timer:null,
        cancelled:false
      };
      try{el.setPointerCapture(ev.pointerId);}catch(e){}
      el.classList.add("gdPinLongPressArmed");
      gdPinDragState={
        pointerId:ev.pointerId,
        startX:ev.clientX,
        startY:ev.clientY,
        offset:L.point(0,0),
        pending:null,
        raf:null,
        pushedUndo:false,
        startPin:pin?L.latLng(pin.lat,pin.lng):null,
        hadMapDragging:false,
        unlocked:false,
        press
      };
      const unlockDrag=()=>{
        if(!gdPinDragState||gdPinDragState.pointerId!==press.pointerId||press.cancelled)return;
        const pointerPoint=gdClientToMapContainerPoint(press.startX,press.startY);
        const markerPoint=pin?map.latLngToContainerPoint(pin):map.latLngToContainerPoint(marker.getLatLng());
        gdPinDragState.offset=pointerPoint?L.point(pointerPoint.x-markerPoint.x,pointerPoint.y-markerPoint.y):L.point(0,0);
        gdPinDragState.hadMapDragging=!!(map.dragging&&map.dragging.enabled&&map.dragging.enabled());
        if(gdPinDragState.hadMapDragging)map.dragging.disable();
        gdPinDragState.unlocked=true;
        press.longPressed=true;
        el.classList.remove("gdPinLongPressArmed");
        el.classList.add("gdPinDragUnlocked");
        el.style.cursor="grabbing";
        try{if(typeof haptic==="function")haptic(18)}catch(e){}
        try{toast("Pin unlocked")}catch(e){}
      };
      press.timer=setTimeout(unlockDrag,GD_PIN_LONG_PRESS_MS);
      const pointToLatLng=moveEv=>{
        if(!moveEv||!Number.isFinite(moveEv.clientX)||!Number.isFinite(moveEv.clientY))return null;
        const p=gdClientToMapContainerPoint(moveEv.clientX,moveEv.clientY);
        if(!p)return null;
        const o=gdPinDragState?.offset||L.point(0,0);
        if(!Number.isFinite(p.x)||!Number.isFinite(p.y)||!Number.isFinite(o.x)||!Number.isFinite(o.y))return null;
        return map.containerPointToLatLng(L.point(p.x-o.x,p.y-o.y));
      };
      const pushUndoOnce=()=>{
        if(!gdPinDragState||gdPinDragState.pushedUndo)return;
        undoStack.push({type:"pin",value:gdPinDragState.startPin});
        gdPinDragState.pushedUndo=true;
      };
      const queue=ll=>{
        if(!gdPinDragState||!ll)return;
        gdPinDragState.pending=ll;
        if(gdPinDragState.raf)return;
        gdPinDragState.raf=requestAnimationFrame(()=>{
          if(!gdPinDragState)return;
          const next=gdPinDragState.pending;
          gdPinDragState.pending=null;
          gdPinDragState.raf=null;
          if(!next)return;
          pin=next;
          marker.setLatLng(pin);
          renderShot();
          updatePinLine();
        });
      };
      const move=moveEv=>{
        if(!gdPinDragState||moveEv.pointerId!==gdPinDragState.pointerId)return;
        moveEv.preventDefault();
        moveEv.stopPropagation();
        if(!gdPinDragState.unlocked){
          if(Math.hypot(moveEv.clientX-gdPinDragState.startX,moveEv.clientY-gdPinDragState.startY)>GD_PIN_LONG_PRESS_CANCEL_PX){
            press.cancelled=true;
            clearTimeout(press.timer);
            el.classList.remove("gdPinLongPressArmed");
          }
          return;
        }
        if(Math.hypot(moveEv.clientX-gdPinDragState.startX,moveEv.clientY-gdPinDragState.startY)>3)pushUndoOnce();
        queue(pointToLatLng(moveEv));
      };
      const end=endEv=>{
        if(gdPinDragState&&endEv.pointerId!==gdPinDragState.pointerId)return;
        endEv.preventDefault();
        endEv.stopPropagation();
        clearTimeout(press.timer);
        document.removeEventListener("pointermove",move);
        document.removeEventListener("pointerup",end);
        document.removeEventListener("pointercancel",end);
        el.classList.remove("gdPinLongPressArmed","gdPinDragUnlocked");
        if(gdPinDragState&&gdPinDragState.raf)cancelAnimationFrame(gdPinDragState.raf);
        const finalLl=pointToLatLng(endEv);
        const unlocked=!!gdPinDragState?.unlocked;
        const hasEndPoint=Number.isFinite(endEv.clientX)&&Number.isFinite(endEv.clientY);
        const drift=(gdPinDragState&&hasEndPoint)?Math.hypot(endEv.clientX-gdPinDragState.startX,endEv.clientY-gdPinDragState.startY):0;
        const moved=unlocked&&gdPinDragState&&drift>3;
        const attemptedMove=press.cancelled||drift>GD_PIN_LONG_PRESS_CANCEL_PX||endEv.type==="pointercancel";
        if(moved)pushUndoOnce();
        const restoreDragging=gdPinDragState?.hadMapDragging;
        if(finalLl&&moved){
          pin=finalLl;
          marker.setLatLng(pin);
        }
        gdPinDragState=null;
        if(restoreDragging)map.dragging.enable();
        el.style.cursor="default";
        if(unlocked){
          renderShot();
          updatePinLine();
        }else if(!attemptedMove){
          gdClearPinAndOpenPinLock("Pin cleared");
        }else{
          try{toast("Hold pin to move")}catch(e){}
        }
        try{el.releasePointerCapture(endEv.pointerId);}catch(e){}
      };
      document.addEventListener("pointermove",move,{passive:false});
      document.addEventListener("pointerup",end,{passive:false});
      document.addEventListener("pointercancel",end,{passive:false});
    },{passive:false});
  };
  marker.on("add",()=>requestAnimationFrame(install));
  requestAnimationFrame(install);
}
function placePin(ll){undoStack.push({type:"pin",value:pin});pin=ll;if(!pinMarker){pinMarker=L.marker(pin,{icon:pinIcon,draggable:false,autoPan:false}).addTo(map);gdInstallPinDrag(pinMarker);}else{pinMarker.setLatLng(pin);gdInstallPinDrag(pinMarker);}renderShot();updatePinLine()}
function updatePinLine(){[pinLine,pinLabel].forEach(l=>l&&map.removeLayer(l));pinLine=pinLabel=null;const el=document.getElementById("pinDiff");if(el)el.style.display="none";if(typeof gdTournamentModeEnabled==="function"&&gdTournamentModeEnabled()){return;}const bubbleTarget=gdShotDisplayTarget();const diff=gdShotPinDiffData();if(!pin||!bubbleTarget||!diff)return;if(el){el.classList.add("tilePinMetric");el.textContent=`Pin diff ${diff.value}${diff.unit}`;el.style.display="block";}pinLine=L.polyline([bubbleTarget,pin],{color:"#fff",weight:2,opacity:.52,dashArray:"3,7"}).addTo(map)}


/* Standalone Wand UI retired. Green Shape Engine ownership lives in scripts/gd-green-shape-engine.js. */

function drawGreenPolygon(pts,label,opts={}){
  [greenOutline,greenSoft,greenLabel,frontLabel,backLabel].forEach(l=>l&&map.removeLayer(l));
  greenPolygon=pts;
  const settled=!!(opts.settled||opts.saved||/saved|accepted/i.test(String(label||"")));

  greenSoft=L.polygon(pts,{
    color:"#1fd36d",
    weight:.6,
    opacity:settled?.08:.12,
    fillColor:"#1fd36d",
    fillOpacity:settled?.006:.012,
    interactive:false,
    className:"gdSubtleGreenSoft"
  }).addTo(map);

  greenOutline=L.polygon(pts,{
    color:"#1fd36d",
    weight:.75,
    opacity:settled?.16:.22,
    fillColor:"#1fd36d",
    fillOpacity:settled?.004:.01,
    interactive:true,
    className:"gdSubtleGreenOutline"
  }).addTo(map);

  if(!settled&&label){
    const northBase=greenCentre||target||pts[0];
    const north=project(northBase,0,18);
    greenLabel=L.marker(north,{
      interactive:false,
      icon:L.divIcon({
        className:"",
        html:`<div class="greenLabel">${label}</div>`,
        iconSize:[92,22],
        iconAnchor:[46,11]
      })
    }).addTo(map);
  }else{
    greenLabel=null;
  }

  drawGreenDistances(pts);
  renderShot();
}

function drawGreenDistances(pts){
  [frontLabel,backLabel].forEach(l=>l&&map.removeLayer(l));
  frontLabel=backLabel=null;
  if(!start||!pts||!pts.length)return;

  const startPt=map.latLngToLayerPoint(start);
  const centre=greenCentre||target||pts[0];
  const centrePt=map.latLngToLayerPoint(centre);
  let ax=centrePt.x-startPt.x;
  let ay=centrePt.y-startPt.y;
  const axisLen=Math.hypot(ax,ay)||1;
  ax/=axisLen;
  ay/=axisLen;
  const px=-ay;
  const py=ax;
  const outline=pts.map(p=>{
    const point=map.latLngToLayerPoint(p);
    const s=(point.x-centrePt.x)*ax+(point.y-centrePt.y)*ay;
    return {latlng:p,point,s,d:map.distance(start,p)};
  });

  let front=outline[0],back=outline[0],fd=Infinity,bd=-Infinity,minS=Infinity,maxS=-Infinity;
  outline.forEach(item=>{
    if(item.d<fd){fd=item.d;front=item}
    if(item.d>bd){bd=item.d;back=item}
    if(item.s<minS)minS=item.s;
    if(item.s>maxS)maxS=item.s;
  });

  const span=Math.max(1,maxS-minS);
  const band=Math.max(10,span*.18);
  const averageEdgePoint=(items,fallback)=>{
    if(!items.length)return fallback.point;
    const sum=items.reduce((acc,item)=>{acc.x+=item.point.x;acc.y+=item.point.y;return acc},{x:0,y:0});
    return L.point(sum.x/items.length,sum.y/items.length);
  };
  const frontEdge=averageEdgePoint(outline.filter(item=>item.s<=minS+band),front);
  const backEdge=averageEdgePoint(outline.filter(item=>item.s>=maxS-band),back);
  const labelOutset=Math.max(8,Math.min(16,span*.13));
  const frontPos=map.layerPointToLatLng(L.point(frontEdge.x-ax*labelOutset,frontEdge.y-ay*labelOutset));
  const backPos=map.layerPointToLatLng(L.point(backEdge.x+ax*labelOutset,backEdge.y+ay*labelOutset));
  const rotDeg=Math.atan2(py,px)*180/Math.PI;

  if(front){
    const v=fmt(fd);
    frontLabel=L.marker(frontPos,{
      interactive:false,
      icon:L.divIcon({
        className:"",
        html:`<div class="yardLabel edgeLabel" style="--label-rot:${rotDeg}deg">Front ${v.value}${v.unit}</div>`,
        iconSize:[70,16],
        iconAnchor:[35,8]
      })
    }).addTo(map);
  }

  if(back){
    const v=fmt(bd);
    backLabel=L.marker(backPos,{
      interactive:false,
      icon:L.divIcon({
        className:"",
        html:`<div class="yardLabel edgeLabel" style="--label-rot:${rotDeg}deg">Back ${v.value}${v.unit}</div>`,
        iconSize:[70,16],
        iconAnchor:[35,8]
      })
    }).addTo(map);
  }
}

