function gdPanelBack(id){
  const el=document.getElementById(id);
  const panelReturn=el?.dataset?.gdReturnTarget||"";
  if(el)el.classList.remove("open");
  if(id==="statsPanel")document.body.classList.remove("gdStatsOpen","gdShotDataOpen");
  if(panelReturn==="gps"&&typeof enterGpsModule==="function"){
    if(el)delete el.dataset.gdReturnTarget;
    window.__gdBackTarget="";
    return enterGpsModule({replace:true,preserveState:true,fromBack:true});
  }
  if(panelReturn==="home"&&typeof gdCanonicalShellHome==="function"){
    if(el)delete el.dataset.gdReturnTarget;
    window.__gdBackTarget="";
    return gdCanonicalShellHome();
  }
  if(window.__gdBackTarget==="profile"&&typeof gdReturnToProfileWorkspace==="function")return gdReturnToProfileWorkspace();
  if(id==="statsPanel"&&typeof gdOpenDataHub==="function")return gdOpenDataHub({replace:true});
  const target=window.__gdBackTarget||"";
  if(target==="gps"&&typeof enterGpsModule==="function"){
    window.__gdBackTarget="";
    return enterGpsModule({replace:true,preserveState:true,fromBack:true});
  }
  if(target==="home"&&typeof gdCanonicalShellHome==="function"){
    window.__gdBackTarget="";
    return gdCanonicalShellHome();
  }
  if(typeof gdCanonicalShellBack==="function")return gdCanonicalShellBack();
  if(typeof shellBack==="function")return shellBack();
  if(typeof showShellHome==="function")return showShellHome();
  return false;
}
