function gdCourseDataLandingCounts(analysis, filteredRecords){
  let store={};
  try{store=window.GolfDaddyShotEvents?.getScopedStore?.()||window.GolfDaddyShotEvents?.getStore?.()||{}}catch(e){store={}}
  const records=Array.isArray(analysis?.records)?analysis.records:[];
  const shown=Array.isArray(filteredRecords)?filteredRecords:[];
  return {
    planned:Array.isArray(store.plannedShots)?store.plannedShots.length:0,
    paired:Array.isArray(store.outcomes)?store.outcomes.length:0,
    rawEvents:Array.isArray(store.ballEvents)?store.ballEvents.length:0,
    records:records.length,
    shown:shown.length,
    counted:shown.filter(record=>record&&record.counted).length
  };
}
