var gdPracticeManualStopUntil=Number(window.__gdPracticeManualStopUntil||0)||0;
var gdPracticeImportJob=gdPracticeReadImportJob();
function gdPracticeNowISO(){return new Date().toISOString();}
function gdPracticeReadImportJob(){
  try{
    const raw=localStorage.getItem(GD_PRACTICE_IMPORT_JOB_KEY);
    if(!raw)return null;
    const job=JSON.parse(raw);
    return job&&typeof job==="object"&&job.id?job:null;
  }catch(e){return null;}
}
function gdPracticeWriteImportJob(job){
  gdPracticeImportJob=job||null;
  try{
    if(job)localStorage.setItem(GD_PRACTICE_IMPORT_JOB_KEY,JSON.stringify(job));
    else localStorage.removeItem(GD_PRACTICE_IMPORT_JOB_KEY);
  }catch(e){console.warn("[GolfDaddy] practice import job persistence failed",e);}
  return gdPracticeImportJob;
}
function gdPracticeReleaseStaleImportJob(){
  gdPracticeWriteImportJob(null);
  try{
    gdPracticePhotoProcessing=false;
    gdPracticePhotoProcessingProgress=0;
    gdPracticePhotoProcessingStageIndex=0;
    gdPracticePhotoProcessingCompletedAt=0;
    document.body?.classList.remove("gdPracticePhotoProcessing");
    document.getElementById("practiceDataPanel")?.classList.remove("gdPracticePhotoProcessing");
  }catch(e){}
  return gdPracticeImportJob;
}
function gdPracticeLegacyHeaderAllocationFailureMessage(text){
  const raw=String(text||"");
  if(!/Header allocation only mapped \d+\/\d+ value columns/i.test(raw))return "";
  const match=raw.match(/mapped\s+(\d+)\/(\d+)/i);
  const mapped=match?`${match[1]}/${match[2]}`:"incomplete";
  return `Previous scan stopped before value OCR because mapped value fields were incomplete (${mapped} value columns mapped). Club is handled separately by the club-id pass. Resume/review import and open scan output for per-cutout header reads. Nothing was saved.`;
}
function gdPracticeHydrateImportJob(){
  const stored=gdPracticeReadImportJob();
  if(!stored)return gdPracticeWriteImportJob(null);
  const current=gdPracticeImportJob;
  const storedTime=Date.parse(stored.updatedAt||stored.createdAt||"")||0;
  const currentTime=Date.parse(current?.updatedAt||current?.createdAt||"")||0;
  if(!current||storedTime>=currentTime)gdPracticeImportJob=stored;
  if(String(gdPracticeImportJob?.status||"")==="failed"&&String(gdPracticeImportJob?.diagnostic||"")===GD_PRACTICE_LEGACY_TIMEOUT_DIAGNOSTIC){
    return gdPracticeReleaseStaleImportJob();
  }
  const failedImportText=String(gdPracticeImportJob?.checkpointText||gdPracticeImportJob?.userMessage||gdPracticeImportJob?.diagnostic||"");
  if(String(gdPracticeImportJob?.status||"")==="failed"&&/gdPracticeDebug(?:CheckpointHtml|Metric|FormatMs|RejectedRows) is not defined/i.test(failedImportText)){
    return gdPracticeReleaseStaleImportJob();
  }
  const modernHeaderMessage=String(gdPracticeLegacyHeaderAllocationFailureMessage(failedImportText)||"");
  if(String(gdPracticeImportJob?.status||"")==="failed"&&modernHeaderMessage){
    gdPracticeImportJob=Object.assign({},gdPracticeImportJob,{
      checkpointText:modernHeaderMessage,
      userMessage:modernHeaderMessage,
      diagnostic:String(gdPracticeImportJob?.diagnostic||failedImportText||modernHeaderMessage),
      updatedAt:gdPracticeNowISO()
    });
    gdPracticeWriteImportJob(gdPracticeImportJob);
  }
  return gdPracticeImportJob;
}
function gdPracticeImportActiveStatuses(){return {queued:true,scanning:true,parsing:true,validating:true,saving:true};}
function gdPracticeImportIsActive(job=gdPracticeImportJob){return !!(job&&gdPracticeImportActiveStatuses()[String(job.status||"")]);}
function gdPracticeImportBlocksNew(job=gdPracticeImportJob){return gdPracticeImportIsActive(job);}
function gdPracticeImportJobIsCurrent(jobId){
  if(!jobId)return true;
  const job=gdPracticeHydrateImportJob();
  return !!(job&&String(job.id||"")===String(jobId)&&gdPracticeImportIsActive(job));
}
function gdPracticeStaleImportError(label){
  const error=new Error(`${label||"Practice scan"} stopped before it completed`);
  error.code="GD_PRACTICE_IMPORT_STALE";
  return error;
}
function gdPracticeAssertCurrentImportJob(jobId,label){
  if(!gdPracticeImportJobIsCurrent(jobId))throw gdPracticeStaleImportError(label);
}
function gdPracticeIsQuietScanStop(error){
  return error&&String(error.code||"")==="GD_PRACTICE_IMPORT_STALE";
}
function gdPracticeMarkManualScanStop(ms=7000){
  gdPracticeManualStopUntil=Date.now()+Math.max(1000,Number(ms)||7000);
  window.__gdPracticeManualStopUntil=gdPracticeManualStopUntil;
}
function gdPracticeManualScanStopIsRecent(){
  return Date.now()<Math.max(Number(gdPracticeManualStopUntil)||0,Number(window.__gdPracticeManualStopUntil)||0);
}
function gdPracticePersistStoppedScanFailure(reason=""){
  const message=gdPracticeScanStoppedMessage(reason);
  const existing=gdPracticeHydrateImportJob();
  const base={
    id:existing?.id||`practice-import-${Date.now()}-${Math.random().toString(16).slice(2,8)}`,
    kind:existing?.kind||"practice-photo",
    sourceLabel:existing?.sourceLabel||gdPracticePhotoName||"Practice photo scan",
    source:existing?.source||"photo",
    importDate:existing?.importDate||gdPracticeNowISO(),
    createdAt:existing?.createdAt||gdPracticeNowISO(),
    updatedAt:gdPracticeNowISO(),
    status:"failed",
    checkpointText:message,
    userMessage:message,
    diagnostic:String(reason||message).slice(0,1200),
    progress:100,
    stageIndex:2,
    accepted:Number(existing?.accepted)||0,
    rejected:Number(existing?.rejected)||0,
    rawRows:Number(existing?.rawRows)||0,
    nativeRows:Number(existing?.nativeRows)||0,
    clubs:Array.isArray(existing?.clubs)?existing.clubs:[]
  };
  gdPracticeWriteImportJob(Object.assign({},existing||{},base));
  return message;
}
function gdPracticeScanSurfaceIsActive(){
  return gdPracticeScanProgressIsActive();
}
function gdPracticeScanReentryBlocked(){
  if(!gdPracticeScanSurfaceIsActive())return false;
  try{gdPracticeSyncLibraryProcessingSurface();}catch(e){}
  return true;
}
function gdPracticeScanStoppedMessage(reason=""){
  const text=String(reason||"").trim();
  if(/header|column name|metric/i.test(text)){
    return "Couldn't find headers. Nothing was saved. Keep the header row visible and re-frame the value grid.";
  }
  if(/reading values|cell ocr|ocr|timeout|timed out|exceeded/i.test(text)){
    return "Couldn't read values. Nothing was saved. Try a tighter crop or clearer table photo.";
  }
  return "Scan stopped before values were saved. Try a tighter crop or clearer table photo.";
}
function gdPracticeReleaseStoppedScan(reason=""){
  console.warn("[GolfDaddy] releasing stopped practice scan",reason);
  const manualStop=gdPracticeManualScanStopIsRecent();
  const stoppedMessage=manualStop?gdPracticeScanStoppedMessage(reason):gdPracticePersistStoppedScanFailure(reason);
  if(manualStop)gdPracticeWriteImportJob(null);
  gdPracticePhotoProcessing=false;
  gdPracticePhotoProcessingProgress=0;
  gdPracticePhotoProcessingStageIndex=0;
  gdPracticePhotoProcessingCompletedAt=0;
  try{gdPracticeResetTesseractWorkers(reason);}catch(e){}
  try{
    gdPracticeProcessingStop();
    document.body?.classList.remove("gdPracticeScanRunning");
    document.body?.classList.remove("gdPracticePhotoProcessing");
    document.getElementById("practiceDataPanel")?.classList.remove("gdPracticeScanRunning");
    document.getElementById("practiceDataPanel")?.classList.remove("gdPracticePhotoProcessing");
    gdPracticeClearLibraryProcessingSurface();
    gdPracticeQuietScanSurface({clearStatus:false});
    gdSetPracticeScanStatus(stoppedMessage);
    if(typeof renderPracticeData==="function")renderPracticeData(true);
  }catch(e){}
  return true;
}
function gdPracticeHardStopScan(reason="Manual stop"){
  const message=String(reason||"Manual stop").trim()||"Manual stop";
  gdPracticeMarkManualScanStop();
  const job=gdPracticeHydrateImportJob();
  const activeJob=gdPracticeImportIsActive(job);
  try{
    gdPracticeDebugCheckpointSafe("manual_hard_stop","warning",{
      outputSummary:"Manual hard stop cleared the active practice scan state",
      counts:{activeJob:activeJob?1:0,hadJob:job?1:0},
      raw:{reason:message,jobId:job?.id||"",jobStatus:job?.status||""}
    });
  }catch(e){}
  gdPracticeWriteImportJob(null);
  gdPracticePhotoProcessing=false;
  gdPracticePhotoProcessingProgress=0;
  gdPracticePhotoProcessingStageIndex=0;
  gdPracticePhotoProcessingCompletedAt=0;
  if(gdPracticePhotoProcessingStopTimer){
    clearTimeout(gdPracticePhotoProcessingStopTimer);
    gdPracticePhotoProcessingStopTimer=null;
  }
  try{gdPracticeResetTesseractWorkers(message);}catch(e){}
  try{gdPracticeProcessingStop();}catch(e){}
  try{
    document.body?.classList.remove("gdPracticeScanRunning");
    document.body?.classList.remove("gdPracticePhotoProcessing");
    document.getElementById("practiceDataPanel")?.classList.remove("gdPracticeScanRunning");
    document.getElementById("practiceDataPanel")?.classList.remove("gdPracticePhotoProcessing");
    gdPracticeClearLibraryProcessingSurface();
  }catch(e){}
  try{gdPracticeRecordLiveDebugEvent("manual_stop","Manual scan cleared. You can adjust the box or scan again.",{state:"cleared"});}catch(e){}
  try{gdPracticeDebugFinishSafe("canceled",{dataSaved:false,errorMessage:"Manual scan cleared"});}catch(e){}
  gdPracticeFeedback("Manual scan cleared. You can adjust the box or scan again.","warning");
  try{gdNativePracticeFeedbackBridge({status:"canceled",lastAction:"Manual scan hard-stopped",warnings:["The in-flight scan job and loader were cleared."],errors:[],nextStep:"Adjust the box or scan again."});}catch(e){}
  try{if(typeof gdPracticeSetContinueScanReady==="function")gdPracticeSetContinueScanReady(!!(gdPracticeClusterCheckpoint||window.__gdPracticeClusterCheckpoint));}catch(e){}
  try{if(typeof gdPracticeRefreshDebugTools==="function")gdPracticeRefreshDebugTools();}catch(e){}
  try{if(typeof renderPracticeData==="function")renderPracticeData(true);}catch(e){}
  try{gdLmToast("Practice scan stopped");}catch(e){}
  return false;
}
function gdPracticeReleaseInactiveProcessingSurface(){
  const job=gdPracticeHydrateImportJob();
  if(gdPracticeImportIsActive(job))return false;
  const scanRunning=!!(document.body?.classList.contains("gdPracticeScanRunning")||document.getElementById("practiceDataPanel")?.classList.contains("gdPracticeScanRunning"));
  if(scanRunning){
    if(!gdPracticePhotoProcessingStartedAt||gdPracticeProcessingElapsed()<=GD_PRACTICE_ORPHAN_SCAN_CLASS_GRACE_MS)return false;
    document.body?.classList.remove("gdPracticeScanRunning");
    document.getElementById("practiceDataPanel")?.classList.remove("gdPracticeScanRunning");
  }
  if(gdPracticePhotoProcessing&&gdPracticePhotoProcessingStartedAt&&gdPracticeProcessingElapsed()<=GD_PRACTICE_ORPHAN_PROCESSING_SURFACE_GRACE_MS)return false;
  gdPracticePhotoProcessing=false;
  gdPracticePhotoProcessingProgress=0;
  gdPracticePhotoProcessingStageIndex=0;
  gdPracticePhotoProcessingCompletedAt=0;
  try{
    gdPracticeProcessingStop();
    document.body?.classList.remove("gdPracticePhotoProcessing");
    document.getElementById("practiceDataPanel")?.classList.remove("gdPracticePhotoProcessing");
    gdPracticeClearLibraryProcessingSurface();
  }catch(e){}
  return true;
}
function gdPracticeImportStatusLabel(status){
  return ({
    queued:"Import queued",
    scanning:"Import running in background",
    parsing:"Import running in background",
    validating:"Import running in background",
    saving:"Import saving",
    completed:"Import completed",
    failed:"Import failed - review",
    canceled:"Import canceled"
  })[String(status||"")]||"Import status";
}
function gdPracticeImportCanStart(sourceLabel){
  const job=gdPracticeHydrateImportJob();
  if(!gdPracticeImportBlocksNew(job))gdPracticeReleaseInactiveProcessingSurface();
  if(gdPracticeImportBlocksNew(job)){
    gdLmToast("Practice import already running");
    gdLmSetStatus("Status","Practice import already running",`${job.sourceLabel||sourceLabel||"Current import"} is ${String(job.status||"running")}. Review, cancel, or finish it before starting another.`,"needs_more_data");
    try{if(typeof renderPracticeData==="function")renderPracticeData(true);}catch(e){}
    return false;
  }
  if(String(job?.status||"")==="failed")gdPracticeWriteImportJob(null);
  return true;
}
function gdPracticePayloadClubLabels(payload){
  const groups=Array.isArray(payload?.clubGroups)?payload.clubGroups:[];
  const clubs=groups.map(group=>String(group?.candidateClub||group?.originClubLabel||group?.club||"").trim()).filter(Boolean);
  return [...new Set(clubs)].slice(0,8);
}
function gdPracticeStartImportJob(kind,sourceLabel,details={}){
  if(!gdPracticeImportCanStart(sourceLabel))return null;
  const now=gdPracticeNowISO();
  const job={
    id:`practice-import-${Date.now()}-${Math.random().toString(16).slice(2,8)}`,
    kind:kind||"practice-import",
    sourceLabel:sourceLabel||"Practice import",
    source:details.source||kind||"practice-import",
    importDate:details.importDate||now,
    createdAt:now,
    updatedAt:now,
    status:details.status||"queued",
    checkpointText:details.checkpointText||"Queued",
    progress:Number(details.progress)||4,
    stageIndex:Number(details.stageIndex)||0,
    accepted:Number(details.accepted)||0,
    rejected:Number(details.rejected)||0,
    rawRows:Number(details.rawRows)||0,
    nativeRows:Number(details.nativeRows)||0,
    clubs:Array.isArray(details.clubs)?details.clubs.slice(0,8):[],
    diagnostic:"",
    userMessage:""
  };
  gdPracticeWriteImportJob(job);
  gdPracticeSyncImportProcessing(job);
  return job;
}
function gdPracticeUpdateImportJob(patch={}){
  const current=gdPracticeHydrateImportJob();
  if(!current)return null;
  const next=Object.assign({},current,patch,{updatedAt:gdPracticeNowISO()});
  gdPracticeWriteImportJob(next);
  gdPracticeSyncImportProcessing(next);
  try{if(typeof renderPracticeData==="function")renderPracticeData(true);}catch(e){}
  return next;
}
function gdPracticeFailImportJob(error,userMessage){
  const message=userMessage||error?.message||"Practice import failed";
  const failedJob=gdPracticeUpdateImportJob({
    status:"failed",
    checkpointText:message,
    userMessage:message,
    diagnostic:String(error?.stack||error?.message||error||message).slice(0,1200),
    progress:100
  });
  gdPracticeReleaseFailedImportSurface();
  return failedJob;
}
function gdPracticeReleaseFailedImportSurface(){
  gdPracticePhotoProcessing=false;
  gdPracticePhotoProcessingProgress=0;
  gdPracticePhotoProcessingStageIndex=0;
  gdPracticePhotoProcessingCompletedAt=0;
  if(gdPracticePhotoProcessingStopTimer){
    clearTimeout(gdPracticePhotoProcessingStopTimer);
    gdPracticePhotoProcessingStopTimer=null;
  }
  try{gdPracticeProcessingStop();}catch(e){}
  try{
    document.body?.classList.remove("gdPracticeScanRunning");
    document.body?.classList.remove("gdPracticePhotoProcessing");
    document.getElementById("practiceDataPanel")?.classList.remove("gdPracticeScanRunning");
    document.getElementById("practiceDataPanel")?.classList.remove("gdPracticePhotoProcessing");
    gdPracticeClearLibraryProcessingSurface();
  }catch(e){}
  try{if(typeof renderPracticeData==="function")renderPracticeData(true);}catch(e){}
  return true;
}
function gdPracticeCompleteImportJob(result,payload,extra={}){
  const groups=Array.isArray(payload?.clubGroups)?payload.clubGroups:[];
  const rejected=Array.isArray(payload?.rejectedRows)?payload.rejectedRows.length:0;
  gdPracticePhotoProcessingProgress=100;
  gdPracticePhotoProcessingStageIndex=GD_PRACTICE_PROCESSING_STAGES.length-1;
  gdPracticePhotoProcessingCompletedAt=Date.now();
  return gdPracticeUpdateImportJob({
    status:"completed",
    checkpointText:"Saved to Clarity Shot Library",
    accepted:groups.length||Number(extra.validCount)||0,
    rejected:rejected||Number(extra.invalidCount)||0,
    rawRows:groups.length+rejected||Number(extra.rawRows)||0,
    nativeRows:Array.isArray(result?.shots)?result.shots.length:(Number(extra.nativeRows)||groups.length),
    sessionId:result?.session?.sessionId||extra.sessionId||"",
    captureId:result?.capture?.captureId||extra.captureId||"",
    importBatchId:result?.session?.importBatchId||result?.capture?.importBatchId||extra.importBatchId||payload?.importBatchId||"",
    importDate:result?.capture?.timestamp||payload?.timestamp||extra.importDate||gdPracticeImportJob?.importDate||gdPracticeNowISO(),
    progress:100,
    stageIndex:GD_PRACTICE_PROCESSING_STAGES.length-1
  });
}
function gdPracticeClearImportJob(){
  gdPracticeMarkManualScanStop();
  gdPracticeWriteImportJob(null);
  try{gdPracticeReleaseFailedImportSurface();}catch(e){}
  gdSetPracticePhotoProcessing(false,{immediate:true,skipJob:true});
  try{if(typeof gdPracticeSetContinueScanReady==="function")gdPracticeSetContinueScanReady(false);}catch(e){}
  try{if(typeof renderPracticeData==="function")renderPracticeData(true);}catch(e){}
  return false;
}
function gdPracticeCancelImportJob(){
  const job=gdPracticeHydrateImportJob();
  if(!job)return false;
  gdPracticeMarkManualScanStop();
  if(String(job.status)==="saving"){
    gdPracticeUpdateImportJob({checkpointText:"Save already started. The import will finish or become recoverable.",userMessage:"Save already started. The import will finish or become recoverable."});
    gdLmToast("Import save already started");
    return false;
  }
  gdPracticeUpdateImportJob({status:"canceled",checkpointText:"Canceled by user",userMessage:"Canceled by user",progress:100});
  gdSetPracticePhotoProcessing(false,{immediate:true,skipJob:true});
  return false;
}
function gdPracticeReviewImportJob(){
  try{
    gdSetShotDataLibraryOpen("practice",true);
    gdTogglePracticeAdmin(true);
    if(typeof gdPracticeImportOpen!=="undefined")gdPracticeImportOpen=false;
    if(typeof gdPracticeEmailLaneOpen!=="undefined")gdPracticeEmailLaneOpen=false;
    gdRenderPracticeImportPanel();
    renderPracticeData(true);
    gdTogglePracticeAdmin(true);
    gdRenderPracticeImportPanel();
  }catch(e){}
  return false;
}
function gdPracticeHandleImportJobAction(action,event){
  try{
    if(event){
      event.preventDefault();
      event.stopPropagation();
      if(event.stopImmediatePropagation)event.stopImmediatePropagation();
    }
  }catch(e){}
  const resolved=String(action||"");
  if(resolved==="cancel")return gdPracticeCancelImportJob();
  if(resolved==="discard"||resolved==="clear")return gdPracticeClearImportJob();
  if(resolved==="review")return gdPracticeReviewImportJob();
  return false;
}
try{
  Object.assign(window,{
    gdPracticeHandleImportJobAction,
    gdPracticeClearImportJob,
    gdPracticeReviewImportJob,
    gdPracticeCancelImportJob,
    gdPracticeHardStopScan,
    gdPracticePrimaryScanAction,
    gdRunDefaultPracticePhotoScanFromCheckpoint,
    gdCancelPracticePhotoScan
  });
}catch(e){}
function gdPracticeSyncImportProcessing(job=gdPracticeImportJob){
  if(!gdPracticeImportIsActive(job))return;
  gdPracticePhotoProcessing=true;
  gdPracticePhotoProcessingProgress=Math.max(1,Math.min(98,Number(job.progress)||8));
  gdPracticePhotoProcessingStageIndex=Math.max(0,Math.min(GD_PRACTICE_PROCESSING_STAGES.length-1,Math.round(Number(job.stageIndex)||0)));
  if(!gdPracticePhotoProcessingStartedAt)gdPracticeProcessingStart();
  document.body.classList.add("gdPracticePhotoProcessing");
  document.getElementById("practiceDataPanel")?.classList.add("gdPracticePhotoProcessing");
  try{gdPracticeSyncLibraryProcessingSurface();}catch(e){}
}
function gdPracticeAssertImportNotCanceled(){
  const job=gdPracticeHydrateImportJob();
  if(job&&String(job.status)==="canceled")throw new Error("Practice import canceled");
}
function gdPracticeProcessingElapsed(){
  return gdPracticePhotoProcessingStartedAt?Math.max(0,Date.now()-gdPracticePhotoProcessingStartedAt):0;
}
function gdPracticeYieldScanPaint(){
  return new Promise(resolve=>{
    let done=false;
    const finish=()=>{if(done)return;done=true;resolve();};
    try{requestAnimationFrame(()=>requestAnimationFrame(finish));}catch(e){}
    setTimeout(finish,90);
  });
}
function gdPracticeProcessingStageState(){
  const activeJob=gdPracticeHydrateImportJob();
  if(gdPracticeImportIsActive(activeJob)){
    return{
      index:Math.max(0,Math.min(GD_PRACTICE_PROCESSING_STAGES.length-1,Math.round(Number(activeJob.stageIndex)||0))),
      progress:Math.max(4,Math.min(98,Math.round(Number(activeJob.progress)||8)))
    };
  }
  if(gdPracticePhotoProcessing){
    const explicitProgress=Number(gdPracticePhotoProcessingProgress);
    const explicitIndex=Number(gdPracticePhotoProcessingStageIndex);
    if(Number.isFinite(explicitProgress)&&explicitProgress>0){
      return{
        index:Number.isFinite(explicitIndex)?Math.max(0,Math.min(GD_PRACTICE_PROCESSING_STAGES.length-1,Math.round(explicitIndex))):0,
        progress:Math.max(4,Math.min(100,Math.round(explicitProgress)))
      };
    }
  }
  const elapsed=gdPracticeProcessingElapsed();
  const thresholds=[0,1400,3200,5400];
  let index=0;
  thresholds.forEach((ms,i)=>{if(elapsed>=ms)index=i;});
  const progress=Math.max(8,Math.min(94,Math.round((elapsed/7600)*94)));
  return{index,progress};
}
function gdPracticeProcessingRefresh(){
  if(!gdPracticeScanProgressIsActive())return;
  gdPracticeHydrateImportJob();
  try{if(typeof renderPracticeData==="function")renderPracticeData(true);}catch(e){}
  try{gdPracticeSyncLibraryProcessingSurface();}catch(e){}
}
function gdPracticeProcessingStart(){
  gdPracticePhotoProcessingStartedAt=Date.now();
  if(gdPracticePhotoProcessingTimer)clearInterval(gdPracticePhotoProcessingTimer);
  gdPracticePhotoProcessingTimer=setInterval(gdPracticeProcessingRefresh,850);
}
function gdPracticeProcessingStop(){
  gdPracticePhotoProcessingStartedAt=0;
  if(gdPracticePhotoProcessingTimer){
    clearInterval(gdPracticePhotoProcessingTimer);
    gdPracticePhotoProcessingTimer=null;
  }
}
try{
  gdPracticeLibraryOpen=false;
  localStorage.setItem("gd_practice_library_open","0");
  gdCourseLibraryOpen=localStorage.getItem("gd_course_library_open")==="1";
  gdCourseImportOpen=localStorage.getItem("gd_course_import_open")==="1";
}catch(e){}
function gdShotDataLibraryIsOpen(kind){
  return String(kind||"practice").toLowerCase()==="course"?!!gdCourseLibraryOpen:!!gdPracticeLibraryOpen;
}
function gdSetShotDataLibraryOpen(kind,open){
  const course=String(kind||"practice").toLowerCase()==="course";
  if(course)gdCourseLibraryOpen=!!open;
  else gdPracticeLibraryOpen=!!open;
  try{
    if(course)localStorage.setItem("gd_course_library_open",open?"1":"0");
    else localStorage.setItem("gd_practice_library_open",open?"1":"0");
  }catch(e){}
  return true;
}
function gdToggleShotDataLibrary(kind,event){
  event?.preventDefault?.();
  event?.stopPropagation?.();
  event?.stopImmediatePropagation?.();
  const course=String(kind||"practice").toLowerCase()==="course";
  const resolvedKind=course?"course":"practice";
  const nextOpen=!gdShotDataLibraryIsOpen(resolvedKind);
  gdSetShotDataLibraryOpen(resolvedKind,nextOpen);
  const shellSelector=course?".gdShotDataLibraryShell-course":".gdShotDataLibraryShell-practice";
  const toggleSelector=course?".gdCourseLibraryTabs":".gdPracticeLibraryTabs";
  document.querySelectorAll(shellSelector).forEach(shell=>shell.classList.toggle("open",nextOpen));
  document.querySelectorAll(toggleSelector).forEach(toggle=>toggle.setAttribute("aria-expanded",nextOpen?"true":"false"));
  if(course&&typeof renderStats==="function")renderStats();
  else if(!course&&typeof renderPracticeData==="function")renderPracticeData(true);
  if(document.getElementById("dataHubPanel")?.classList.contains("open")&&typeof renderCompareData==="function")renderCompareData();
  return false;
}
if(!window.__gdShotDataLibraryToggleBound){
  window.__gdShotDataLibraryToggleBound=true;
  document.addEventListener("click",event=>{
    const toggle=event.target&&event.target.closest&&event.target.closest("[data-gd-shot-library-kind]");
    if(!toggle)return;
    return gdToggleShotDataLibrary(toggle.dataset.gdShotLibraryKind||"practice",event);
  },true);
}
function gdNativeShotDataProcessingTrackHTML(clubLabel=""){
  const job=gdPracticeHydrateImportJob();
  const state=gdPracticeProcessingStageState();
  const label=gdPracticeImportIsActive(job)&&job?.checkpointText
    ?String(job.checkpointText)
    :(GD_PRACTICE_PROCESSING_STAGES[state.index]||"Processing");
  const stages=GD_PRACTICE_PROCESSING_STAGES.map((stageLabel,index)=>{
    const tone=index<state.index?"done":(index===state.index?"active":"pending");
    return `<span class="gdNativeProcessingNode ${tone}" aria-label="${gdEscapeHTML(stageLabel)}"><span>${index+1}</span></span>`;
  }).join("");
  return `<span class="gdNativeProcessingBadge" aria-live="polite"><span class="gdNativeProcessingTrack" aria-hidden="true"><span class="gdNativeProcessingRail"></span><span class="gdNativeProcessingFill" style="width:${state.progress}%"></span><span class="gdNativeProcessingNodes">${stages}</span></span><span class="gdNativeProcessingLabel">${gdEscapeHTML(label)}</span></span>`;
}
function gdNativeShotDataProcessingStopHTML(){
  return `<button type="button" class="gdNativeProcessingStop" onclick="return gdPracticeHardStopScan('Manual stop from library progress')">Stop scan</button>`;
}
function gdNativeShotDataProcessingStackHTML(extraClass=""){
  const cls=`gdNativeProcessingStack${extraClass?` ${extraClass}`:""}`;
  return `<span class="${cls}">${gdNativeShotDataProcessingTrackHTML()}${gdNativeShotDataProcessingStopHTML()}</span>`;
}
function gdPracticeClearLibraryProcessingSurface(){
  document.querySelectorAll(".gdPracticeLibraryProcessing").forEach(node=>node.remove());
  document.querySelectorAll(".gdPracticeLibraryTabs .gdNativeProcessingStack").forEach(node=>node.remove());
}
function gdPracticeSyncLibraryProcessingSurface(){
  const job=gdPracticeHydrateImportJob();
  const active=gdPracticeImportIsActive(job)||gdPracticeScanProgressIsActive();
  if(!active){
    gdPracticeClearLibraryProcessingSurface();
    return false;
  }
  try{gdSetShotDataLibraryOpen("practice",true);}catch(e){}
  document.querySelectorAll(".gdShotDataLibraryShell-practice").forEach(shell=>shell.classList.add("open"));
  document.querySelectorAll(".gdPracticeLibraryTabs").forEach(toggle=>toggle.setAttribute("aria-expanded","true"));
  const tabMain=document.querySelector(".gdShotDataLibraryShell-practice .gdShotDataLibraryTabMain");
  if(tabMain){
    let headerSurface=Array.from(tabMain.children||[]).find(node=>node.classList&&node.classList.contains("gdNativeProcessingStack"));
    if(!headerSurface){
      headerSurface=document.createElement("span");
      tabMain.append(headerSurface);
    }
    headerSurface.className="gdNativeProcessingStack gdPracticeLibraryHeaderProcessing";
    headerSurface.innerHTML=gdNativeShotDataProcessingTrackHTML();
    document.querySelectorAll(".gdPracticeLibraryProcessing").forEach(node=>node.remove());
    return true;
  }
  const body=document.querySelector(".gdShotDataLibraryShell-practice .gdPracticeLibraryBody")
    ||document.querySelector(".gdShotDataLibraryShell-practice")
    ||document.getElementById("gdPracticeEvidenceList")
    ||document.getElementById("practiceDataPanel");
  if(!body)return false;
  let surface=Array.from(body.children||[]).find(node=>node.classList&&node.classList.contains("gdPracticeLibraryProcessing"));
  if(!surface){
    surface=document.createElement("div");
    surface.className="gdPracticeLibraryProcessing";
    body.prepend(surface);
  }
  document.querySelectorAll(".gdPracticeLibraryProcessing").forEach(node=>{if(node!==surface)node.remove();});
  surface.innerHTML=gdNativeShotDataProcessingStackHTML();
  return true;
}
function gdNativeShotDataProcessingHTML(){
  const job=gdPracticeHydrateImportJob();
  if(gdPracticeImportIsActive(job)){
    gdPracticeSyncImportProcessing(job);
    return gdNativeShotDataProcessingStackHTML("gdPracticeLibraryHeaderProcessing");
  }
  if(gdPracticeScanProgressIsActive()){
    if(!gdPracticePhotoProcessingStartedAt)gdPracticeProcessingStart();
    return gdNativeShotDataProcessingStackHTML("gdPracticeLibraryHeaderProcessing");
  }
  if(!gdPracticePhotoProcessing){
    gdPracticeReleaseInactiveProcessingSurface();
    return "";
  }
  if(!gdPracticePhotoProcessingStartedAt||gdPracticeProcessingElapsed()>GD_PRACTICE_ORPHAN_PROCESSING_SURFACE_GRACE_MS){
    gdPracticePhotoProcessing=false;
    gdPracticePhotoProcessingProgress=0;
    gdPracticePhotoProcessingStageIndex=0;
    try{
      document.body?.classList.remove("gdPracticePhotoProcessing");
      document.getElementById("practiceDataPanel")?.classList.remove("gdPracticePhotoProcessing");
      gdPracticeClearLibraryProcessingSurface();
    }catch(e){}
    return "";
  }
  return gdNativeShotDataProcessingStackHTML("gdPracticeLibraryHeaderProcessing");
}
function gdSetPracticePhotoProcessing(active,opts={}){
  const wasProcessing=gdPracticePhotoProcessing;
  const optionClubs=Array.isArray(opts?.clubs)?opts.clubs.map(club=>String(club||"").trim()).filter(Boolean):[];
  if(active&&gdPracticePhotoProcessingStopTimer){
    clearTimeout(gdPracticePhotoProcessingStopTimer);
    gdPracticePhotoProcessingStopTimer=null;
  }
  if(!active&&gdPracticePhotoProcessing&&!opts?.immediate){
    const completionRemaining=gdPracticePhotoProcessingCompletedAt
      ? GD_PRACTICE_PROCESSING_COMPLETE_VISIBLE_MS-(Date.now()-gdPracticePhotoProcessingCompletedAt)
      : 0;
    const remaining=Math.max(GD_PRACTICE_PROCESSING_MIN_VISIBLE_MS-gdPracticeProcessingElapsed(),completionRemaining);
    if(remaining>0){
      if(gdPracticePhotoProcessingStopTimer)clearTimeout(gdPracticePhotoProcessingStopTimer);
      gdPracticePhotoProcessingStopTimer=setTimeout(()=>{
        gdPracticePhotoProcessingStopTimer=null;
        gdSetPracticePhotoProcessing(false,Object.assign({},opts,{immediate:true}));
      },remaining);
      try{if(typeof renderPracticeData==="function")renderPracticeData(true);}catch(e){}
      return;
    }
  }
  if(!active&&gdPracticePhotoProcessingStopTimer){
    clearTimeout(gdPracticePhotoProcessingStopTimer);
    gdPracticePhotoProcessingStopTimer=null;
  }
  gdPracticePhotoProcessing=!!active;
  if(gdPracticePhotoProcessing){
    const progress=Number(opts?.progress);
    const stage=Number(opts?.stageIndex);
    if(Number.isFinite(progress))gdPracticePhotoProcessingProgress=Math.max(1,Math.min(98,progress));
    else if(!wasProcessing)gdPracticePhotoProcessingProgress=8;
    if(Number.isFinite(stage))gdPracticePhotoProcessingStageIndex=Math.max(0,Math.min(GD_PRACTICE_PROCESSING_STAGES.length-1,Math.round(stage)));
    else if(!wasProcessing)gdPracticePhotoProcessingStageIndex=0;
  }else{
    gdPracticePhotoProcessingProgress=0;
    gdPracticePhotoProcessingStageIndex=0;
    gdPracticePhotoProcessingCompletedAt=0;
  }
  if(gdPracticePhotoProcessing&&!wasProcessing)gdPracticeProcessingStart();
  if(!gdPracticePhotoProcessing&&wasProcessing)gdPracticeProcessingStop();
  if(gdPracticePhotoProcessing){
    try{gdSetShotDataLibraryOpen("practice",true);}catch(e){}
  }
  const panel=document.getElementById("practiceDataPanel");
  panel?.classList.toggle("gdPracticePhotoProcessing",gdPracticePhotoProcessing);
  document.body.classList.toggle("gdPracticePhotoProcessing",gdPracticePhotoProcessing);
  if(gdPracticePhotoProcessing){
    const keepAdminOpen=typeof gdPracticeAdminIsOpen==="function"&&gdPracticeAdminIsOpen();
    gdPracticePhotoProcessingClubs=optionClubs.length
      ? optionClubs
      : (opts?.preserveClubs&&Array.isArray(gdPracticePhotoProcessingClubs)&&gdPracticePhotoProcessingClubs.length
        ? gdPracticePhotoProcessingClubs
        : (typeof gdPracticeScanClubLabels==="function"?gdPracticeScanClubLabels():["7i"]));
    try{
      if(typeof gdPracticeImportOpen!=="undefined"){
        gdPracticeImportOpen=false;
        localStorage.removeItem(GD_PRACTICE_IMPORT_OPEN_KEY);
        gdRenderPracticeImportPanel();
      }
      if(typeof gdTogglePracticeAdmin==="function"&&!keepAdminOpen)gdTogglePracticeAdmin(false);
      else if(keepAdminOpen&&typeof gdRenderPracticeAdminChrome==="function")gdRenderPracticeAdminChrome();
      const nativeDrawer=document.getElementById("gdNativePracticeImportDrawer");
      if(nativeDrawer)nativeDrawer.open=false;
      const feedback=document.getElementById("gdNativePracticeFeedback");
      if(feedback)feedback.innerHTML="";
    }catch(e){}
    if(opts?.quietScanSurface)gdPracticeQuietScanSurface(typeof opts.quietScanSurface==="object"?opts.quietScanSurface:{});
    else gdPracticeRefreshDebugTools();
  }
  if(!opts?.skipJob){
    const job=gdPracticeHydrateImportJob();
    if(job&&gdPracticeImportIsActive(job)){
      if(gdPracticePhotoProcessing){
        gdPracticeUpdateImportJob({
          progress:gdPracticePhotoProcessingProgress,
          stageIndex:gdPracticePhotoProcessingStageIndex,
          clubs:gdPracticePhotoProcessingClubs
        });
      }else if(String(job.status)!=="saving"){
        gdPracticeUpdateImportJob({status:"failed",checkpointText:"Import stopped before it completed",userMessage:"Import stopped before it completed"});
      }
    }
  }
  try{if(typeof renderPracticeData==="function")renderPracticeData(true);}catch(e){}
  try{gdPracticeSyncLibraryProcessingSurface();}catch(e){}
}
function gdToggleCourseImport(event){
  event?.preventDefault?.();
  event?.stopPropagation?.();
  event?.stopImmediatePropagation?.();
  gdCourseImportOpen=!gdCourseImportOpen;
  try{localStorage.setItem("gd_course_import_open",gdCourseImportOpen?"1":"0");}catch(e){}
  if(typeof gdRenderCourseDataAdminPanel==="function")gdRenderCourseDataAdminPanel();
  return false;
}
function gdCourseBubbleValueLabel(analysis, filteredAnalysis, records){
  let p=null;
  try{p=typeof ensureProfile==="function"?ensureProfile():null;}catch(e){p=null;}
  let source=null;
  try{source=typeof gdCourseBubbleSource==="function"?gdCourseBubbleSource(analysis,filteredAnalysis,records,p):null;}catch(e){source=null;}
  const offset=Number(source?.offsetDeg);
  return source&&Number.isFinite(offset)?"Bubble ready":"Bubble not ready";
}
function gdCourseLibraryClubTabsHTML(analysis, filteredRecords){
  const allRows=Array.isArray(analysis?.records)?analysis.records:[];
  const rows=allRows.length?allRows:(Array.isArray(filteredRecords)?filteredRecords:[]);
    if(!rows.length)return `<div class="gdCourseLibraryClubTabs empty"><span>No course shots yet</span></div>`;
  const selected=gdStatsView.club||"all";
  const grouped={};
  rows.forEach(record=>{
    const club=record?.club||"Unknown";
    grouped[club]=grouped[club]||[];
    grouped[club].push(record);
  });
  const allActive=selected==="all";
  const all=`<button type="button" class="gdCourseLibraryClubTab ${allActive?"active":""}" onclick="gdStatsSelectClub('all');return false"><span>All</span><strong>${rows.length}</strong></button>`;
  const clubs=Object.keys(grouped).sort((a,b)=>a.localeCompare(b,undefined,{numeric:true})).map(club=>{
    const active=selected===club;
    const clubRows=grouped[club]||[];
    return `<button type="button" class="gdCourseLibraryClubTab ${active?"active":""}" onclick="gdStatsSelectClub(${gdShotDataJsArg(club)});return false"><span>${gdEscapeHTML(club)}</span><strong>${clubRows.length}</strong></button>`;
  }).join("");
  return `<div class="gdCourseLibraryClubTabs">${all}${clubs}</div>`;
}
function gdCourseLibraryShellHTML(analysis, filteredAnalysis, filteredRecords, counts, bodyHTML){
  const safeCounts=counts||gdCourseDataLandingCounts(analysis,filteredRecords);
  const totalRows=Number(safeCounts.records)||Number(Array.isArray(filteredRecords)?filteredRecords.length:0)||0;
  const bubble=gdCourseBubbleValueLabel(analysis,filteredAnalysis,filteredRecords);
  return gdShotDataLibraryShellHTML({kind:"course",title:"Course Library",bubbleLabel:"Course Bubble",bubbleValue:bubble,count:totalRows,bodyHTML,dropdown:true,open:gdShotDataLibraryIsOpen("course")});
}
function gdRenderCourseDataLanding(analysis, filteredRecords, filteredAnalysis){
  const root=document.getElementById("gdCourseDataLanding");
  if(!root)return;
  const counts=gdCourseDataLandingCounts(analysis,filteredRecords);
  const status=counts.shown?`${counts.shown} shown`:
    counts.records?`${counts.records} paired`:
    counts.paired?`${counts.paired} paired, waiting for usable shots`:
    counts.planned?`${counts.planned} planned`:
    counts.rawEvents?`${counts.rawEvents} ball events`:"No data yet";
  const countedLabel=counts.shown?`${counts.counted}/${counts.shown} counted`:"0 shown";
  const body=`<div class="gdCourseDataLandingHead"><span>Stored shots</span><strong>${gdEscapeHTML(status)}</strong></div><div class="gdCourseDataLandingStats"><b>${counts.planned} plans</b><b>${counts.paired} pairs</b><b>${countedLabel}</b></div>${gdCourseLibraryClubTabsHTML(analysis,filteredRecords)}`;
  root.innerHTML=gdCourseLibraryShellHTML(analysis,filteredAnalysis,filteredRecords,counts,body);
}
function gdCourseDataCanManage(){
  let permission="player";
  try{permission=typeof gdGetAccountPermission==="function"?gdGetAccountPermission():"player"}catch(e){}
  return permission==="admin"||permission==="coach";
}
