function gdSetCourseDataTab(tab, forceOpen){
  if(tab==="admin"&&!gdCourseDataCanManage()){
    try{toast("Course Data admin is coach/admin only");}catch(e){}
    return false;
  }
  const panel=document.getElementById("statsPanel");
  const btn=document.getElementById("gdCourseAdminExpanderBtn");
  const open=!!panel?.classList.contains("gdCourseAdminTab");
  const admin=typeof forceOpen==="boolean"?forceOpen:(tab==="admin"?!open:false);
  panel?.classList.toggle("gdCourseAdminTab",admin);
  if(btn){
    btn.classList.toggle("active",admin);
    btn.setAttribute("aria-expanded",admin?"true":"false");
    btn.textContent=admin?"Hide admin":"Admin";
  }
  if(admin&&typeof gdRenderCourseDataAdminPanel==="function")gdRenderCourseDataAdminPanel();
  if(admin)gdEnsureCourseDataAdminFallback();
  return false;
}
function gdDeleteCourseShot(shotId){
  if(!gdCourseDataCanManage())return;
  const id=String(shotId||"");
  if(!id)return;
  if(!confirm("Delete this paired course shot?"))return;
  const api=window.GolfDaddyShotEvents;
  const store=safe(()=>api?.getScopedStore?.()||api?.getStore?.(),null);
  if(!api||!store){toast("Course data feed unavailable");return}
  if(typeof api.deleteShot==="function")api.deleteShot(id);
  else{
    store.plannedShots=(store.plannedShots||[]).filter(shot=>shot.shotId!==id);
    store.outcomes=(store.outcomes||[]).filter(outcome=>outcome.shotId!==id);
    store.updatedAt=new Date().toISOString();
    try{localStorage.setItem(api.storageKey||"gd_shot_events_v1",JSON.stringify(store));}catch(e){console.warn("[GolfDaddy] course shot delete failed",e)}
  }
  renderStats();
  renderDataHubStatus();
  renderCompareData();
  toast("Course shot deleted");
}
function gdRenderCourseDataAdminPanel(){
  const root=document.getElementById("gdCourseDataAdminPanel");
  if(!root)return;
  const canManage=gdCourseDataCanManage();
  let records=[];
  try{
    const analysis=gdCurrentStatsAnalysis();
    records=(analysis?.records||[]).slice().sort((a,b)=>gdStatsShotTime(b)-gdStatsShotTime(a));
  }catch(e){records=[];}
  const badge=canManage?"Admin editable":"Locked by permission";
  const rows=records.map(record=>{
    const shotId=String(record.shotId||"");
    const escapedId=gdEscapeHTML(shotId).replace(/'/g,"&#39;");
    const action=canManage&&shotId?`<button type="button" onclick="event.stopPropagation();gdDeleteCourseShot('${escapedId}')">Delete</button>`:`<span class="gdShotAdminBadge">Locked</span>`;
    return `<div class="gdShotAdminRow"><div><strong>${gdEscapeHTML(record.club||"Unknown")} · ${Number(record.actualDistanceM||0).toFixed(0)}m</strong><span>${record.counted?"Counted":"Filtered"} · ${gdOffsetLabel(record.normalizedDeg||0)} · ${gdEscapeHTML(record.holeId||record.roundId||"course shot")}</span></div>${action}</div>`;
  }).join("");
  root.innerHTML=`<div class="gdShotAdminHead"><div><strong>Course Data admin</strong><span>Permission-gated management lives here, away from the normal shot view.</span></div><div class="gdShotAdminBadge">${badge}</div></div><div class="gdShotAdminList">${rows||'<div class="gdShotAdminEmpty">No paired course shots to manage yet.</div>'}</div>`;
  gdEnsureCourseDataAdminFallback();
}
