function gdShotChartClamp(value,min,max){
  return Math.max(min,Math.min(max,Number(value)||0));
}
function gdShotChartQuantile(values,pct){
  const sorted=(values||[]).map(Number).filter(Number.isFinite).sort((a,b)=>a-b);
  if(!sorted.length)return 0;
  const index=gdShotChartClamp(pct,0,1)*(sorted.length-1);
  const lower=Math.floor(index),upper=Math.ceil(index);
  if(lower===upper)return sorted[lower];
  const t=index-lower;
  return sorted[lower]*(1-t)+sorted[upper]*t;
}
function gdShotChartNiceStep(range,targetTicks=4){
  const raw=Math.max(1,Number(range)||1)/Math.max(1,Number(targetTicks)||4);
  const pow=Math.pow(10,Math.floor(Math.log10(raw)));
  const unit=raw/pow;
  const nice=unit<=1?1:unit<=2?2:unit<=2.5?2.5:unit<=5?5:10;
  return nice*pow;
}
function gdShotChartNiceMax(value,targetTicks=4,minValue=1){
  const step=gdShotChartNiceStep(Math.max(minValue,Number(value)||minValue),targetTicks);
  return Math.max(minValue,Math.ceil(Math.max(minValue,Number(value)||minValue)/step)*step);
}
function gdShotChartTickValues(maxValue,targetTicks=4){
  const max=Math.max(1,Number(maxValue)||1);
  const step=gdShotChartNiceStep(max,targetTicks);
  const ticks=[];
  for(let value=0;value<=max+step*.5;value+=step){
    const rounded=Math.round(value*10)/10;
    if(rounded<=max+step*.25)ticks.push(rounded);
  }
  if(ticks[ticks.length-1]!==max)ticks.push(max);
  return [...new Set(ticks.map(value=>Math.round(value*10)/10))];
}
function gdShotChartLateralStep(maxValue){
  const max=Math.max(5,Number(maxValue)||5);
  if(max<=20)return 5;
  if(max<=40)return 10;
  if(max<=80)return 20;
  return gdShotChartNiceStep(max,4);
}
function gdShotChartEnsureLateralRange(plot,...values){
  if(!plot)return plot;
  const next=Math.max(
    Number(plot.lateralMax)||0,
    ...values.map(Number).filter(Number.isFinite)
  );
  plot.lateralMax=gdShotChartNiceMax(next,4,18);
  plot.lateralStep=gdShotChartLateralStep(plot.lateralMax);
  return plot;
}
function gdShotChartLayout(dataRows, overlayRows, opts={}){
  const chartWidth=Number(opts.width)||480;
  const chartHeight=Number(opts.height)||260;
  const plotLeft=Number(opts.plotLeft)||34;
  const labelGutter=Math.max(34,Number(opts.labelGutter)||38);
  const requestedRight=Number(opts.plotRight)||450;
  const plotRight=Math.min(requestedRight,chartWidth-labelGutter);
  const plotTop=Number(opts.plotTop)||82;
  const plotBottom=Number(opts.plotBottom)||224;
  const plotMidY=(plotTop+plotBottom)/2;
  const distanceValues=(dataRows||[]).concat(overlayRows||[])
    .map(row=>Number(row&&row.actualDistanceM))
    .filter(value=>Number.isFinite(value)&&value>0);
  const hardMax=Math.max(120,Number(opts.maxDomainM)||520);
  const scaleDistances=distanceValues.filter(value=>value<=hardMax);
  const domainSource=scaleDistances.length?scaleDistances:distanceValues.map(value=>Math.min(value,hardMax));
  const highBase=domainSource.length>=8?gdShotChartQuantile(domainSource,.96):Math.max(60,...domainSource);
  const distancePadding=Math.max(14,highBase*.07);
  const maxDistance=gdShotChartNiceMax(Math.min(hardMax,highBase+distancePadding),4,60);
  const lateralValues=(dataRows||[]).concat(overlayRows||[])
    .filter(row=>row&&row.hasLateral!==false)
    .map(row=>Math.abs(Number(row.lateralM)))
    .filter(Number.isFinite);
  const lateralBase=lateralValues.length>=8?gdShotChartQuantile(lateralValues,.94):Math.max(0,...lateralValues);
  const lateralMax=gdShotChartNiceMax(lateralBase*1.18+2,4,Number(opts.minLateralM)||18);
  return {
    chartWidth,chartHeight,plotLeft,plotRight,plotTop,plotBottom,plotMidY,
    labelX:Math.min(chartWidth-8,plotRight+10),
    minDistance:0,
    maxDistance,
    distanceRange:Math.max(1,maxDistance),
    lateralMax,
    lateralStep:gdShotChartLateralStep(lateralMax),
    tickValues:gdShotChartTickValues(maxDistance,4)
  };
}
function gdShotChartTicksSvg(plot){
  const minDistance=Math.max(0,Number(plot.minDistance)||0);
  const maxDistance=Math.max(minDistance,Number(plot.maxDistance)||0);
  const distanceRange=Math.max(1,Number(plot.distanceRange)||maxDistance-minDistance||1);
  const tickValues=[...new Set((plot.tickValues||[])
    .map(Number)
    .filter(value=>Number.isFinite(value)&&value>=minDistance&&value<=maxDistance)
    .map(value=>Math.round(value)))];
  return tickValues.map(value=>{
    const x=plot.plotLeft+((value-minDistance)/distanceRange)*(plot.plotRight-plot.plotLeft);
    const anchor=value===minDistance?"start":value===Math.round(maxDistance)?"end":"middle";
    const opacity=value===minDistance||value===Math.round(maxDistance)?".12":".075";
    return `<line x1="${x.toFixed(1)}" y1="${plot.plotTop}" x2="${x.toFixed(1)}" y2="${plot.plotBottom}" stroke="rgba(255,255,255,${opacity})" stroke-width="1"/><line x1="${x.toFixed(1)}" y1="${plot.plotBottom}" x2="${x.toFixed(1)}" y2="${plot.plotBottom+4}" stroke="rgba(238,245,242,.24)" stroke-width="1"/><text x="${x.toFixed(1)}" y="${plot.plotBottom+18}" fill="rgba(238,245,242,.58)" font-size="9" font-weight="850" text-anchor="${anchor}">${Math.round(value)}m</text>`;
  }).join("");
}
function gdShotChartOfflineGridSvg(plot){
  const half=(plot.plotBottom-plot.plotTop)/2;
  const step=Math.max(1,Number(plot.lateralStep)||gdShotChartLateralStep(plot.lateralMax));
  const maxStep=Math.floor((Number(plot.lateralMax)||0)/step)*step;
  const rows=[];
  for(let metres=step;metres<=maxStep;metres+=step){
    [-1,1].forEach(direction=>{
      const y=plot.plotMidY+direction*(metres/Math.max(1,plot.lateralMax))*half;
      if(y<=plot.plotTop+2||y>=plot.plotBottom-2)return;
      const major=metres%(step*2)===0;
      const label=direction<0?"L":"R";
      rows.push(`<line x1="${plot.plotLeft}" y1="${y.toFixed(1)}" x2="${plot.plotRight}" y2="${y.toFixed(1)}" stroke="rgba(238,245,242,${major?".12":".075"})" stroke-width="1" stroke-dasharray="${major?"4 10":"2 12"}" stroke-linecap="round"/>`);
      rows.push(`<text x="${plot.labelX.toFixed(1)}" y="${(y+2.6).toFixed(1)}" fill="rgba(238,245,242,${major?".44":".34"})" font-size="8" font-weight="850" text-anchor="start">${label} ${Math.round(metres)}m</text>`);
    });
  }
  return rows.join("");
}
function gdShotChartBackdropSvg(plot,title){
  const width=Number(plot.chartWidth)||480;
  const height=Number(plot.chartHeight)||260;
  return `<rect width="${width}" height="${height}" fill="rgba(0,0,0,.08)"/>
    <rect x="${(plot.plotLeft-12).toFixed(1)}" y="${(plot.plotTop-16).toFixed(1)}" width="${(plot.plotRight-plot.plotLeft+56).toFixed(1)}" height="${(plot.plotBottom-plot.plotTop+42).toFixed(1)}" rx="10" fill="rgba(255,255,255,.012)" stroke="rgba(255,255,255,.045)" stroke-width="1"/>
    <line x1="${plot.plotLeft}" y1="${plot.plotTop}" x2="${plot.plotLeft}" y2="${plot.plotBottom}" stroke="rgba(255,255,255,.18)" stroke-width="1"/>
    <line x1="${plot.plotLeft}" y1="${plot.plotBottom}" x2="${plot.plotRight}" y2="${plot.plotBottom}" stroke="rgba(255,255,255,.12)" stroke-width="1"/>
    ${gdShotChartOfflineGridSvg(plot)}
    <line x1="${plot.plotLeft}" y1="${plot.plotMidY}" x2="${plot.plotRight}" y2="${plot.plotMidY}" stroke="rgba(255,255,255,.22)" stroke-width="1" stroke-dasharray="5 7" stroke-linecap="round"/>
    <path d="M ${(plot.plotLeft+8).toFixed(1)} ${plot.plotMidY.toFixed(1)} H ${(plot.plotLeft+40).toFixed(1)}" stroke="rgba(238,245,242,.55)" stroke-width="1.4" stroke-linecap="round"/>
    <circle cx="${plot.plotLeft}" cy="${plot.plotMidY}" r="6.2" fill="#f8faf7" stroke="rgba(0,0,0,.55)" stroke-width="1.4"/>
    <circle cx="${plot.plotLeft}" cy="${plot.plotMidY}" r="2.1" fill="#07100d"/>
    <text x="${plot.plotLeft+10}" y="${plot.plotMidY+21}" fill="rgba(238,245,242,.62)" font-size="8.5" font-weight="900">Origin</text>
    ${gdShotChartTicksSvg(plot)}
    <text x="22" y="34" fill="#fff" font-size="21" font-weight="950">${gdStatsSvgText(title)}</text>`;
}
function gdShotChartLateralInfo(source,distance){
  const direct=Number(source&&source.lateralM);
  if(Number.isFinite(direct))return{value:direct,hasLateral:true};
  const deg=Number(source&&(source.normalizedDeg??source.plot?.normalizedDeg));
  if(Number.isFinite(deg)&&Number.isFinite(distance)&&distance>0){
    return{value:Math.tan(deg*Math.PI/180)*distance,hasLateral:true};
  }
  return{value:0,hasLateral:false};
}
function gdShotChartYForLateral(plot,lateral){
  const half=(plot.plotBottom-plot.plotTop)/2;
  return plot.plotMidY-gdShotChartClamp((Number(lateral)||0)/Math.max(1,plot.lateralMax),-1,1)*half;
}
function gdShotChartPoint(plot,distance,lateral,index,hasLateral=true){
  const actual=Number(distance);
  if(!Number.isFinite(actual)||actual<=0)return null;
  const x=gdShotChartClamp(plot.plotLeft+(actual/plot.distanceRange)*(plot.plotRight-plot.plotLeft),plot.plotLeft,plot.plotRight);
  const jitter=((Number(index)||0)%5-2)*1.15;
  const half=(plot.plotBottom-plot.plotTop)/2;
  const y=hasLateral===false
    ? plot.plotMidY+Math.min(34,half*.48)+jitter
    : gdShotChartYForLateral(plot,lateral)+(Math.abs(Number(lateral)||0)<.25?jitter:0);
  return{x,y,clipped:actual>plot.maxDistance};
}
function gdShotChartSourceShape(source){
  return source==="practice"?"diamond":"circle";
}
function gdShotChartDiamondPath(point,radius){
  const r=Number(radius)||2.4;
  return `M ${point.x.toFixed(1)} ${(point.y-r*1.45).toFixed(1)} L ${(point.x+r*1.45).toFixed(1)} ${point.y.toFixed(1)} L ${point.x.toFixed(1)} ${(point.y+r*1.45).toFixed(1)} L ${(point.x-r*1.45).toFixed(1)} ${point.y.toFixed(1)} Z`;
}
function gdShotChartDotSvg(point,{fill="#8f9a96",opacity=".8",radius=2.4,missing=false,stroke="",strokeWidth="",shape="circle"}={}){
  if(!point)return "";
  const strokeAttrs=stroke?` stroke="${stroke}" stroke-width="${strokeWidth||1}"`:"";
  if(shape==="diamond"){
    if(missing){
      return `<path d="${gdShotChartDiamondPath(point,radius)}" fill="rgba(0,0,0,.10)" stroke="${stroke||fill}" stroke-width="${strokeWidth||1.3}" stroke-dasharray="2 2" opacity="${opacity}"/>`;
    }
    return `<path d="${gdShotChartDiamondPath(point,radius)}" fill="${fill}" opacity="${opacity}"${strokeAttrs}/>`;
  }
  if(missing){
    return `<circle cx="${point.x.toFixed(1)}" cy="${point.y.toFixed(1)}" r="${radius.toFixed(1)}" fill="rgba(0,0,0,.10)" stroke="${stroke||fill}" stroke-width="${strokeWidth||1.3}" stroke-dasharray="2 2" opacity="${opacity}"/>`;
  }
  return `<circle cx="${point.x.toFixed(1)}" cy="${point.y.toFixed(1)}" r="${radius.toFixed(1)}" fill="${fill}" opacity="${opacity}"${strokeAttrs}/>`;
}
function gdShotChartClubOvalsSvg(plot,rows,opts={}){
  const minPoints=Math.max(2,Number(opts.minPoints)||2);
  const clusterColour=opts.clusterColour||"rgba(255,210,135,.82)";
  const groups=new Map();
  (rows||[]).forEach((row,rowIndex)=>{
    if(!row||row.counted===false||row.excluded)return;
    const actual=Number(row.actualDistanceM);
    const lateral=Number(row.lateralM);
    const point=gdShotChartPoint(plot,actual,lateral,Number.isFinite(Number(row.index))?Number(row.index):rowIndex,row.hasLateral!==false);
    if(!point)return;
    const club=String(row.club||"Unknown");
    const source=String(row.source||opts.source||"data");
    const key=`${source}::${club}`;
    if(!groups.has(key))groups.set(key,{club,source,points:[]});
    groups.get(key).points.push(point);
  });
  const ovals=[...groups.values()].map(({club,source,points})=>{
    if(points.length<minPoints)return "";
    const xs=points.map(point=>point.x),ys=points.map(point=>point.y);
    const minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);
    const width=maxX-minX,height=maxY-minY;
    const cx=(minX+maxX)/2,cy=(minY+maxY)/2;
    const rx=gdShotChartClamp(width/2+10,20,56);
    const ry=gdShotChartClamp(height/2+8,11,34);
    const colour=clusterColour;
    const dash=opts.strokeDasharray||"1 5";
    const sourceClass=source==="practice"?" practice":" course";
    return `<ellipse class="gdShotChartClubOval${sourceClass}" data-source="${gdStatsSvgText(source)}" cx="${cx.toFixed(1)}" cy="${cy.toFixed(1)}" rx="${rx.toFixed(1)}" ry="${ry.toFixed(1)}" fill="${colour}" fill-opacity="${source==="practice"?".018":".014"}" stroke="${colour}" stroke-width="${source==="practice"?".75":".85"}" stroke-opacity="${source==="practice"?".44":".34"}" stroke-dasharray="${dash}" stroke-linecap="round" pointer-events="none"/>`;
  }).join("");
  return ovals?`<g class="gdShotChartClubOvals" aria-hidden="true">${ovals}</g>`:"";
}
function gdShotChartFitOvalsSvg(plot,fits,rows,opts={}){
  const rowsByClub=new Map();
  (rows||[]).forEach((row,rowIndex)=>{
    if(!row||row.counted===false||row.excluded)return;
    const club=String(row.club||"Unknown");
    if(!rowsByClub.has(club))rowsByClub.set(club,[]);
    rowsByClub.get(club).push(Object.assign({__rowIndex:rowIndex},row));
  });
  const ovals=(fits||[]).map(fit=>{
    const club=String(fit?.club||"Unknown");
    const bubble=fit?.resultBubble||{};
    const clubRows=rowsByClub.get(club)||[];
    if(!clubRows.length||!Number.isFinite(Number(bubble.widthM))||!Number.isFinite(Number(bubble.depthM)))return "";
    const baseDistance=gdShotBubbleMedian(clubRows.map(row=>Number(row.record?.expectedDistanceM)||Number(row.expectedDistanceM)||Number(row.actualDistanceM)).filter(Number.isFinite))||gdShotBubbleMedian(clubRows.map(row=>Number(row.actualDistanceM)).filter(Number.isFinite))||155;
    const actualDistance=baseDistance+(Number(bubble.depthOffsetM)||0);
    const lateral=Number(bubble.lateralOffsetM)||0;
    const source=String(opts.source||"course");
    const offset=Number.isFinite(Number(bubble.normalizedDeg))?Number(bubble.normalizedDeg):Number(fit?.offsetDeg)||0;
    const generated=gdGeneratedShotBubbleForClub(club,baseDistance,offset);
    const widthM=Number(bubble.widthM);
    const depthM=Number(bubble.depthM);
    const simulatedBubble=Object.assign({},generated,{
      club,
      baseDistanceM:baseDistance,
      centerDistanceM:actualDistance,
      centerLateralM:lateral,
      widthM:Number.isFinite(widthM)&&widthM>0?widthM:generated.widthM,
      depthM:Number.isFinite(depthM)&&depthM>0?depthM:generated.depthM,
      lateralRadiusM:Number.isFinite(widthM)&&widthM>0?widthM/2:generated.lateralRadiusM,
      depthRadiusM:Number.isFinite(depthM)&&depthM>0?depthM/2:generated.depthRadiusM,
      offsetDeg:offset
    });
    const xForDistance=distance=>plot.plotLeft+((distance-plot.minDistance)/plot.distanceRange)*(plot.plotRight-plot.plotLeft);
    const yForLateral=value=>plot.plotMidY+gdShotBubbleOverlayClamp(value/plot.lateralMax,-1,1)*((plot.plotBottom-plot.plotTop)/2);
    const path=gdShotBubbleOverlayBubblePath(simulatedBubble,plot,xForDistance,yForLateral);
    if(!path)return "";
    const colour=opts.colour||opts.color||(source==="practice"?"#37f28d":"#d7b06b");
    return `<path class="gdShotChartFitOval ${source}" data-source="${gdStatsSvgText(source)}-fit-bubble" data-club="${gdStatsSvgText(club)}" d="${path}" fill="${colour}" fill-opacity=".05" stroke="${colour}" stroke-width="1.35" stroke-opacity=".58" stroke-linejoin="round" pointer-events="none"/>`;
  }).join("");
  return ovals?`<g class="gdShotChartClubOvals gdShotChartFitOvals" aria-hidden="true">${ovals}</g>`:"";
}
function gdShotChartSourceLegendSvg(x=320,y=58){
  const course=`<circle cx="${x}" cy="${y-1}" r="3.6" fill="#4abfe7" opacity=".84"/><text x="${x+8}" y="${y+2}" fill="rgba(255,255,255,.62)" font-size="8.5" font-weight="850">Course</text>`;
  const practicePoint={x:x+66,y:y-1};
  const practice=`<circle cx="${practicePoint.x}" cy="${practicePoint.y}" r="3.6" fill="#22c978" opacity=".88"/><text x="${x+74}" y="${y+2}" fill="rgba(255,255,255,.62)" font-size="8.5" font-weight="850">Practice</text>`;
  return course+practice;
}
function gdOffsetLabel(value){
  const n=Number(value);
  if(!Number.isFinite(n))return "-";
  if(Math.abs(n)<.05)return "0.0°";
  return `${n>0?"R":"L"} ${Math.abs(n).toFixed(1)}°`;
}
function gdParseOffsetValue(value,fallback=NaN){
  if(typeof value==="number")return Number.isFinite(value)?value:fallback;
  const raw=String(value??"").trim();
  if(!raw)return fallback;
  const direction=raw.match(/\b([lr])\b/i)?.[1]?.toUpperCase()||"";
  const numberMatch=raw.replace(/,/g,".").match(/[+-]?\d+(?:\.\d+)?/);
  if(!numberMatch)return fallback;
  const magnitude=Number(numberMatch[0]);
  if(!Number.isFinite(magnitude))return fallback;
  if(direction==="L")return -Math.abs(magnitude);
  if(direction==="R")return Math.abs(magnitude);
  return magnitude;
}
function gdStatsCurrentModelOffsetDeg(){
  const visible=document.querySelector(".modulePanel.open .gdBubbleFaceOffsetInput")||document.querySelector("#statsPanel.open .gdBubbleFaceOffsetInput");
  const visibleValue=gdParseOffsetValue(visible?.value);
  if(Number.isFinite(visibleValue))return visibleValue;
  const editing=document.querySelector(".gdBubbleFaceOffsetInput[data-editing='1']");
  const live=gdParseOffsetValue(editing?.value);
  if(Number.isFinite(live))return live;
  try{return gdBubbleCentralOffset(ensureProfile());}catch(e){return 1.4}
}
