function gdStatsClubColor(club){
  const name=String(club||"Unknown");
  if(name==="Unknown")return "#9aa4b2";
  let hash=0;
  for(let i=0;i<name.length;i++)hash=(hash*31+name.charCodeAt(i))>>>0;
  return gdStatsClubPalette[hash%gdStatsClubPalette.length];
}
