  const practiceTab=isPractice?" gdPracticeLibraryTab":" gdCourseLibraryTab";
  const practiceBubble=isPractice?" gdPracticeLibraryBubble":" gdCourseLibraryBubble";
  const practiceBody=isPractice?" gdPracticeLibraryBody":" gdCourseLibraryBody";
  const headerStatus=opts.headerStatusHTML?String(opts.headerStatusHTML):"";
