function gdRenderShotBubbleOverlayView(view){
  if(view==="course"){
    gdShotBubbleSafe(()=>typeof renderStats==="function"&&renderStats());
    gdShotBubbleSafe(()=>typeof gdRenderCourseDataSurfaceFallback==="function"&&gdRenderCourseDataSurfaceFallback());
  }else if(view==="practice"){
    gdShotBubbleSafe(()=>typeof renderPracticeData==="function"&&renderPracticeData(true));
  }else{
    gdShotBubbleSafe(()=>typeof renderCompareData==="function"&&renderCompareData());
  }
  gdSyncShotBubbleOverlayControls(view);
  gdShotBubbleSafe(()=>gdApplyShotBubbleDomOverlay(view));
  setTimeout(()=>{
    if(view==="course"){
      gdShotBubbleSafe(()=>typeof renderStats==="function"&&renderStats());
      gdShotBubbleSafe(()=>typeof gdRenderCourseDataSurfaceFallback==="function"&&gdRenderCourseDataSurfaceFallback());
    }else if(view==="practice"){
      gdShotBubbleSafe(()=>typeof renderPracticeData==="function"&&renderPracticeData(true));
    }else{
      gdShotBubbleSafe(()=>typeof renderCompareData==="function"&&renderCompareData());
    }
    gdSyncShotBubbleOverlayControls(view);
    gdShotBubbleSafe(()=>gdApplyShotBubbleDomOverlay(view));
  },0);
}
function gdSyncShotBubbleOverlayControls(view){
  const controls=document.querySelectorAll("[data-gd-overlay-control]");
	  controls.forEach(btn=>{
	    const btnView=btn.dataset.gdOverlayControl||"compare";
	    if(view&&btnView!==view)return;
	    const active=gdShotBubbleOverlayEnabled(btnView);
	    const customLabel=btn.dataset.gdOverlayLabel||"";
	    btn.classList.toggle("active",active);
	    btn.setAttribute("aria-pressed",active?"true":"false");
	    btn.textContent=customLabel
	      ? active?`Hide ${customLabel}`:`Overlay ${customLabel}`
	      : active?"Hide Shot Data Overlay":"Overlay Shot Data";
	  });
	}
function gdWireShotBubbleOverlayToggle(){
  if(window.__gdShotBubbleOverlayToggleWired)return;
  window.__gdShotBubbleOverlayToggleWired=true;
  function consumeOverlayRequests(){
    document.querySelectorAll("[data-gd-overlay-control][data-gd-overlay-request]").forEach(btn=>{
      const request=btn.getAttribute("data-gd-overlay-request")||"";
      if(!request)return;
      btn.removeAttribute("data-gd-overlay-request");
      const view=btn.dataset.gdOverlayControl||"compare";
      gdSetShotBubbleOverlay(view,request==="on"?true:request==="off"?false:!gdShotBubbleOverlayEnabled(view),null);
    });
  }
  document.addEventListener("click",event=>{
    const btn=event.target?.closest?.("[data-gd-overlay-toggle]");
    if(!btn)return;
    return gdShotBubbleOverlayClick(btn.dataset.gdOverlayView||"compare",event);
  },true);
  document.addEventListener("gd-shot-overlay-toggle",event=>{
    const btn=event.target?.closest?.("[data-gd-overlay-control]");
    if(!btn)return;
    return gdToggleShotBubbleOverlay(btn.dataset.gdOverlayControl||"compare",event);
  },true);
  if("MutationObserver" in window){
    const observer=new MutationObserver(list=>{
      list.forEach(mutation=>{
        if(mutation.type!=="attributes"||mutation.attributeName!=="data-gd-overlay-request")return;
        const btn=mutation.target?.closest?.("[data-gd-overlay-control]");
        if(!btn)return;
        const token=btn.getAttribute("data-gd-overlay-request")||"";
        if(!token||btn.__gdLastOverlayRequest===token)return;
        btn.__gdLastOverlayRequest=token;
        btn.removeAttribute("data-gd-overlay-request");
        const view=btn.dataset.gdOverlayControl||"compare";
        gdSetShotBubbleOverlay(view,token==="on"?true:token==="off"?false:!gdShotBubbleOverlayEnabled(view),null);
      });
    });
    observer.observe(document.documentElement,{subtree:true,attributes:true,attributeFilter:["data-gd-overlay-request"]});
  }
  if(typeof setInterval==="function")window.__gdShotBubbleOverlayRequestTimer=setInterval(consumeOverlayRequests,90);
  gdSyncShotBubbleOverlayControls();
}
window.gdSyncShotBubbleOverlayControls=gdSyncShotBubbleOverlayControls;
window.gdRenderShotBubbleOverlayView=gdRenderShotBubbleOverlayView;
