function gdShotBubbleNormaliseDrawable(generated,row={},offsetDeg=0){
  const distance=Number(row?.actualDistanceM);
  const sourceClub=gdBubbleClubForPresentation(row||generated||{});
  const generatedBase=generated||{};
  const offset=gdBubbleOffsetForSource({
    ...generatedBase,
    ...row,
    offsetDeg:Number.isFinite(Number(offsetDeg))?Number(offsetDeg):gdBubbleOffsetForSource(generatedBase)
  });
  const presentation=gdBubblePresentationForRender({
    ...(generatedBase||{}),
    ...(row||{}),
    club:sourceClub,
    distanceM:distance,
    offsetDeg:offset,
    handedness:gdBubbleHandednessForSource({...(generatedBase||{}),...(row||{})})
  },{normalizeAxes:true});
  if(!presentation)return null;
  const next=Object.assign({},generatedBase,row,{
    widthM:presentation.widthM,
    depthM:presentation.depthM,
    lateralRadiusM:presentation.lateralRadiusM,
    depthRadiusM:presentation.depthRadiusM,
    radiusM:presentation.radiusM,
    club:sourceClub,
    handedness:presentation.handedness,
    skewDeg:Number.isFinite(Number(row?.skewDeg))?Number(row.skewDeg):Number.isFinite(Number(generatedBase.skewDeg))?Number(generatedBase.skewDeg):0,
    offsetDeg:presentation.offsetDeg,
    visualYBias:Number.isFinite(Number(generatedBase.visualYBias))?Number(generatedBase.visualYBias):0,
    row
  });
  next.tiltDeg=presentation.tiltDeg;
  return next;
}
function gdShotBubbleOverlayBubbleParts(rows,offsetDeg){
  return (rows||[]).map(row=>{
    const distance=Number(row?.actualDistanceM);
    if(!Number.isFinite(distance)||distance<=0)return null;
    const bubble=gdGeneratedShotBubbleForClub(row.club,distance,offsetDeg);
    return bubble&&Number.isFinite(Number(bubble.baseDistanceM))?gdShotBubbleNormaliseDrawable(bubble,row,offsetDeg):null;
  }).filter(Boolean);
}
function gdShotBubbleOverlayLateralExtent(bubble){
  const scale=gdShotBubbleOverlayScale();
  const lateral=Math.max(1,Number(bubble?.lateralRadiusM)||Number(bubble?.widthM)/2||1)*scale;
  const depth=Math.max(1,Number(bubble?.depthRadiusM)||Number(bubble?.depthM)/2||1)*scale;
  const tilt=gdShotBubbleDisplayTiltDeg(bubble)*Math.PI/180;
  const skew=(Number(bubble?.skewDeg)||0)*Math.PI/180;
  return Math.abs(Number(bubble?.centerLateralM)||0)+Math.abs(Math.sin(tilt))*depth+Math.abs(Math.cos(tilt))*lateral+Math.abs(Math.tan(skew))*depth*.42+2;
}
function gdShotBubbleOverlayLateralMax(rows,offsetDeg){
  return Math.max(2,...gdShotBubbleOverlayBubbleParts(rows,offsetDeg).map(gdShotBubbleOverlayLateralExtent).filter(Number.isFinite));
}
function gdShotBubbleOverlayDistanceExtent(bubble){
  const scale=gdShotBubbleOverlayScale();
  const center=Number(bubble?.centerDistanceM)||Number(bubble?.baseDistanceM)||0;
  const lateral=Math.max(1,Number(bubble?.lateralRadiusM)||Number(bubble?.widthM)/2||1)*scale;
  const depth=Math.max(1,Number(bubble?.depthRadiusM)||Number(bubble?.depthM)/2||1)*scale;
  const tilt=gdShotBubbleDisplayTiltDeg(bubble)*Math.PI/180;
  return center+Math.abs(Math.cos(tilt))*depth+Math.abs(Math.sin(tilt))*lateral+4;
}
function gdShotBubbleOverlayDistanceExtentRows(rows,offsetDeg){
  return gdShotBubbleOverlayBubbleParts(rows,offsetDeg).map(bubble=>({
    club:bubble.club||bubble.row?.club||"Unknown",
    actualDistanceM:gdShotBubbleOverlayDistanceExtent(bubble),
    lateralM:0,
    hasLateral:false,
    projectionSource:"bubble-extent"
  })).filter(row=>Number.isFinite(Number(row.actualDistanceM))&&Number(row.actualDistanceM)>0);
}
function gdShotBubbleOverlayClamp(value,min,max){
  return Math.max(min,Math.min(max,Number(value)||0));
}
function gdShotBubbleOverlayBubblePath(bubble,plot,xForDistance,yForLateral){
  const scale=gdShotBubbleOverlayScale();
  const payload=bubble?.payload||{};
  const centerDistance=Number(bubble?.centerDistanceM)||Number(bubble?.baseDistanceM)||0;
  const centerLateral=Number(bubble?.centerLateralM)||0;
  const lateral=Math.max(1,Number(bubble?.lateralRadiusM)||Number(bubble?.widthM)/2||1)*scale;
  const depth=Math.max(1,Number(bubble?.depthRadiusM)||Number(bubble?.depthM)/2||1)*scale;
  const tilt=gdShotBubbleDisplayTiltDeg(bubble)*Math.PI/180;
  const skew=(Number(bubble?.skewDeg)||0)*Math.PI/180;
  const points=[];
  const steps=64;
  for(let i=0;i<steps;i++){
    const rel=(Math.PI*2*i)/steps;
    const radiusFactor=typeof bubbleRadiusFactor==="function"?bubbleRadiusFactor(rel,payload):1;
    const localX=Math.cos(rel)*depth*radiusFactor;
    const localY=Math.sin(rel)*lateral*radiusFactor;
    const skewedY=localY+Math.tan(skew)*localX*.42;
    const rotatedX=localX*Math.cos(tilt)-skewedY*Math.sin(tilt);
    const rotatedY=localX*Math.sin(tilt)+skewedY*Math.cos(tilt);
    points.push(`${xForDistance(centerDistance+rotatedX).toFixed(1)} ${yForLateral(centerLateral+rotatedY).toFixed(1)}`);
  }
  return points.length?`M ${points.join(" L ")} Z`:"";
}
function gdShotBubbleOverlayTypeStyle(source,view){
  const key=String(source||"").toLowerCase();
  if(key==="practice-bubble-projection")return{colour:"#37f28d",fillOpacity:".085",strokeOpacity:".76",strokeWidth:"1.55"};
  if(key==="offset-hub-underlay")return{colour:"#d7b06b",fillOpacity:".075",strokeOpacity:".62",strokeWidth:"1.35"};
  if(key==="gps-bubble"||view==="compare")return{colour:"#d7b06b",fillOpacity:".075",strokeOpacity:".62",strokeWidth:"1.35"};
  return{colour:"#d7b06b",fillOpacity:".08",strokeOpacity:".66",strokeWidth:"1.35"};
}
function gdShotBubbleOverlayLayerMarkup(rows,plot,view,opts={}){
  const maxBubbles=Math.max(1,Math.min(18,Math.round(Number(opts.maxBubbles)||12)));
  const bubbleRows=(Array.isArray(opts.referenceRows)?opts.referenceRows:gdShotBubbleOverlayReferenceRows(rows))
    .filter(row=>Number.isFinite(Number(row.actualDistanceM))&&Number(row.actualDistanceM)>0)
    .sort((a,b)=>String(a.club).localeCompare(String(b.club),undefined,{numeric:true}))
    .slice(0,maxBubbles);
  if(!bubbleRows.length)return "";
  const offsetDeg=Number.isFinite(Number(opts.offsetDeg))?Number(opts.offsetDeg):gdStatsCurrentModelOffsetDeg();
  const bubbles=gdShotBubbleOverlayBubbleParts(bubbleRows,offsetDeg);
  if(!bubbles.length)return "";
  const xForDistance=distance=>plot.plotLeft+((distance-plot.minDistance)/plot.distanceRange)*(plot.plotRight-plot.plotLeft);
  const yForLateral=lateral=>gdShotChartYForLateral(plot,lateral);
  const lineEndDistance=Math.max(...bubbles.map(bubble=>Number(bubble.centerDistanceM||bubble.baseDistanceM)).filter(Number.isFinite),Number(plot.maxDistance)||0);
  const lineEnd=Math.min(Number(plot.maxDistance)||lineEndDistance,lineEndDistance);
  const hubLine=view==="compare"?`<line class="gdOffsetHubOverlayLine" data-source="gps-target-line" x1="${plot.plotLeft.toFixed(1)}" y1="${plot.plotMidY.toFixed(1)}" x2="${xForDistance(lineEnd).toFixed(1)}" y2="${plot.plotMidY.toFixed(1)}" stroke="rgba(215,176,107,.58)" stroke-width="1.15" stroke-dasharray="7 6" stroke-linecap="round"/>`:"";
  const groupClass=opts.groupClass||`gdShotBubbleOverlayLayer${view==="compare"?" gdOffsetHubOverlayLayer":""}`;
  const source=opts.source||"gps-bubble";
  const typeStyle=gdShotBubbleOverlayTypeStyle(source,view);
  const colour=opts.colour||opts.color||typeStyle.colour;
  const fillOpacity=opts.fillOpacity||typeStyle.fillOpacity;
  const strokeOpacity=opts.strokeOpacity||typeStyle.strokeOpacity;
  const strokeWidth=opts.strokeWidth||typeStyle.strokeWidth;
  const groupStyle=opts.groupStyle?` style="${gdStatsSvgText(opts.groupStyle)}"`:"";
  return `<g class="${groupClass}" data-offset-deg="${Number(offsetDeg).toFixed(2)}"${groupStyle}>${hubLine}${bubbles.map(bubble=>{
    const club=bubble.club||bubble.row?.club||"Unknown";
    const path=gdShotBubbleOverlayBubblePath(bubble,plot,xForDistance,yForLateral);
    if(!path)return "";
    const sourceKey=String(source||"").toLowerCase();
    const labelWord=opts.labelText||(sourceKey==="practice-bubble-projection"?"PRACTICE":sourceKey==="my-bubble"?"MY":"");
    const showLabel=!!labelWord&&opts.label!==false&&bubbles.length===1;
    const label=showLabel?(()=>{
      const cx=xForDistance(Number(bubble.centerDistanceM)||Number(bubble.baseDistanceM)||0);
      const cy=yForLateral(Number(bubble.centerLateralM)||0);
      const radiusM=Math.max(3,Number(bubble.lateralRadiusM)||Number(bubble.widthM)/2||5);
      const labelRadiusPx=Math.abs(yForLateral((Number(bubble.centerLateralM)||0)+radiusM)-cy);
      const fontSize=Math.max(5.2,Math.min(7.4,labelRadiusPx*.44));
      const mid=cy.toFixed(1);
      const isMyBubble=sourceKey==="my-bubble";
      const mainFill=isMyBubble?"rgba(28,17,2,.86)":"rgba(0,14,8,.84)";
      const highFill=isMyBubble?"rgba(255,236,181,.24)":"rgba(160,255,201,.20)";
      const lowFill="rgba(0,0,0,.58)";
      const line=(word,y,dx,dy,fill,opacity="1")=>`<text x="${(cx+dx).toFixed(1)}" y="${(Number(y)+dy).toFixed(1)}" text-anchor="middle" dominant-baseline="middle" fill="${fill}" opacity="${opacity}" font-size="${fontSize.toFixed(1)}" font-weight="950" letter-spacing="0">${gdStatsSvgText(word)}</text>`;
      return `<g class="gdPracticeBubbleEmbossLabel" data-source="practice-bubble-label" pointer-events="none" aria-hidden="true">
        ${line(labelWord,mid,-.55,-.55,lowFill)}
        ${line(labelWord,mid,.55,.6,highFill)}
        ${line(labelWord,mid,0,0,mainFill)}
      </g>`;
    })():"";
    return `<path class="gdOffsetHubBubble" data-club="${gdStatsSvgText(club)}" data-source="${gdStatsSvgText(source)}" data-offset-deg="${Number(bubble.offsetDeg||0).toFixed(2)}" data-tilt-deg="${Number(bubble.tiltDeg||0).toFixed(2)}" data-base-distance-m="${Number(bubble.baseDistanceM||0).toFixed(1)}" d="${path}" fill="${colour}" fill-opacity="${fillOpacity}" stroke="${colour}" stroke-width="${strokeWidth}" stroke-opacity="${strokeOpacity}"/>${label}`;
  }).join("")}</g>`;
}
function gdShotBubbleOverlayLayer(rows,plot,view,opts={}){
  if(!gdShotBubbleOverlayEnabled(view))return "";
  return gdShotBubbleOverlayLayerMarkup(rows,plot,view,opts);
}
function gdOffsetHubUnderlayLayer(referenceRows,plot,view){
  const rows=(referenceRows||[]).filter(row=>Number.isFinite(Number(row.actualDistanceM))&&Number(row.actualDistanceM)>0);
  if(!rows.length)return "";
  return gdShotBubbleOverlayLayerMarkup([],plot,view,{
    referenceRows:rows,
    maxBubbles:rows.length,
    offsetDeg:gdStatsCurrentModelOffsetDeg(),
    groupClass:"gdShotBubbleOverlayLayer gdOffsetHubUnderlayLayer",
    source:"offset-hub-underlay",
    fillOpacity:".075",
    strokeOpacity:".62",
    strokeWidth:"1.35"
  });
}
function gdShotBubbleOverlayActualCourseDistance(record){
  const actual=Number(record?.actualDistanceM);
  if(Number.isFinite(actual))return actual;
  const expected=Number(record?.expectedDistanceM);
  const depth=Number(record?.depthM);
  if(Number.isFinite(expected)&&Number.isFinite(depth))return expected+depth;
  return Number.isFinite(expected)?expected:NaN;
}
function gdShotBubbleOverlayActualPracticeDistance(shot){
  const carry=Number(shot?.carryM);
  if(Number.isFinite(carry))return carry;
  const expected=Number(shot?.expectedM);
  const depth=Number(shot?.depthM);
  if(Number.isFinite(expected)&&Number.isFinite(depth))return expected+depth;
  return Number.isFinite(expected)?expected:NaN;
}
function gdShotBubbleOverlayLooksLikeClub(label){
  const value=String(label||"").trim().toLowerCase();
  return /^(driver|[1-9]w|[1-9]i|pw|gw|sw|lw)$/.test(value);
}
function gdShotBubbleOverlayVisibleClubRows(view){
  if(view==="compare")return [];
  const visual=gdShotBubbleOverlayContainer(view);
  if(!visual)return [];
  const clubs=[...new Set([...visual.querySelectorAll("svg text")]
    .map(node=>String(node.textContent||"").trim())
    .filter(gdShotBubbleOverlayLooksLikeClub))];
  if(!clubs.length)return [];
  const bagByClub={};
  gdShotBubbleOverlayBagRows().forEach(row=>{bagByClub[gdShotBubbleOverlayClubKey(row.club)]=row;});
  return clubs.map(club=>{
    const key=gdShotBubbleOverlayClubKey(club);
    const bag=bagByClub[key];
    if(bag)return Object.assign({},bag,{club});
    const defaultCarry=gdShotBubbleSafe(()=>typeof gdDefaultCarryForClub==="function"?gdDefaultCarryForClub(club):NaN,NaN);
    const carry=Number(defaultCarry);
    return Number.isFinite(carry)&&carry>0?{club,actualDistanceM:carry,lateralM:0}:null;
  }).filter(Boolean);
}
function gdShotBubbleOverlayRowsForView(view){
  if(view==="course"){
    const analysis=gdShotBubbleSafe(()=>typeof gdCurrentStatsAnalysis==="function"?gdCurrentStatsAnalysis():null,null)||{};
    const records=gdShotBubbleSafe(()=>typeof gdStatsFilteredRecords==="function"?gdStatsFilteredRecords(analysis):analysis.records,analysis.records)||[];
    const rows=gdShotBubbleOverlayDataRows((Array.isArray(records)?records:[]).map(record=>({
      club:record?.club||"Unknown",
      actualDistanceM:gdShotBubbleOverlayActualCourseDistance(record),
      lateralM:Number(record?.lateralM)||0
    })));
    return rows.length?rows:gdShotBubbleOverlayVisibleClubRows(view);
  }
  if(view==="practice"){
    const analysis=gdShotBubblePracticeAnalysis()||{};
    const shots=Array.isArray(analysis?.acceptedShots)?analysis.acceptedShots:[];
    const rows=gdShotBubbleOverlayDataRows(shots.map(shot=>({
      club:shot?.club||"Unknown",
      actualDistanceM:gdShotBubbleOverlayActualPracticeDistance(shot),
      lateralM:Number(shot?.lateralM)||0
    })));
    return rows.length?rows:gdShotBubbleOverlayVisibleClubRows(view);
  }
  const ctx=gdShotBubbleSafe(()=>typeof gdComparisonContext==="function"?gdComparisonContext():null,null)||{};
  const courseRows=gdShotBubbleSafe(()=>typeof gdCompareCoursePoints==="function"?gdCompareCoursePoints(ctx):[],[])||[];
  const practiceRows=gdShotBubbleSafe(()=>typeof gdComparePracticePoints==="function"?gdComparePracticePoints(ctx):[],[])||[];
  const rows=gdShotBubbleOverlayDataRows(courseRows.concat(practiceRows).filter(row=>row&&row.counted!==false&&!row.excluded));
  return rows.length?rows:gdShotBubbleOverlayVisibleClubRows(view);
}
function gdShotBubbleOverlayContainer(view){
  const id=view==="course"?"gdStatsVisual":view==="practice"?"gdPracticeDataVisual":"gdHubCompareDataVisual";
  return document.getElementById(id);
}
function gdApplyShotBubbleDomOverlay(view){
  view=["course","practice","compare"].includes(view)?view:"compare";
  const visual=gdShotBubbleOverlayContainer(view);
  if(!visual)return;
  visual.querySelectorAll(".gdShotBubbleDomOverlay").forEach(node=>node.remove());
  if(!gdShotBubbleOverlayEnabled(view))return;
  if(visual.querySelector("svg:not(.gdShotBubbleDomOverlay) .gdShotBubbleOverlayLayer"))return;
  const practiceAnalysis=view==="practice"?gdShotBubblePracticeAnalysis():null;
  const practiceOffset=view==="practice"&&typeof window.gdPracticeBubbleOffsetDeg==="function"?window.gdPracticeBubbleOffsetDeg(practiceAnalysis):null;
  const hasPracticeOffset=value=>typeof window.gdPracticeHasBubbleOffset==="function"?window.gdPracticeHasBubbleOffset(value):typeof value==="number"&&Number.isFinite(value);
  if(view==="practice"&&!hasPracticeOffset(practiceOffset))return;
  const dataRows=gdShotBubbleOverlayRowsForView(view);
  const overlayRows=(view==="practice"&&typeof window.gdPracticeProjectionRows==="function"?window.gdPracticeProjectionRows(dataRows,practiceAnalysis):gdShotBubbleOverlayReferenceRows(dataRows))
    .filter(row=>Number.isFinite(Number(row.actualDistanceM))&&Number(row.actualDistanceM)>0);
  if(!overlayRows.length)return;
  const plotLeft=30,plotRight=450,plotTop=82,plotBottom=224;
  const plot=gdShotChartLayout(dataRows,overlayRows,{plotLeft,plotRight,plotTop,plotBottom});
  const offset=view==="practice"?practiceOffset:gdStatsCurrentModelOffsetDeg();
  gdShotChartEnsureLateralRange(
    plot,
    gdShotBubbleOverlayLateralMax(overlayRows,offset),
    view==="practice"?gdShotBubbleOverlayLateralMax(overlayRows,gdStatsCurrentModelOffsetDeg()):0
  );
  const layer=view==="practice"
    ? gdOffsetHubUnderlayLayer(overlayRows,plot,view)+gdShotBubbleOverlayLayerMarkup(dataRows,plot,view,{
      referenceRows:overlayRows,
      maxBubbles:overlayRows.length,
      offsetDeg:offset,
      groupClass:"gdShotBubbleOverlayLayer gdPracticeBubbleProjectionLayer",
      source:"practice-bubble-projection"
    })
    : gdShotBubbleOverlayLayerMarkup(dataRows,plot,view,{offsetDeg:offset});
  if(!layer)return;
  visual.insertAdjacentHTML("beforeend",`<svg class="gdShotBubbleDomOverlay" viewBox="0 0 480 260" aria-hidden="true">${layer}</svg>`);
}
function gdShotBubbleOverlayStandaloneSvg(view,title,width=480,height=260){
  const practiceAnalysis=view==="practice"?gdShotBubblePracticeAnalysis():null;
  const practiceOffset=view==="practice"&&typeof window.gdPracticeBubbleOffsetDeg==="function"?window.gdPracticeBubbleOffsetDeg(practiceAnalysis):null;
  const hasPracticeOffset=value=>typeof window.gdPracticeHasBubbleOffset==="function"?window.gdPracticeHasBubbleOffset(value):typeof value==="number"&&Number.isFinite(value);
  const rows=view==="practice"&&hasPracticeOffset(practiceOffset)&&typeof window.gdPracticeProjectionRows==="function"?window.gdPracticeProjectionRows([],practiceAnalysis):gdShotBubbleOverlayReferenceRows([]);
  if(!gdShotBubbleOverlayEnabled(view)||!rows.length){
    const plot=gdShotChartLayout([],[],{plotLeft:30,plotRight:450,plotTop:82,plotBottom:224});
    return `<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${gdStatsSvgText(title)} visual">
      ${gdShotChartBackdropSvg(plot,title)}
    </svg>${gdShotBubbleOverlayButton(view)}`;
  }
  const plotLeft=30,plotRight=450,plotTop=82,plotBottom=224;
  const plot=gdShotChartLayout(rows,[],{plotLeft,plotRight,plotTop,plotBottom});
  const offset=view==="practice"?practiceOffset:gdStatsCurrentModelOffsetDeg();
  gdShotChartEnsureLateralRange(plot,gdShotBubbleOverlayLateralMax(rows,offset));
  const overlaySvg=view==="practice"
    ? gdOffsetHubUnderlayLayer(rows,plot,view)+gdShotBubbleOverlayLayerMarkup([],plot,view,{referenceRows:rows,maxBubbles:rows.length,offsetDeg:offset,groupClass:"gdShotBubbleOverlayLayer gdPracticeBubbleProjectionLayer",source:"practice-bubble-projection"})
    : gdShotBubbleOverlayLayer([],plot,view,{offsetDeg:offset});
  const clubKey=rows.map(row=>row.club).sort((a,b)=>String(a).localeCompare(String(b),undefined,{numeric:true})).slice(0,6);
  const clubKeySvg=clubKey.map((club,i)=>`<circle cx="${26+i*48}" cy="58" r="4.2" fill="${gdStatsClubColor(club)}"/><text x="${34+i*48}" y="61" fill="rgba(255,255,255,.68)" font-size="9" font-weight="850">${gdStatsSvgText(club)}</text>`).join("");
  return `<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${gdStatsSvgText(title)} visual">
    ${gdShotChartBackdropSvg(plot,title)}
    ${overlaySvg}
    ${clubKeySvg}
  </svg>${gdShotBubbleOverlayButton(view)}`;
}
function gdStatsShotTime(record){
  const time=Date.parse(record?.timestamp||"");
  return Number.isFinite(time)?time:0;
}
function gdStatsCutoffTime(range){
  const now=Date.now();
  if(range==="3m")return now-92*24*60*60*1000;
  if(range==="6m")return now-183*24*60*60*1000;
  if(range==="12m")return now-366*24*60*60*1000;
  return 0;
}
function gdStatsTimeColor(record, records){
  const times=(records||[]).map(gdStatsShotTime).filter(Boolean).sort((a,b)=>a-b);
  if(!times.length)return "#9aa4b2";
  const t=gdStatsShotTime(record);
  if(!t)return "#9aa4b2";
  const min=times[0],max=times[times.length-1];
  const bucket=max===min?Math.floor(gdStatsTimePalette.length/2):Math.max(0,Math.min(gdStatsTimePalette.length-1,Math.floor(((t-min)/(max-min))*gdStatsTimePalette.length)));
  return gdStatsTimePalette[bucket];
}
function gdStatsMedian(values){
  const sorted=(values||[]).map(Number).filter(Number.isFinite).sort((a,b)=>a-b);
  if(!sorted.length)return 0;
  const mid=Math.floor(sorted.length/2);
  return sorted.length%2?sorted[mid]:(sorted[mid-1]+sorted[mid])/2;
}
function gdStatsClubLatest(records, club){
  return Math.max(0,...(records||[]).filter(r=>r.club===club).map(gdStatsShotTime));
}
function gdStatsFilterChanged(){
  gdStatsView={
    club:document.getElementById("gdStatsClubFilter")?.value||"all",
    minDistance:document.getElementById("gdStatsMinDistance")?.value||"",
    maxDistance:document.getElementById("gdStatsMaxDistance")?.value||"",
    dateRange:document.getElementById("gdStatsDateRange")?.value||"all",
    colourMode:document.getElementById("gdStatsColourMode")?.value||"club",
    sort:document.getElementById("gdStatsSort")?.value||"club"
  };
  renderStats();
}
function gdStatsSelectClub(club){
  gdStatsView.club=club||"all";
  const select=document.getElementById("gdStatsClubFilter");
  if(select)select.value=gdStatsView.club;
  renderStats();
}
function gdStatsFilteredRecords(analysis){
  const hasMin=String(gdStatsView.minDistance||"").trim()!=="";
  const hasMax=String(gdStatsView.maxDistance||"").trim()!=="";
  const min=Number(gdStatsView.minDistance);
  const max=Number(gdStatsView.maxDistance);
  const cutoff=gdStatsCutoffTime(gdStatsView.dateRange);
  return (analysis?.records||[]).filter(r=>{
    if(gdStatsView.club&&gdStatsView.club!=="all"&&r.club!==gdStatsView.club)return false;
    if(hasMin&&Number.isFinite(min)&&r.actualDistanceM<min)return false;
    if(hasMax&&Number.isFinite(max)&&r.actualDistanceM>max)return false;
    if(cutoff&&gdStatsShotTime(r)&&gdStatsShotTime(r)<cutoff)return false;
    return true;
  });
}
function gdStatsPopulateFilters(analysis){
  const clubSelect=document.getElementById("gdStatsClubFilter");
  const minInput=document.getElementById("gdStatsMinDistance");
  const maxInput=document.getElementById("gdStatsMaxDistance");
  const dateSelect=document.getElementById("gdStatsDateRange");
  const colourSelect=document.getElementById("gdStatsColourMode");
  const sortSelect=document.getElementById("gdStatsSort");
  if(minInput&&document.activeElement!==minInput)minInput.value=gdStatsView.minDistance;
  if(maxInput&&document.activeElement!==maxInput)maxInput.value=gdStatsView.maxDistance;
  if(dateSelect)dateSelect.value=gdStatsView.dateRange;
  if(colourSelect)colourSelect.value=gdStatsView.colourMode;
  if(sortSelect)sortSelect.value=gdStatsView.sort;
  if(!clubSelect)return;
  const clubs=[...new Set((analysis?.records||[]).map(r=>r.club||"Unknown"))].sort((a,b)=>{
    if(a==="Unknown")return 1;
    if(b==="Unknown")return -1;
    return a.localeCompare(b,undefined,{numeric:true});
  });
  const current=gdStatsView.club||"all";
  clubSelect.innerHTML=`<option value="all">All clubs</option>`+clubs.map(club=>`<option value="${gdEscapeHTML(club)}">${gdEscapeHTML(club)}</option>`).join("");
  clubSelect.value=clubs.includes(current)?current:"all";
  gdStatsView.club=clubSelect.value;
}
function gdStatsAnalysisForRecords(records, settings){
  const api=window.GolfDaddyShotClusterAnalysis;
  if(!api||!Array.isArray(records))return null;
  const cfg=Object.assign({},settings||{});
  return {
    bubbleFit:api.analyzeBubbleFit?api.analyzeBubbleFit(records,cfg,gdStatsConsistencyPct):[],
    bubbleFitRange:api.analyzeBubbleFitRange?api.analyzeBubbleFitRange(records,Object.assign({},cfg,{consistencyDefaultPct:gdStatsConsistencyPct})):[],
    clusterHunter:api.analyzeClusterHunter?api.analyzeClusterHunter(records,cfg):null
  };
}
function gdStatsVisualSummary(analysis, filteredRecords, filteredAnalysis){
  const visual=document.getElementById("gdStatsVisual");
  if(!visual)return;
  const records=filteredRecords||[];
  const width=480,height=260;
  const fitSource=filteredAnalysis?.bubbleFit||analysis?.bubbleFit||[];
  const fit=fitSource.slice().sort((a,b)=>(b.shots||0)-(a.shots||0))[0];
  const modelFit=fit||((analysis?.bubbleFit||[]).slice().sort((a,b)=>(b.shots||0)-(a.shots||0))[0])||null;
  const hasVisualData=!!records.length;
	  if(!hasVisualData){
	    visual.innerHTML=gdShotBubbleOverlayStandaloneSvg("course",gdShotDataGraphTitle("Course Data"),width,height);
    return;
  }
  const fitsByClub={};
  fitSource.forEach(item=>{fitsByClub[item.club]=item});
  const showAllClubs=(gdStatsView.club||"all")==="all";
  const plotLeft=30;
  const plotRight=450;
  const plotTop=82;
  const plotBottom=224;
  const plotMidY=(plotTop+plotBottom)/2;
  const actualDistanceForRecord=r=>{
    const actual=Number(r.actualDistanceM);
    if(Number.isFinite(actual))return actual;
    const expected=Number(r.expectedDistanceM);
    const depth=Number(r.depthM);
    if(Number.isFinite(expected)&&Number.isFinite(depth))return expected+depth;
    return Number.isFinite(expected)?expected:NaN;
  };
  const dataRows=records.map((r,index)=>{
    const actual=actualDistanceForRecord(r);
    const lateral=gdShotChartLateralInfo(r,actual);
    return {club:r.club||"Unknown",actualDistanceM:actual,lateralM:lateral.value,hasLateral:lateral.hasLateral,counted:r.counted!==false,excluded:r.counted===false,record:r,index};
  }).filter(row=>Number.isFinite(row.actualDistanceM)&&row.actualDistanceM>0);
  const overlayRows=gdShotBubbleOverlayEnabled("course")?gdShotBubbleOverlayReferenceRows(dataRows):[];
  const hubRows=gdShotBubbleOverlayReferenceRows(dataRows);
  const hubDomainRows=hubRows.length?gdShotBubbleOverlayDistanceExtentRows(hubRows,gdStatsCurrentModelOffsetDeg()):[];
  const plot=gdShotChartLayout(dataRows,overlayRows.concat(hubDomainRows),{plotLeft,plotRight,plotTop,plotBottom});
  if(gdShotBubbleOverlayEnabled("course")||hubRows.length)gdShotChartEnsureLateralRange(
    plot,
    gdShotBubbleOverlayEnabled("course")?gdShotBubbleOverlayLateralMax(dataRows,gdStatsCurrentModelOffsetDeg()):0,
    hubRows.length?gdShotBubbleOverlayLateralMax(hubRows,gdStatsCurrentModelOffsetDeg()):0
  );
  const shotDots=dataRows.map(row=>{
    const r=row.record;
    const point=gdShotChartPoint(plot,row.actualDistanceM,row.lateralM,row.index,row.hasLateral);
    const clubColor=gdStatsClubColor(row.club);
    const timeColor=gdStatsTimeColor(r,records);
    const shotColor=gdStatsView.colourMode==="time"?timeColor:clubColor;
    const fill=r.counted?shotColor:"#8f9a96";
    const op=r.counted?".82":".18";
    return gdShotChartDotSvg(point,{fill,opacity:op,radius:r.counted?2.6:1.8,missing:row.hasLateral===false});
  }).join("");
  const clubKey=showAllClubs?[...new Set(records.map(r=>r.club||"Unknown"))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true})).slice(0,6):[];
  const clubKeySvg=clubKey.map((club,i)=>`<circle cx="${26+i*48}" cy="58" r="4.2" fill="${gdStatsClubColor(club)}"/><text x="${34+i*48}" y="61" fill="rgba(255,255,255,.68)" font-size="9" font-weight="850">${gdStatsSvgText(club)}</text>`).join("");
  const timeKeySvg=gdStatsTimePalette.map((color,i)=>`<circle cx="${26+i*52}" cy="58" r="4.2" fill="${color}"/><text x="${34+i*52}" y="61" fill="rgba(255,255,255,.68)" font-size="9" font-weight="850">${i===0?"old":i===gdStatsTimePalette.length-1?"new":""}</text>`).join("");
  const hubUnderlaySvg=hubRows.length?gdOffsetHubUnderlayLayer(hubRows,plot,"course"):"";
  const overlaySvg=gdShotBubbleOverlayLayer(dataRows,plot,"course",{offsetDeg:gdStatsCurrentModelOffsetDeg()});
  const clubOvals=gdShotChartFitOvalsSvg(plot,fitSource,dataRows,{source:"course"})||gdShotChartClubOvalsSvg(plot,dataRows);
  visual.innerHTML=`
    <svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Shot pattern stats visual">
      ${gdShotChartBackdropSvg(plot,gdShotDataGraphTitle("Course Data"))}
      ${hubUnderlaySvg}
      ${overlaySvg}
      ${clubOvals}
      ${shotDots}
      ${gdStatsView.colourMode==="time"?timeKeySvg:clubKeySvg}
    </svg>${gdShotBubbleOverlayButton("course")}`;
}
// Course Shot Library: same organisation as the practice Clarity Shot
// Library - a shell with club sections that expand to show individual shots
// (with their round/hole provenance), instead of the old flat filter list.
const gdCourseLibraryOpenClubs={};
function gdCourseLibraryToggleClub(el){
  const club=el?.dataset?.gdCourseClub;
  if(club)gdCourseLibraryOpenClubs[club]=!!el.open;
}
function gdCourseShotDateLabel(record){
  const t=safe(()=>typeof gdStatsShotTime==="function"?gdStatsShotTime(record):Date.parse(record?.at||record?.time||record?.timestamp||0),0)||0;
  if(!t)return "";
  try{return new Date(t).toLocaleDateString(undefined,{day:"numeric",month:"short"});}catch(e){return "";}
}
function gdRenderCourseClubGroups(list, records, filteredAnalysis, cfg){
  const rows=records||[];
  const bubbleValue=safe(()=>gdCourseBubbleValueLabel(filteredAnalysis,filteredAnalysis,rows),"-");
  if(!rows.length){
    list.innerHTML=gdShotDataLibraryShellHTML({
      kind:"course",
      title:"Course Shot Library",
      bubbleLabel:"Course Bubble",
      bubbleValue,
      count:0,
      bodyHTML:`<div class="gdPracticeEvidenceHead"><div><strong>Course Shot Library</strong><span>Paired GPS course shots will appear here, filed by club.</span></div></div>`,
      dropdown:true,
      open:gdShotDataLibraryIsOpen("course")
    });
    return;
  }
  const grouped={};
  rows.forEach(record=>{
    const club=record.club||"Unknown";
    grouped[club]=grouped[club]||[];
    grouped[club].push(record);
  });
  const fitsByClub={};
  (filteredAnalysis?.bubbleFit||[]).forEach(item=>{fitsByClub[item.club]=item;});
  const clustersByClub={};
  (filteredAnalysis?.clusterHunter?.byClub||[]).forEach(item=>{clustersByClub[item.club]=item;});
  const clubs=Object.keys(grouped).sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}));
  const sections=clubs.map((club,index)=>{
    const clubRows=grouped[club].slice().sort((a,b)=>gdStatsShotTime(b)-gdStatsShotTime(a));
    const fit=fitsByClub[club]||{};
    const cluster=clustersByClub[club]||{};
    const counted=clubRows.filter(row=>row.counted).length;
    const offset=Number.isFinite(Number(cluster.meanDeg))?cluster.meanDeg:Number(fit.resultBubble?.normalizedDeg||0);
    const open=gdCourseLibraryOpenClubs[club]!==undefined?!!gdCourseLibraryOpenClubs[club]:index===0;
    const shotRows=clubRows.map(record=>{
      const meta=[gdCourseShotDateLabel(record),record.holeId||record.roundId||""].filter(Boolean).join(" · ");
      return `<div class="bagRow gdClubShotRow ${record.counted?"":"filtered"}"><span>${Number(record.actualDistanceM||0).toFixed(0)}m · ${record.counted?"counted":"filtered"}${meta?` · ${gdEscapeHTML(meta)}`:""}</span><strong>${gdOffsetLabel(record.normalizedDeg||0)}</strong></div>`;
    }).join("");
    return `<details class="gdCourseLibraryClub" data-gd-course-club="${gdEscapeHTML(club)}" ${open?"open":""} ontoggle="gdCourseLibraryToggleClub(this)"><summary class="bagRow gdClubGroupRow"><span>${gdEscapeHTML(club)} · ${counted}/${clubRows.length} counted${fit.shots?` · ${Math.round(fit.consistencyPct||gdStatsConsistencyPct)}% fit`:""}</span><strong>${gdOffsetLabel(offset||0)}</strong></summary><div class="gdCourseLibraryClubRows">${shotRows}</div></details>`;
  }).join("");
  list.innerHTML=gdShotDataLibraryShellHTML({
    kind:"course",
    title:"Course Shot Library",
    bubbleLabel:"Course Bubble",
    bubbleValue,
    count:rows.length,
    bodyHTML:sections,
    dropdown:true,
    open:gdShotDataLibraryIsOpen("course")
  });
}
function gdRenderStatsAnalysis(list){
  try{
    const analysis=gdCurrentStatsAnalysis();
    if(!analysis)return false;
    gdStatsPopulateFilters(analysis);
    const filteredRecords=gdStatsFilteredRecords(analysis);
    const filteredAnalysis=gdStatsAnalysisForRecords(filteredRecords,analysis.settings)||analysis;
    document.getElementById("statsPanel")?.classList.toggle("gdStatsEmpty",!filteredRecords.length);
    gdRenderCourseDataLanding(analysis,filteredRecords,filteredAnalysis);
    gdStatsVisualSummary(analysis,filteredRecords,filteredAnalysis);
    const cfg=analysis.settings;
    const slider=document.getElementById("gdStatsConsistency");
    const label=document.getElementById("gdStatsConsistencyLabel");
    const hint=document.getElementById("gdStatsFitHint");
    const clampedPct=gdStatsClampConsistency(gdStatsConsistencyPct,cfg);
    if(clampedPct!==gdStatsConsistencyPct){
      gdStatsConsistencyPct=clampedPct;
      try{localStorage.setItem("gd_stats_consistency_pct",String(gdStatsConsistencyPct))}catch(e){}
    }
    if(slider){
      slider.min=Math.round(cfg.consistencyMinPct);
      slider.max=Math.round(cfg.consistencyMaxPct);
      slider.value=String(gdStatsConsistencyPct);
    }
    if(label)label.textContent=`${gdStatsConsistencyPct}%`;
    const topFit=(filteredAnalysis.bubbleFit||[]).slice().sort((a,b)=>(b.shots||0)-(a.shots||0))[0];
    if(hint)hint.textContent=topFit?`${topFit.club} ${gdStatsGuidanceLabel(topFit.fitGuidance,topFit.sizeDeltaPct)}`:"Shot Data fit";
    gdRenderCourseClubGroups(list,filteredRecords,filteredAnalysis,cfg);
    return true;
  }catch(e){
    console.warn("[GolfDaddy] stats analysis render skipped",e);
    return false;
  }
}
function gdStatsHeaderText(analysis){
  if(!analysis)return shotTracking?`${trackedShots.length} shots logged`:"Shot tracking off";
  const rawCount=(analysis.records||[]).length;
  const shownCount=gdStatsFilteredRecords(analysis).length;
  if(shownCount)return `${shownCount} paired results · cluster rules active`;
  if(rawCount)return `${rawCount} stored · no paired results shown`;
  return "No paired results yet";
}
function renderStats(){
  const stats=gdCurrentStatsAnalysis();
  document.getElementById("statsSub").textContent=gdShotDataSubLabel(gdStatsHeaderText(stats));
  const list=document.getElementById("shotLogList");
  list.classList.add("gdCourseLibraryRows","gdShotDataLibraryBody","gdCourseLibraryBody");
  list.innerHTML="";
  if(gdRenderStatsAnalysis(list)){gdRenderCourseDataAdminPanel();return;}
  gdRenderCourseDataLanding(stats,[],stats);
  trackedShots.slice().reverse().forEach(s=>{const v=fmt(s.distanceM);const row=document.createElement("div");row.className="bagRow";row.innerHTML=`<span>Shot ${s.id} · ${s.reason}</span><strong>${v.value}${v.unit}</strong>`;list.appendChild(row)})
  gdRenderCourseDataAdminPanel();
}
